"""Прототипы ОГЭ по физике 2027, задания 1–22 (id ph-oge-NN-slug).

План КИМ ОГЭ 2027 (спецификация, обобщённый план):
 1 — соответствие «понятие/величина → пример/единица/определение» (2 б.); 2 — устройство → явление/закономерность,
 величина → прибор (2 б.); 3 — распознать явление (1 б.); 4 — текст с пропусками (2 б.); 5 — объяснение явления,
 выбор ответа с обоснованием (1 б.); 6–7 — расчёт, механика; 8 — тепловые явления; 9–10 — электромагнитные явления
 (9 — электричество, 10 — магнетизм, волны, оптика); 11 — квантовые явления; 12 — изменение величин (механика,
 тепловые); 13 — изменение величин (электромагнитные, квантовые); 14 — график/таблица, два верных утверждения (2 б.);
 15 — прямые измерения, выбор установки (1 б.); 16 — анализ опытов, два верных вывода (2 б.); 17 — эксперимент (3 б.);
 18 — текст + качественный вопрос (2 б.); 19 — качественная задача (2 б.); 20–22 — расчётные задачи (3 б.).

Тексты условий — свои (не пересказ банка ФИПИ); справочные данные — как на странице справочных данных КИМ ОГЭ.
"""
