def F(answer_format, style, level, time_min, scale, trap, kes, score):
    """Поля соответствия КИМ ОГЭ 2027 (см. BRIEF: главный критерий приёмки)."""
    return dict(answer_format=answer_format, style=style, level=level, time_min=time_min, scale=scale, trap=trap,
                kes=kes, score=score)


SC2 = '2 балла; 1 балл, если неверна одна позиция ответа'
SC2M = '2 балла; 1 балл, если один символ лишний/неверный или один отсутствует; порядок цифр не важен'
SC1 = '1 балл за полное совпадение с эталоном'
SC3 = '3 балла по критериям (полное решение: Дано, законы, преобразования, числовой ответ)'
MATCH_FMT = 'последовательность цифр по буквам (соответствие), цифры могут повторяться'
NUM_FMT = 'число (целое или конечная десятичная дробь) в указанных единицах, без единиц в ответе'


def pick(rng, xs, k):
    return rng.sample(list(xs), k)


def shuffled(rng, xs):
    xs = list(xs)
    rng.shuffle(xs)
    return xs


def match_answer(lefts, rights, rel):
    """Ответ-соответствие: для каждой левой позиции — номер правой, для которой rel(left, right) истинно (ровно одна)."""
    a = {}
    for i, l in enumerate(lefts):
        js = [j for j, r in enumerate(rights) if rel(l, r)]
        if len(js) != 1:
            raise ValueError(f'неоднозначно: {l} → {js}')
        a[LET[i]] = str(js[0] + 1)
    return a


def one_answer(options, right):
    return str(options.index(right) + 1)


