def _solve_unit(p):
    return match_answer(p['left'], p['right'], lambda l, r: QUANT[l][0] == r)


UNIT_HEAD = [
    'Установите соответствие между физическими величинами и единицами, в которых эти величины выражаются в СИ.',
    'Установите соответствие между физическими величинами и их основными единицами в СИ.',
]


def _pick_distinct(rng, keys, k, val, pool_vals, nbad):
    """k ключей с различными значениями val + nbad «лишних» значений, не совпадающих ни с одним выбранным."""
    for _ in range(100):
        L = pick(rng, keys, k)
        vals = [val(x) for x in L]
        if len(set(vals)) < k:
            continue
        pool = sorted(set(pool_vals) - set(vals))
        if len(pool) < nbad:
            continue
        return L, vals, pick(rng, pool, nbad)
    raise Retry


@proto('ph-oge-01-quantity-unit', 'ОГЭ', 1, 'Физическая величина → единица в СИ',
       invariant='три величины (часто одного раздела) и пять единиц СИ; две единицы лишние',
       varies='раздел (механика, тепловые, электрические явления, оптика), набор величин, порядок',
       answer_rule='каждой величине — её единица в СИ',
       mistakes=['единица мощности и работы (Вт/Дж)', 'удельные теплоты: Дж/кг и Дж/(кг·°С)', 'момент силы Н·м и работа Дж'],
       solve=_solve_unit, kind='dict', kes=['1.2', '1.8', '1.17', '2.8', '3.6', '3.8', '3.10'],
       fidelity=F(MATCH_FMT + ' (3 позиции, 5 вариантов)', 'как в банке: «единица величины в СИ», единица в виде '
                  '«ньютон (1 Н)»', 'Б', 2, 'величины курса 7–9 кл., как в банке', 'близкие единицы (Дж/кг и '
                  'Дж/(кг·°С), Дж и Вт, Н и Н·м)', '1.1–3.25', SC2))
def g_unit(rng):
    sec = rng.choice([1, 2, 3, 0])
    keys = [k for k, v in QUANT.items() if sec == 0 or v[3] == sec]
    L, vals, bad = _pick_distinct(rng, keys, 3, lambda x: QUANT[x][0], [v[0] for v in QUANT.values()], 2)
    right = shuffled(rng, vals + bad)
    q = rng.choice(UNIT_HEAD) + TAIL_MATCH + '\nФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ЕДИНИЦЫ'
    a = match_answer(L, right, lambda l, r: QUANT[l][0] == r)
    e = '; '.join(f'{x} — {QUANT[x][0]}' for x in L) + '.'
    return pcard('ph-oge-01-quantity-unit', q, a, e, k='match', o=match_opts(L, right), p={'left': L, 'right': right})


def _solve_def(p):
    return match_answer(p['left'], p['right'], lambda l, r: QUANT[l][1] == r)


@proto('ph-oge-01-quantity-definition', 'ОГЭ', 1, 'Физическая величина → определение',
       invariant='три величины и пять формулировок определений; две формулировки лишние',
       varies='раздел, набор величин, порядок; «лишние» определения — от других величин того же раздела',
       answer_rule='каждой величине — её определение',
       mistakes=['удельная теплоёмкость ↔ количество теплоты', 'сила тока ↔ напряжение', 'путь ↔ перемещение'],
       solve=_solve_def, kind='dict', kes=['1.1–1.19', '2.6–2.13', '3.6–3.10'],
       fidelity=F(MATCH_FMT + ' (3 позиции, 5 вариантов)', 'как в банке: «физические величины и их определения»',
                  'Б', 2, 'определения из учебника 7–9 кл. (своими словами)', 'похожие определения соседних величин',
                  '1.1–3.25', SC2))
def g_def(rng):
    sec = rng.choice([1, 2, 3])
    keys = [k for k, v in QUANT.items() if v[3] == sec]
    L, vals, bad = _pick_distinct(rng, keys, 3, lambda x: QUANT[x][1], [v[1] for v in QUANT.values() if v[3] == sec], 2)
    right = shuffled(rng, vals + bad)
    q = 'Установите соответствие между физическими величинами и их определениями (формулировками).' + TAIL_MATCH
    q += '\nФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ОПРЕДЕЛЕНИЯ'
    a = match_answer(L, right, lambda l, r: QUANT[l][1] == r)
    e = '; '.join(f'{x} — {QUANT[x][1]}' for x in L) + '.'
    return pcard('ph-oge-01-quantity-definition', q, a, e, k='match', o=match_opts(L, right), p={'left': L, 'right': right})


def _solve_formula(p):
    return match_answer(p['left'], p['right'], lambda l, r: QUANT[l][2] == r)


@proto('ph-oge-01-quantity-formula', 'ОГЭ', 1, 'Физическая величина → формула для её расчёта',
       invariant='три величины и пять формул; две формулы лишние',
       varies='раздел, набор величин, порядок',
       answer_rule='каждой величине — формула, по которой её рассчитывают',
       mistakes=['p = F/S и p = mυ (давление и импульс)', 'N = A/t и A = Fs', 'I = q/t и q = It'],
       solve=_solve_formula, kind='dict', kes=['1.1–1.19', '2.8', '3.6–3.10'],
       fidelity=F(MATCH_FMT + ' (3 позиции, 5 вариантов)', 'по спецификации 2027 №1 («обозначения величин»), формулы — '
                  'как в учебнике', 'Б', 2, 'формулы курса 7–9 кл.', 'одинаковые буквы у разных величин (p — давление '
                  'и импульс)', '1.1–3.25', SC2))
def g_formula(rng):
    keys = [k for k, v in QUANT.items() if v[2] != '—']
    L, vals, bad = _pick_distinct(rng, keys, 3, lambda x: QUANT[x][2], [v[2] for v in QUANT.values() if v[2] != '—'], 2)
    right = shuffled(rng, vals + bad)
    q = 'Установите соответствие между физическими величинами и формулами, по которым эти величины определяются.'
    q += TAIL_MATCH + '\nФИЗИЧЕСКИЕ ВЕЛИЧИНЫ — ФОРМУЛЫ'
    a = match_answer(L, right, lambda l, r: QUANT[l][2] == r)
    e = '; '.join(f'{x}: {QUANT[x][2]}' for x in L) + '.'
    return pcard('ph-oge-01-quantity-formula', q, a, e, k='match', o=match_opts(L, right), p={'left': L, 'right': right})


