EXTRA_PHEN = {'h': ['изменение давления газа при нагревании'], 't': ['превращение механической энергии во внутреннюю'],
              'e': ['химическое действие электрического тока'], 'o': ['поглощение света'], 's': ['резонанс']}


def _solve_devphen(p):
    return match_answer(p['left'], p['right'], lambda l, r: DEV_PHEN[l][0] == r)


def _dev_card(pid, rng, table, extra, head, cols):
    grp = rng.choice(sorted({v[1] for v in table.values()}))
    keys = [k for k, v in table.items() if v[1] == grp] if rng.random() < 0.8 else list(table)
    pool = [v[0] for k, v in table.items() if v[1] == grp] + extra.get(grp, [])
    L, vals, bad = _pick_distinct(rng, keys, 2, lambda x: table[x][0], pool, 2)
    right = shuffled(rng, vals + bad)
    q = head + TAIL_MATCH + '\n' + cols
    a = match_answer(L, right, lambda l, r: table[l][0] == r)
    e = '; '.join(f'{x} — {table[x][0]}' for x in L) + '.'
    return pcard(pid, q, a, e, k='match', o=match_opts(L, right), p={'left': L, 'right': right})


@proto('ph-oge-02-device-phenomenon', 'ОГЭ', 2, 'Техническое устройство → явление в основе его действия',
       invariant='два устройства и четыре явления; два явления лишние',
       varies='область (гидростатика, тепловые, электромагнитные, оптика, звук), устройства, порядок',
       answer_rule='каждому устройству — явление, на котором основано его действие',
       mistakes=['генератор ↔ двигатель (индукция и сила Ампера)', 'лупа ↔ перископ (преломление и отражение)',
                 'насос ↔ пресс (атмосферное давление и закон Паскаля)'],
       solve=_solve_devphen, kind='dict', kes=['1.21', '1.22', '2.2', '2.7', '2.13', '3.10', '3.12', '3.14', '3.15', '3.21', '3.22', '3.24'],
       fidelity=F(MATCH_FMT + ' (2 позиции, 4 варианта)', 'как в демоверсии 2027 №2: «технические устройства и '
                  'физические явления, лежащие в основе их работы»', 'Б', 2, 'устройства из банка и учебника 7–9 кл.',
                  'генератор/двигатель, отражение/преломление', '1–4', SC2))
def g_devphen(rng):
    head = 'Установите соответствие между техническими устройствами и физическими явлениями, на которых основано их действие.'
    return _dev_card('ph-oge-02-device-phenomenon', rng, DEV_PHEN, EXTRA_PHEN, head, 'УСТРОЙСТВА — ЯВЛЕНИЯ')


