@proto('ph-oge-02-device-law', 'ОГЭ', 2, 'Прибор → физическая закономерность в основе его действия',
       invariant='два прибора и четыре закономерности; две закономерности лишние',
       varies='область (механика, тепловые, электричество), приборы, порядок',
       answer_rule='каждому прибору — закономерность, на которой основан принцип его действия',
       mistakes=['манометр ↔ барометр', 'динамометр ↔ весы', 'амперметр ↔ электрометр'],
       solve=_solve_devlaw, kind='dict', kes=['1.13', '1.20', '1.21', '2.2', '2.10', '3.1', '3.7', '3.12', '3.14'],
       fidelity=F(MATCH_FMT + ' (2 позиции, 4 варианта)', 'как в банке: «технические устройства и физические '
                  'закономерности, лежащие в основе принципа их действия»', 'Б', 2, 'приборы школьной лаборатории',
                  'близкие приборы одной области', '1–3', SC2))
def g_devlaw(rng):
    head = 'Установите соответствие между приборами и физическими закономерностями, на которых основан принцип их действия.'
    return _dev_card('ph-oge-02-device-law', rng, DEV_LAW, EXTRA_LAW, head, 'ПРИБОРЫ — ЗАКОНОМЕРНОСТИ')


