# =====================================================================================================================
# ЗАДАНИЕ 4. Текст с пропусками: вставить слова из списка (соответствие, 4 пропуска, 7–8 слов)
# =====================================================================================================================

HEAD4 = 'Прочитайте текст и вставьте на места пропусков слова (словосочетания) из приведённого списка.'
TAIL4 = ' Запишите в таблицу выбранные цифры под соответствующими буквами.'


def _gap_card(pid, rng, text, right_words, decoys, p, e):
    """right_words — слова для (А)…(Г) по порядку; decoys — лишние слова. Список перемешивается."""
    words = shuffled(rng, right_words + decoys)
    left = [f'({LET[i]})' for i in range(len(right_words))]
    a = {LET[i]: str(words.index(w) + 1) for i, w in enumerate(right_words)}
    p = dict(p, words=words)
    return pcard(pid, f'{HEAD4}\n{text}\nСписок слов и словосочетаний — во втором столбце.{TAIL4}', a, e,
                 k='match', o=match_opts(left, words), p=p)


def _ans_by_words(p, need):
    return {LET[i]: str(p['words'].index(w) + 1) for i, w in enumerate(need)}


# --- 4a. электризация через влияние: притяжение незаряженного тела
OBJ4A = [  # (к чему, кто — ед./мн., мн.ч., чего)
    ('тонкой струйке воды, текущей из крана', 'струйка воды', 0, 'струйки'),
    ('лёгкой гильзе из металлической фольги, подвешенной на шёлковой нити', 'гильза', 0, 'гильзы'),
    ('мелким обрывкам папиросной бумаги, лежащим на столе', 'обрывки бумаги', 1, 'обрывков бумаги'),
    ('лёгкому шарику из фольги, подвешенному на капроновой нити', 'шарик', 0, 'шарика'),
    ('мыльному пузырю, лежащему на столе', 'мыльный пузырь', 0, 'мыльного пузыря'),
    ('пустой алюминиевой банке из-под напитка, лежащей на боку', 'банка', 0, 'банки'),
]
ROD4A = [('палочку', 'палочке', 'палочки'), ('пластмассовую линейку', 'линейке', 'линейки'),
         ('расчёску', 'расчёске', 'расчёски'), ('надутый воздушный шарик', 'шарику', 'шарика')]



def _solve_4a(p):
    sign = p['sign']
    pl = p['plural']
    att = 'притягиваются' if pl else 'притягивается'
    near = 'положительный заряд' if sign < 0 else 'отрицательный заряд'
    return _ans_by_words(p, [att, 'электризации через влияние', 'перераспределяются', near])


@proto('ph-oge-04-electrostatic-induction', 'ОГЭ', 4, 'Текст с пропусками: притяжение незаряженного тела к заряженному',
       invariant='заряженное тело подносят, не касаясь, к незаряженному: притяжение, электризация через влияние, '
                 'перераспределение зарядов, на ближней стороне — заряд противоположного знака',
       varies='тело (струя воды, гильза, бумага, банка, пузырь), чем заряжают, знак заряда, порядок слов в списке',
       answer_rule='притягивается; через влияние; перераспределяются; ближе — заряд противоположного знака',
       mistakes=['на ближней стороне — заряд того же знака', 'считают, что незаряженное тело не притягивается',
                 '«нейтрализуются» вместо «перераспределяются»'],
       solve=_solve_4a, kind='param', kes=['3.1', '3.2', '3.5'],
       fidelity=F(MATCH_FMT + ' (4 пропуска, 8 слов)', 'как в демоверсии 2027 №4: связный текст об опыте, список '
                  'слов с парами противоположностей', 'Б', 10, 'школьные демонстрации электростатики',
                  'знак заряда на ближней стороне', '3.1–3.5', SC2))
def g_4a(rng):
    obj, who, pl, where = rng.choice(OBJ4A)
    rod, rod_d, rod_g = rng.choice(ROD4A)
    sign = rng.choice([1, -1])
    sgn = 'положительно' if sign > 0 else 'отрицательно'
    zar = 'заряженный' if 'шарик' in rod else 'заряженную'
    att, rep = ('притягиваются', 'отталкиваются') if pl else ('притягивается', 'отталкивается')
    text = (f'{sgn.capitalize()} {zar} {rod} медленно приближают к {obj}, не допуская касания. Наблюдают, что '
            f'{who} (А) к {rod_d}. Причина — явление (Б): под действием электрического поля {rod_g} заряды внутри '
            f'{where} (В), и на обращённой к {rod_d} стороне возникает избыточный (Г).')
    near = 'положительный заряд' if sign < 0 else 'отрицательный заряд'
    far = 'отрицательный заряд' if sign < 0 else 'положительный заряд'
    right = [att, 'электризации через влияние', 'перераспределяются', near]
    decoys = [rep, 'магнитного взаимодействия', 'нейтрализуются', far]
    e = (f'Незаряженное тело {"притягиваются" if pl else "притягивается"}: в нём происходит электризация через влияние — '
         f'заряды перераспределяются, и ближе к {rod_d} оказывается заряд противоположного знака ({near}).')
    return _gap_card('ph-oge-04-electrostatic-induction', rng, text, right, decoys, {'sign': sign, 'plural': pl}, e)


# --- 4b. электроскоп: влияние или касание
def _solve_4b(p):
    s = p['sign']
    same = 'положительный' if s > 0 else 'отрицательный'
    opp = 'отрицательный' if s > 0 else 'положительный'
    if p['touch']:
        moved = 'электроны' if s > 0 else 'электроны'
        return _ans_by_words(p, ['расходятся', same, moved, 'остаются разошедшимися'])
    return _ans_by_words(p, ['расходятся', opp, same, 'опадают'])


ROD4B = [('стеклянную палочку', 'стеклянной палочкой'), ('эбонитовую палочку', 'эбонитовой палочкой'),
         ('пластмассовую линейку', 'пластмассовой линейкой'), ('палочку из оргстекла', 'палочкой из оргстекла')]


@proto('ph-oge-04-electroscope', 'ОГЭ', 4, 'Текст с пропусками: электроскоп при поднесении заряженного тела или касании',
       invariant='заряженное тело подносят к шару электроскопа (без касания или с касанием): расхождение листочков, '
                 'знаки зарядов на шаре и листочках, что будет после удаления тела',
       varies='знак заряда, касание/без касания, материал палочки, порядок слов',
       answer_rule='без касания: на шаре — противоположный знак, на листочках — тот же, после удаления листочки опадают; '
                   'с касанием: электроскоп получает заряд того же знака (переходят электроны), листочки остаются разошедшимися',
       mistakes=['путают знаки заряда шара и листочков', 'считают, что переходят протоны',
                 'после удаления палочки листочки «остаются разошедшимися» и без касания'],
       solve=_solve_4b, kind='param', kes=['3.1', '3.3', '3.5'],
       fidelity=F(MATCH_FMT + ' (4 пропуска, 8 слов)', 'как в банке №4 (тексты об электроскопе)', 'Б', 10,
                  'школьный электроскоп', 'знак зарядов на шаре и листочках; касание/влияние', '3.1–3.5', SC2))
def g_4b(rng):
    s = rng.choice([1, -1])
    touch = rng.random() < 0.5
    rod, rod_i = rng.choice([r for r in ROD4B if not (('стекл' in r[0] and s < 0) or ('эбонит' in r[0] and s > 0))])
    sgn = 'положительно' if s > 0 else 'отрицательно'
    same = 'положительный' if s > 0 else 'отрицательный'
    opp = 'отрицательный' if s > 0 else 'положительный'
    if touch:
        text = (f'{sgn.capitalize()} заряженной {rod_i} коснулись шара незаряженного электроскопа, а затем '
                f'палочку убрали. Листочки электроскопа (А). Электроскоп приобрёл (Б) заряд, так как при касании '
                f'{"с электроскопа на палочку" if s > 0 else "с палочки на электроскоп"} перешли (В). После удаления '
                f'палочки листочки (Г).')
        right = ['расходятся', same, 'электроны', 'остаются разошедшимися']
        decoys = ['опадают', opp, 'протоны', 'сразу опадают']
        e = (f'При касании электроскоп заряжается зарядом того же знака ({same}); переходят только электроны. '
             'Заряд остаётся на электроскопе, листочки остаются разошедшимися.')
    else:
        text = (f'{sgn.capitalize()} заряженную {rod} поднесли к шару незаряженного электроскопа, не касаясь его. '
                f'Листочки электроскопа (А). При этом на шаре электроскопа накапливается (Б) заряд, а на листочках — '
                f'(В) заряд. Если палочку убрать, листочки (Г).')
        right = ['расходятся', opp, same, 'опадают']
        decoys = ['остаются неподвижными', 'остаются разошедшимися', 'нейтральный', 'притягиваются к шару']
        e = (f'Электризация через влияние: ближе к палочке (на шаре) — заряд противоположного знака ({opp}), на листочках — '
             f'того же ({same}), листочки расходятся. Общий заряд электроскопа равен нулю, поэтому после удаления палочки '
             'заряды снова распределяются равномерно и листочки опадают.')
    p = {'sign': s, 'touch': touch}
    return _gap_card('ph-oge-04-electroscope', rng, text, right, decoys, p, e)


# --- 4c. тепловое расширение жидкости в колбе с трубкой
OBJ4C = [('подкрашенной водой', 'воды'), ('со спиртом', 'спирта'), ('подсолнечным маслом', 'масла'),
         ('подкрашенным керосином', 'керосина')]


def _solve_4c(p):
    h = p['heat']
    return _ans_by_words(p, ['поднимается' if h else 'опускается', 'возрастает' if h else 'убывает',
                             'увеличивается' if h else 'сокращается', 'становится больше' if h else 'становится меньше'])


@proto('ph-oge-04-thermal-expansion', 'ОГЭ', 4, 'Текст с пропусками: тепловое расширение жидкости (колба с трубкой)',
       invariant='колбу с жидкостью и тонкой трубкой нагревают или охлаждают; уровень в трубке, скорость молекул, '
                 'расстояния между ними, объём',
       varies='жидкость, нагревание/охлаждение, чем нагревают/охлаждают, порядок слов',
       answer_rule='нагревание: уровень поднимается, скорость молекул растёт, расстояния и объём увеличиваются; '
                   'охлаждение — наоборот',
       mistakes=['считают, что увеличиваются размеры молекул', 'при охлаждении уровень поднимается'],
       solve=_solve_4c, kind='param', kes=['2.1', '2.2', '2.5'],
       fidelity=F(MATCH_FMT + ' (4 пропуска, 8 слов)', 'как в банке №4 (колба с трубкой)', 'Б', 10,
                  'лабораторная колба, жидкости из справочной таблицы', 'расширение за счёт расстояний, а не размеров '
                  'молекул', '2.1–2.5', SC2))
def g_4c(rng):
    liq, liq_g = rng.choice(OBJ4C)
    heat = rng.random() < 0.5
    how = rng.choice(['в сосуд с горячей водой', 'в таз с кипятком']) if heat else rng.choice(
        ['в сосуд со льдом', 'в холодную воду со снегом'])
    proc = 'нагревании' if heat else 'охлаждении'
    text = (f'Колбу {liq if liq.startswith("со ") else "с " + liq} закрыли пробкой, через которую пропущена тонкая стеклянная трубка, и опустили {how}. '
            f'Уровень жидкости в трубке (А). Это объясняется тем, что при {proc} средняя скорость теплового движения '
            f'молекул {liq_g} (Б), а среднее расстояние между молекулами (В). В результате объём жидкости (Г).')
    right = ['поднимается' if heat else 'опускается', 'возрастает' if heat else 'убывает',
             'увеличивается' if heat else 'сокращается', 'становится больше' if heat else 'становится меньше']
    decoys = ['опускается' if heat else 'поднимается', 'убывает' if heat else 'возрастает',
              'сокращается' if heat else 'увеличивается', 'становится меньше' if heat else 'становится больше']
    e = ('При нагревании молекулы движутся быстрее, расстояния между ними растут — жидкость расширяется, уровень в трубке '
         'поднимается.' if heat else 'При охлаждении молекулы движутся медленнее, расстояния между ними уменьшаются — '
         'объём жидкости уменьшается, уровень в трубке опускается.')
    return _gap_card('ph-oge-04-thermal-expansion', rng, text, right, decoys, {'heat': heat}, e)


# --- 4d. плавание тел
BODY4D = ['парафин', 'лёд', 'древесина (сосна)', 'древесина (дуб)', 'алюминий', 'мрамор', 'стекло оконное', 'сталь',
          'медь', 'свинец']
LIQ4D = ['вода', 'керосин', 'глицерин', 'вода морская', 'бензин', 'ртуть', 'спирт']
GEN = {'парафин': 'парафина', 'лёд': 'льда', 'древесина (сосна)': 'сосны', 'древесина (дуб)': 'дуба',
       'алюминий': 'алюминия', 'мрамор': 'мрамора', 'стекло оконное': 'стекла', 'сталь': 'стали', 'медь': 'меди',
       'свинец': 'свинца', 'вода': 'воды', 'керосин': 'керосина', 'глицерин': 'глицерина', 'вода морская': 'морской воды',
       'бензин': 'бензина', 'ртуть': 'ртути', 'спирт': 'спирта', 'масло машинное': 'машинного масла',
       'молоко цельное': 'молока', 'цинк': 'цинка', 'олово': 'олова', 'железо': 'железа', 'латунь': 'латуни',
       'никель': 'никеля', 'серебро': 'серебра', 'золото': 'золота', 'фарфор': 'фарфора', 'бетон': 'бетона'}
INS = {'вода': 'воду', 'керосин': 'керосин', 'глицерин': 'глицерин', 'вода морская': 'морскую воду',
       'бензин': 'бензин', 'ртуть': 'ртуть', 'спирт': 'спирт', 'масло машинное': 'машинное масло'}


def _solve_4d(p):
    fl = RHO[p['body']] < RHO[p['liq']]
    return _ans_by_words(p, ['плавает' if fl else 'тонет', 'меньше' if fl else 'больше',
                             'уравновешивает' if fl else 'не уравновешивает', 'частично' if fl else 'полностью'])


@proto('ph-oge-04-floating', 'ОГЭ', 4, 'Текст с пропусками: условие плавания тела',
       invariant='сплошное тело опускают в жидкость; плавает/тонет, сравнение плотностей, соотношение выталкивающей '
                 'силы и силы тяжести, полностью/частично погружено',
       varies='вещество тела и жидкость (плотности из таблицы), форма тела, порядок слов',
       answer_rule='ρтела < ρжидк: плавает, частично погружено, Fа уравновешивает mg; иначе тонет, Fа < mg',
       mistakes=['сравнивают массы вместо плотностей', 'стальной шарик «тонет» в ртути'],
       solve=_solve_4d, kind='param', kes=['1.23'],
       fidelity=F(MATCH_FMT + ' (4 пропуска, 8 слов)', 'как в банке №4 (кубик льда, яйцо в жидкостях)', 'Б', 10,
                  'плотности — из справочных таблиц КИМ', 'плотность тела и жидкости, ртуть', '1.23', SC2))
def g_4d(rng):
    body = rng.choice(BODY4D)
    liq = rng.choice(LIQ4D)
    if RHO[body] == RHO[liq]:
        raise Retry
    fl = RHO[body] < RHO[liq]
    shape = rng.choice(['кубик', 'шарик', 'брусок'])
    sp = {'кубик': 'Сплошной кубик', 'шарик': 'Сплошной шарик', 'брусок': 'Сплошной брусок'}[shape]
    text = (f'{sp} из {GEN[body]} осторожно опустили в широкий сосуд, в который налили {INS[liq]}. '
            f'{shape.capitalize()} (А), так как плотность {GEN[body]} (Б) плотности {GEN[liq]}. В положении равновесия '
            f'выталкивающая сила (В) силу тяжести, действующую на {shape}, а сам {shape} погружён в жидкость (Г).')
    right = ['плавает' if fl else 'тонет', 'меньше' if fl else 'больше', 'уравновешивает' if fl else 'не уравновешивает',
             'частично' if fl else 'полностью']
    decoys = ['тонет' if fl else 'плавает', 'больше' if fl else 'меньше', 'не уравновешивает' if fl else 'уравновешивает',
              'полностью' if fl else 'частично']
    e = (f'ρ({body}) = {RHO[body]} кг/м³, ρ({liq}) = {RHO[liq]} кг/м³. ' +
         ('Плотность тела меньше — оно плавает, частично погрузившись; выталкивающая сила уравновешивает силу тяжести.'
          if fl else 'Плотность тела больше — оно тонет, погружаясь полностью; выталкивающая сила меньше силы тяжести.'))
    return _gap_card('ph-oge-04-floating', rng, text, right, decoys, {'body': body, 'liq': liq}, e)


# --- 4e. звук: высота и громкость
SRC4E = [('Стальную линейку зажали в тисках и ударили по её свободному концу', 'выступающую часть линейки',
          'линейка'),
         ('Гитарную струну оттянули и отпустили', 'звучащую часть струны, прижав её пальцем к ладу,', 'струна'),
         ('Натянутую между двумя гвоздями резинку оттянули и отпустили', 'натянутую часть резинки', 'резинка'),
         ('Тонкую деревянную рейку прижали к краю стола и ударили по свободному концу', 'выступающую часть рейки',
          'рейка')]


def _solve_4e(p):
    return _ans_by_words(p, ['колебательное', 'увеличивается' if p['shorter'] else 'уменьшается',
                             'выше' if p['shorter'] else 'ниже', 'громче' if p['stronger'] else 'тише'])


@proto('ph-oge-04-sound', 'ОГЭ', 4, 'Текст с пропусками: источник звука, высота и громкость',
       invariant='источник звука — колеблющееся тело; укорочение/удлинение → частота и высота тона; сила удара → '
                 'амплитуда и громкость',
       varies='источник (линейка, струна, резинка, рейка), укоротили/удлинили, сильнее/слабее, порядок слов',
       answer_rule='короче → частота больше, звук выше; сильнее → амплитуда больше, громче',
       mistakes=['громкость связывают с частотой', 'высоту тона — с амплитудой'],
       solve=_solve_4e, kind='param', kes=['1.24', '1.27', '1.28'],
       fidelity=F(MATCH_FMT + ' (4 пропуска, 8 слов)', 'как в банке №4 (линейка в тисках, нить, камертон)', 'Б', 10,
                  'школьные опыты со звуком', 'частота ↔ высота, амплитуда ↔ громкость', '1.24–1.28', SC2))
def g_4e(rng):
    act, part, who = rng.choice(SRC4E)
    shorter = rng.random() < 0.5
    stronger = rng.random() < 0.5
    ch = 'укоротили' if shorter else 'удлинили'
    hit = 'сильнее' if stronger else 'слабее'
    text = (f'{act} — послышался звук. Источником звука является (А) движение тела. Затем {ch} {part} и снова '
            f'возбудили звук, но {hit}, чем в первый раз. Частота колебаний при этом (Б), поэтому звук стал (В). '
            f'Из-за изменения амплитуды колебаний звук стал (Г).')
    if 'струн' in part and not shorter:
        text = text.replace(f'{ch} {part}', 'удлинили звучащую часть струны, отпустив палец')
    right = ['колебательное', 'увеличивается' if shorter else 'уменьшается', 'выше' if shorter else 'ниже',
             'громче' if stronger else 'тише']
    decoys = ['вращательное', 'уменьшается' if shorter else 'увеличивается', 'ниже' if shorter else 'выше',
              'тише' if stronger else 'громче']
    e = ('Звук создаёт колеблющееся тело. Чем короче колеблющаяся часть, тем больше частота и выше звук; чем сильнее '
         'удар, тем больше амплитуда и громче звук.')
    return _gap_card('ph-oge-04-sound', rng, text, right, decoys, {'shorter': shorter, 'stronger': stronger}, e)


# =====================================================================================================================
# ЗАДАНИЕ 5. Объяснение явления: выбрать ответ с верным обоснованием (1 из 4)
# =====================================================================================================================

F5 = lambda kes, scale, trap: F('одна цифра — номер верного ответа (4 варианта «вывод + обоснование»)',
                                'как в демоверсии 2027 №5: вопрос «Нарушится ли…/Какой…?» и четыре развёрнутых '
                                'варианта ответа с объяснением', 'Б', 6, scale, trap, kes, SC1)

# --- 5a. выталкивающая сила: весы, два тела/две жидкости
MAT5 = ['алюминий', 'сталь', 'медь', 'свинец', 'цинк', 'мрамор', 'стекло оконное', 'олово', 'серебро', 'фарфор']
LIQ5 = ['вода', 'керосин', 'спирт', 'глицерин', 'вода морская', 'бензин', 'масло машинное']
LIQ5_PREP = {'вода': 'воду', 'керосин': 'керосин', 'спирт': 'спирт', 'глицерин': 'глицерин',
             'вода морская': 'морскую воду', 'бензин': 'бензин', 'масло машинное': 'машинное масло'}


def _solve_5a(p):
    # независимо: равные массы → V = m/ρ; Fa = ρж g V; перевешивает тело с меньшей Fa
    if p['mode'] == 'mat':
        f1 = Fr(RHO[p['liq']], RHO[p['m1']])
        f2 = Fr(RHO[p['liq']], RHO[p['m2']])
    else:
        f1, f2 = Fr(RHO[p['l1']]), Fr(RHO[p['l2']])
    want = ('1', 'less') if f1 < f2 else ('2', 'less')
    return str(p['codes'].index(list(want)) + 1)


@proto('ph-oge-05-buoyancy-balance', 'ОГЭ', 5, 'Весы с телами в жидкости: какое перевесит и почему',
       invariant='уравновешенные на весах тела погружают в жидкость; сравнить выталкивающие силы (Fa = ρж g Vт)',
       varies='два тела равной массы из разных веществ в одной жидкости или одинаковые тела в двух жидкостях; '
              'вещества и жидкости из справочной таблицы',
       answer_rule='перевешивает тело, на которое действует меньшая выталкивающая сила (меньший объём или менее '
                   'плотная жидкость)',
       mistakes=['считают, что Fa зависит от плотности тела', '«равные массы — равновесие не нарушится»',
                 'перевешивает тело в более плотной жидкости'],
       solve=_solve_5a, kind='param', kes=['1.20', '1.23'],
       fidelity=F5('1.23', 'вещества и жидкости из справочных таблиц КИМ', 'Fa зависит от объёма тела и плотности '
                   'жидкости, а не от плотности тела'))
def g_5a(rng):
    mode = rng.choice(['mat', 'liq'])
    shape = rng.choice(['шара', 'цилиндра', 'бруска'])
    if mode == 'mat':
        m1, m2 = pick(rng, MAT5, 2)
        liq = rng.choice(LIQ5)
        if RHO[m1] == RHO[m2]:
            raise Retry
        g1, g2 = GEN[m1], GEN[m2]
        q = (f'Два сплошных {shape} одинаковой массы — первый из {g1}, второй из {g2} — уравновешены на рычажных весах. '
             f'Нарушится ли равновесие весов, если оба тела одновременно полностью погрузить в {LIQ5_PREP[liq]}?')
        dense, light = ('1', '2') if RHO[m1] > RHO[m2] else ('2', '1')
        name = {'1': f'из {g1}', '2': f'из {g2}'}
        items = [
            ([dense, 'less'], f'Равновесие нарушится: перевесит тело {name[dense]}. Его объём меньше, поэтому на него '
                              'действует меньшая выталкивающая сила.'),
            ([light, 'more'], f'Равновесие нарушится: перевесит тело {name[light]}. Его объём больше, поэтому на него '
                              'действует бо́льшая выталкивающая сила.'),
            (['0', 'eq'], 'Равновесие не нарушится: массы тел одинаковы, поэтому одинаковы и выталкивающие силы.'),
            ([dense, 'rho'], f'Равновесие нарушится: перевесит тело {name[dense]}. Плотность его вещества больше, '
                             'поэтому на него действует бо́льшая выталкивающая сила.'),
        ]
        p = {'mode': mode, 'm1': m1, 'm2': m2, 'liq': liq}
        e = (f'Массы равны, значит, объём тела {name[dense]} меньше (V = m/ρ). Fa = ρж·g·V — на него действует '
             f'меньшая выталкивающая сила, и оно перевесит.')
    else:
        mat = rng.choice(MAT5)
        l1, l2 = pick(rng, LIQ5, 2)
        if RHO[l1] == RHO[l2]:
            raise Retry
        q = (f'Два одинаковых сплошных {shape} из {GEN[mat]} уравновешены на рычажных весах. Первое тело полностью '
             f'погрузили в {LIQ5_PREP[l1]}, второе — в {LIQ5_PREP[l2]}. Нарушится ли равновесие весов?')
        lo, hi = ('1', '2') if RHO[l1] < RHO[l2] else ('2', '1')
        nm = {'1': f'первое тело (в жидкости: {l1})', '2': f'второе тело (в жидкости: {l2})'}
        items = [
            ([lo, 'less'], f'Равновесие нарушится: перевесит {nm[lo]}. Плотность этой жидкости меньше, поэтому '
                           'выталкивающая сила меньше.'),
            ([hi, 'more'], f'Равновесие нарушится: перевесит {nm[hi]}. Плотность этой жидкости больше, поэтому '
                           'выталкивающая сила больше.'),
            (['0', 'eq'], 'Равновесие не нарушится: тела одинаковые и погружены полностью, поэтому выталкивающие силы '
                          'равны.'),
            (['0', 'mass'], 'Равновесие не нарушится: массы тел при погружении в жидкость не изменяются.'),
        ]
        p = {'mode': mode, 'l1': l1, 'l2': l2}
        e = 'Объёмы тел равны, Fa = ρж·g·V больше в более плотной жидкости; перевешивает тело в менее плотной жидкости.'
    items = shuffled(rng, items)
    p['codes'] = [c for c, _ in items]
    o = [t for _, t in items]
    right = next(i for i, (c, _) in enumerate(items) if c[1] == 'less')
    return pcard('ph-oge-05-buoyancy-balance', q, str(right + 1), e, k='one', o=opts(o), p=p)


# --- 5b. теплопередача: ощущение «холоднее/горячее», цвет и излучение
PAIR5B = [('металлическая дверная ручка', 'деревянная дверь'), ('стальная ложка', 'деревянная ложка'),
          ('алюминиевая кружка', 'керамическая кружка'), ('металлическая скамейка', 'деревянная скамейка'),
          ('медная монета', 'пластмассовая пуговица'), ('железные перила', 'деревянные перила')]
ENV5B = [(-15, 'на морозе при температуре −15 °С'), (-5, 'на улице при температуре −5 °С'), (10, 'в неотапливаемом сарае при температуре 10 °С'),
         (50, 'в сауне при температуре воздуха 50 °С'), (60, 'на солнцепёке, где они нагрелись до 60 °С'),
         (80, 'в сауне при температуре воздуха 80 °С'), (5, 'в холодном подвале при температуре 5 °С')]


def _solve_5b(p):
    if p['mode'] == 'touch':
        # при t < 36 °С рука отдаёт тепло, при t > 36 °С получает; металл проводит тепло лучше — ощущение сильнее
        want = ['metal', 'cond'] if (p['t'] < 36) == (p['ask'] == 'cold') else ['other', 'cond']
    else:
        want = ['dark', 'rad']
    return str(p['codes'].index(want) + 1)


@proto('ph-oge-05-heat-transfer', 'ОГЭ', 5, 'Теплопередача: какой предмет кажется холоднее/горячее, что остывает или '
       'нагревается быстрее',
       invariant='сравнение двух тел по теплопроводности (одинаковая температура, разное ощущение) или по поглощению/'
                 'излучению (тёмное и светлое)',
       varies='предметы, температура среды (ниже или выше температуры тела человека), сюжет (снег, чайник, одежда)',
       answer_rule='ниже 36 °С холоднее кажется металл, выше — металл кажется горячее (большая теплопроводность); '
                   'тёмные тела сильнее поглощают и излучают',
       mistakes=['«металл холоднее — у него ниже температура»', 'белое тело излучает сильнее'],
       solve=_solve_5b, kind='param', kes=['2.7'],
       fidelity=F5('2.7', 'бытовые предметы из банка (ложки, кружки, ручки, снег, чайник)',
                   'одинаковая температура ≠ одинаковое ощущение; цвет и излучение'))
def g_5b(rng):
    mode = rng.choice(['touch', 'touch', 'color'])
    if mode == 'touch':
        (met, oth), (t, env) = rng.choice(PAIR5B), rng.choice(ENV5B)
        ask = 'cold' if t < 36 else 'hot'
        word = 'холоднее' if ask == 'cold' else 'горячее'
        q = (f'{met.capitalize()} и {oth} долго находились {env}. Какой из этих предметов на ощупь кажется {word}? '
             'Выберите верное утверждение.')
        items = [
            (['metal', 'cond'], f'{met.capitalize()}, так как металл обладает большей теплопроводностью.'),
            (['other', 'cond'], f'{oth.capitalize()}, так как у дерева, керамики и пластмассы теплопроводность меньше.'),
            (['metal', 'temp'], f'{met.capitalize()}, так как температура металла {"ниже" if ask == "cold" else "выше"}.'),
            (['eq', 'temp'], 'Оба предмета ощущаются одинаково, так как их температуры равны.'),
        ]
        cold = t < 36
        e = (f'Температуры предметов одинаковы ({ru(t)} °С). Металл быстрее {"отводит тепло от руки" if cold else "передаёт тепло руке"}, '
             f'поэтому кажется {"холоднее" if cold else "горячее"}.')
        p = {'mode': mode, 't': t, 'ask': ask}
    else:
        sc = rng.choice([
            ('Два одинаковых чайника — чёрный и белый — налили одинаково горячей водой и оставили остывать. Какой чайник '
             'остынет быстрее?', 'Чёрный', 'Белый', 'излучает', 'излучает'),
            ('В солнечный день на поле лежит чистый снег и снег, посыпанный золой. Какой снег растает быстрее?',
             'Посыпанный золой', 'Чистый', 'поглощает', 'поглощает'),
            ('Две одинаковые бутылки с водой — одну обернули чёрной тканью, другую белой — выставили на солнце. Вода в '
             'какой бутылке нагреется быстрее?', 'В бутылке с чёрной тканью', 'В бутылке с белой тканью', 'поглощает',
             'поглощает'),
            ('Два одинаковых термометра выставили на солнце: шарик одного закопчён, другого — нет. Какой термометр '
             'покажет более высокую температуру?', 'Закопчённый', 'Незакопчённый', 'поглощает', 'поглощает'),
        ])
        q, dark, light, verb, _ = sc
        items = [
            (['dark', 'rad'], f'{dark}, так как тёмная поверхность сильнее {verb} излучение.'),
            (['light', 'rad'], f'{light}, так как светлая поверхность сильнее {verb} излучение.'),
            (['dark', 'cond'], f'{dark}, так как у тёмной поверхности больше теплопроводность.'),
            (['eq', 'x'], 'Одинаково, так как цвет поверхности не влияет на теплопередачу.'),
        ]
        e = f'Тёмные тела сильнее поглощают и сильнее излучают энергию. Ответ: {dark.lower()}.'
        p = {'mode': mode}
    items = shuffled(rng, items)
    p['codes'] = [c for c, _ in items]
    a = _solve_5b(p)
    return pcard('ph-oge-05-heat-transfer', q, a, e, k='one', o=opts([t for _, t in items]), p=p)


# --- 5c. инерция в транспорте
VEH5C = [('автобуса', 'автобус', ''), ('трамвая', 'трамвай', ''), ('электрички', 'электричка', 'а'),
         ('маршрутного такси', 'маршрутное такси', 'о'), ('вагона метро', 'вагон', ''), ('поезда', 'поезд', '')]


def _solve_5c(p):
    # тело по инерции сохраняет скорость: отклонение вперёд ⇔ транспорт замедляется; назад ⇔ разгоняется;
    # влево ⇔ поворот вправо
    d = p['dir']
    want = {'вперёд': 'brake', 'назад': 'accel', 'влево': 'right', 'вправо': 'left'}[d]
    return str(p['codes'].index(want) + 1)


@proto('ph-oge-05-inertia', 'ОГЭ', 5, 'Инерция: как изменилось движение транспорта по поведению пассажиров/предметов',
       invariant='пассажиры или предмет на гладком столике отклоняются/катятся относительно вагона; вывод об изменении '
                 'скорости транспорта с объяснением через инерцию',
       varies='транспорт, объект (пассажиры, мяч на столе, маятник-брелок), направление отклонения',
       answer_rule='вперёд — торможение; назад — разгон; вбок — поворот в противоположную сторону',
       mistakes=['вперёд — «разгон»', 'объясняют «силой, толкающей вперёд»'],
       solve=_solve_5c, kind='param', kes=['1.9', '1.10'],
       fidelity=F5('1.9', 'как в банке: пассажиры трамвая, мяч в вагоне поезда', 'направление отклонения при '
                   'торможении и разгоне'))
def g_5c(rng):
    gen_, nom, sx = rng.choice(VEH5C)
    d = rng.choice(['вперёд', 'назад', 'влево', 'вправо'])
    obj = rng.choice(['pass', 'ball', 'toy'])
    if obj == 'pass':
        who = f'Пассажиры, стоящие в салоне равномерно и прямолинейно движущегося {gen_},'
        act = f'вдруг отклонились {d}'
    elif obj == 'ball':
        who = f'Мяч, лежавший на гладком горизонтальном столике {gen_}, движущегося равномерно и прямолинейно,'
        act = f'вдруг покатился {d}' if d in ('вперёд', 'назад') else f'вдруг покатился {d}'
    else:
        who = f'Брелок, висевший на нити у кабины водителя {gen_}, движущегося равномерно и прямолинейно,'
        act = f'вдруг отклонился {d}'
    dd = {'вперёд': 'по направлению движения', 'назад': 'против направления движения', 'влево': 'влево по ходу движения',
          'вправо': 'вправо по ходу движения'}[d]
    q = f'{who} {act} ({dd}). Что произошло с движением {gen_}?'
    items = [
        ('brake', f'{nom.capitalize()} начал{sx} тормозить: тела по инерции продолжают двигаться с прежней скоростью, '
                  'поэтому смещаются вперёд относительно салона.'),
        ('accel', f'{nom.capitalize()} начал{sx} разгоняться: тела по инерции сохраняют прежнюю скорость, поэтому '
                  'смещаются назад относительно салона.'),
        ('right', f'{nom.capitalize()} повернул{sx} вправо: тела по инерции продолжают двигаться прямолинейно и '
                  'смещаются влево относительно салона.'),
        ('left', f'{nom.capitalize()} повернул{sx} влево: тела по инерции продолжают двигаться прямолинейно и смещаются '
                 'вправо относительно салона.'),
        ('push', f'{nom.capitalize()} продолжает двигаться равномерно: на тела начала действовать сила, направленная '
                 f'{d}.'),
    ]
    want = {'вперёд': 'brake', 'назад': 'accel', 'влево': 'right', 'вправо': 'left'}[d]
    others = [x for x in items if x[0] != want]
    chosen = [x for x in items if x[0] == want] + pick(rng, others, 3)
    chosen = shuffled(rng, chosen)
    p = {'dir': d, 'codes': [c for c, _ in chosen]}
    e = 'Тела в салоне по инерции сохраняют скорость, которую имели до изменения движения транспорта. ' + \
        dict(chosen)[want].split(':')[0] + '.'
    return pcard('ph-oge-05-inertia', q, _solve_5c(p), e, k='one', o=opts([t for _, t in chosen]), p=p)


# --- 5d. цвет предмета через светофильтр
COL = {'красный': ('красным', 'красном', 'красного', 'красный', 'красная', 'красными'),
       'зелёный': ('зелёным', 'зелёном', 'зелёного', 'зелёный', 'зелёная', 'зелёными'),
       'синий': ('синим', 'синем', 'синего', 'синий', 'синяя', 'синими')}


def _look(surface, filt):
    """Цвет поверхности (белый/цветной) при освещении белым светом через фильтр: виден цвет фильтра или чёрный."""
    return filt if surface in ('белый', filt) else 'чёрный'


def _solve_5d(p):
    a_ink = p['filt'] if p['ink'] == p['filt'] else 'чёрный'
    a_pap = p['filt'] if p['paper'] in ('белый', p['filt']) else 'чёрный'
    code = 'no' if a_ink == a_pap else 'yes'
    return str(p['codes'].index([code, a_ink, a_pap]) + 1)


@proto('ph-oge-05-color-filter', 'ОГЭ', 5, 'Цвет предмета через светофильтр: удастся ли прочитать надпись',
       invariant='белый свет, фильтр пропускает только свой цвет; поверхность отражает свой цвет; надпись видна, если '
                 'надпись и фон выглядят по-разному',
       varies='цвет чернил, цвет бумаги (белая/цветная), цвет фильтра, сюжет (текст, рисунок)',
       answer_rule='цвет, совпадающий с цветом фильтра, выглядит цветом фильтра; остальные — чёрными',
       mistakes=['«красное через красный фильтр видно лучше»', 'смешивание цветов вместо поглощения'],
       solve=_solve_5d, kind='param', kes=['3.20'],
       fidelity=F5('3.20', 'как в банке: надпись на бумаге через фильтр', 'надпись того же цвета, что фильтр, '
                   'сливается с белым фоном'))
def g_5d(rng):
    ink, filt = rng.choice(list(COL)), rng.choice(list(COL))
    paper = rng.choice(['белый', 'белый'] + list(COL))
    if paper == ink:
        raise Retry
    a_ink = _look(ink, filt)
    a_pap = _look(paper, filt)
    what = rng.choice(['написан текст', 'нарисован домик', 'начерчена схема'])
    pap_txt = 'белой бумаге' if paper == 'белый' else f'{COL[paper][1]} листе бумаги'
    q = (f'На {pap_txt} {COL[ink][0]} фломастером {what}. Ученик рассматривает лист при белом свете через '
         f'{COL[filt][3]} светофильтр. Что он увидит?')
    vis = lambda c: 'чёрный' if c == 'чёрный' else c
    fon = lambda c: {'чёрный': 'чёрном', 'красный': 'красном', 'зелёный': 'зелёном', 'синий': 'синем'}[c]
    ink_ = lambda c: {'чёрный': 'чёрный', 'красный': 'красный', 'зелёный': 'зелёный', 'синий': 'синий'}[c]
    cands = []
    for ci in ['чёрный', filt]:
        for cp in ['чёрный', filt]:
            if ci == cp:
                t = f'Изображение не будет видно: и оно, и фон будут выглядеть {"чёрными" if ci == "чёрный" else COL[filt][5]}.'
                cands.append((['no', ci, cp], t))
            else:
                t = (f'Изображение будет видно: {ink_(ci)} рисунок на {fon(cp)} фоне, так как фильтр пропускает только '
                     f'{COL[filt][2]} цвета свет.')
                cands.append((['yes', ci, cp], t))
    if len({tuple(c) for c, _ in cands}) != 4:
        raise Retry
    right = ['no' if a_ink == a_pap else 'yes', a_ink, a_pap]
    items = shuffled(rng, cands)
    p = {'ink': ink, 'paper': paper, 'filt': filt, 'codes': [c for c, _ in items]}
    e = (f'Фильтр пропускает только {COL[filt][2]} цвета свет. Поверхность, отражающая этот цвет (белая или '
         f'{COL[filt][4]}), выглядит {COL[filt][0]}, остальные — чёрными. Надпись: {a_ink}, фон: {a_pap}.')
    o = [t for _, t in items]
    if len(set(o)) != 4:
        raise Retry
    return pcard('ph-oge-05-color-filter', q, str([c for c, _ in items].index(right) + 1), e, k='one', o=opts(o), p=p)


# --- 5e. уровень воды после таяния льда
CASE5E = {
    'float_fresh': ('В мензурке с водой плавает кусок льда. Отметили уровень воды.', 'same'),
    'float_salt': ('В сосуде с солёной водой плавает кусок льда из пресной воды. Отметили уровень воды.', 'up'),
    'fixed_bottom': ('Кусок льда прикрепили нитью ко дну мензурки и налили воду так, что лёд полностью погружён. '
                     'Отметили уровень воды.', 'down'),
    'stone': ('В сосуде с водой плавает кусок льда, в который вморожен небольшой камешек. Отметили уровень воды.', 'down'),
    'cork': ('В сосуде с водой плавает кусок льда, в который вморожена пробковая крошка (плотность пробки меньше плотности '
             'воды). Отметили уровень воды.', 'same'),
}


def _solve_5e(p):
    # масса вытесненной воды до таяния vs объём талой воды (+ плавающие/тонущие включения)
    c = p['case']
    rho_w, rho_i = 1000, 900
    if c == 'float_fresh':
        before, after = Fr(1), Fr(1)  # плавающий лёд вытесняет воду своей массы
    elif c == 'float_salt':
        before, after = Fr(rho_w, 1030), Fr(1)
    elif c == 'fixed_bottom':
        before, after = Fr(rho_w, rho_i), Fr(1)
    elif c == 'stone':
        before, after = Fr(2), Fr(1) + Fr(1, 2)  # камень: сначала «весом», после — только объёмом
    else:
        before, after = Fr(1), Fr(1)
    want = 'up' if after > before else 'down' if after < before else 'same'
    return str(p['codes'].index(want) + 1)


@proto('ph-oge-05-ice-melt', 'ОГЭ', 5, 'Изменится ли уровень воды, когда растает лёд',
       invariant='лёд плавает или удерживается в воде; сравнить объём вытесненной воды до таяния и объём талой воды',
       varies='пресная/солёная вода, лёд плавает/прикреплён ко дну, включения в лёд (камешек, пробка)',
       answer_rule='плавающий лёд в пресной воде — уровень не меняется; в солёной — поднимается; лёд, удерживаемый под '
                   'водой, или лёд с камнем — уровень понижается',
       mistakes=['«лёд легче воды — уровень опустится»', 'не учитывают, что вода в сосуде солёная'],
       solve=_solve_5e, kind='param', kes=['1.23', '2.12'],
       fidelity=F5('1.23', 'как в банке: мензурка со льдом', 'масса вытесненной воды = масса плавающего льда'))
def g_5e(rng):
    case = rng.choice(list(CASE5E))
    txt, ans = CASE5E[case]
    cont = rng.choice([('мензурке', 'мензурки'), ('стакане', 'стакана'), ('банке', 'банки'), ('аквариуме', 'аквариума')])
    txt = txt.replace('мензурке', cont[0]).replace('сосуде', cont[0]).replace('мензурки', cont[1])
    q = txt + ' Изменится ли уровень воды, когда весь лёд растает?'
    R = {
        'same': 'Уровень не изменится: плавающий лёд вытесняет воду, масса которой равна массе льда, а при таянии '
                'масса льда не меняется.',
        'up': 'Уровень повысится: талая вода займёт больший объём, чем вытеснял лёд.',
        'down': 'Уровень понизится: лёд вытеснял больше воды, чем её образуется при таянии.',
        'down2': 'Уровень понизится: плотность льда меньше плотности воды, поэтому при таянии объём уменьшается.',
    }
    items = [('same', R['same']), ('up', R['up']), ('down', R['down'])]
    if ans != 'down':
        items.append(('x', R['down2']))
    else:
        items.append(('x', 'Уровень не изменится: масса льда и масса талой воды одинаковы.'))
    items = shuffled(rng, items)
    p = {'case': case, 'codes': [c for c, _ in items]}
    e = {'same': 'Плавающее тело вытесняет жидкость массой, равной своей массе; талая вода имеет ту же массу и '
                 'занимает ровно этот объём.',
         'up': 'Лёд вытесняет солёную воду массой, равной массе льда; пресная талая вода менее плотная и займёт '
               'больший объём.',
         'down': 'Удерживаемый под водой лёд или лёд с камнем вытесняет больше воды, чем даёт талая вода (камень '
                 'после таяния тонет и вытесняет только свой объём).'}[ans]
    return pcard('ph-oge-05-ice-melt', q, _solve_5e(p), e, k='one', o=opts([t for _, t in items]), p=p)


# =====================================================================================================================
# ЗАДАНИЯ 6–11. Расчёт одной величины (краткий ответ — число)
# =====================================================================================================================

def P(**kw):
    """Параметры карточки для solve(): дроби — строками ('3/2'), чтобы карточка сериализовалась в JSON."""
    return {k: (str(v) if isinstance(v, Fr) else v) for k, v in kw.items()}


def V(p, k):
    return Fr(p[k])


def ncard(pid, q, x, unit, e, p, wrong, dec=2):
    """Числовая карточка: x — точное значение (Fraction); ответ — конечная дробь ≤ dec знаков, иначе Retry."""
    a = exact(x, dec)
    if a is None or Fr(x) <= 0 and not p.get('_neg'):
        raise Retry
    if len(a.replace(',', '').replace('-', '')) > 7:
        raise Retry
    q = q + (f'\nОтвет: ___ {unit}.' if unit else '\nОтвет: ___.')
    ws = []
    for w in wrong:
        try:
            w = Fr(w)
        except (TypeError, ValueError, ZeroDivisionError):
            continue
        if w > 0 and (w * 1000).denominator == 1:
            ws.append(fmt(w))
    return pcard(pid, q, a, e, k='num', p=p, wrong=ws)


def sx(x):
    return ru(x)


def fsqrt(x):
    """Точный квадратный корень из дроби (или None)."""
    x = Fr(x)
    if x < 0:
        return None
    a, b = math.isqrt(x.numerator), math.isqrt(x.denominator)
    return Fr(a, b) if a * a == x.numerator and b * b == x.denominator else None


FN = lambda kes, scale, trap, unit_note='': F(NUM_FMT + unit_note, 'как в банке: краткое условие, «Ответ: ___ ед.»; '
                                             'g = 10 Н/кг, справочные данные — со страницы КИМ', 'Б', 4, scale, trap,
                                             kes, SC1)

# ------------------------------------------------------------------ 6. Механика: движение и взаимодействие


def _solve_6xt(p):
    t, x = p['t'], p['x']
    i = p['seg']
    return exact(Fr(abs(x[i + 1] - x[i]), t[i + 1] - t[i]))


XT_WHO = ['тело', 'велосипедист', 'лодка', 'игрушечный автомобиль', 'тележка', 'пешеход', 'шайба']


@proto('ph-oge-06-xt-speed', 'ОГЭ', 6, 'Скорость на участке по таблице/графику координаты x(t)',
       invariant='движение вдоль оси Ox с участками равномерного движения; модуль скорости на указанном интервале',
       varies='кто движется, значения координат (в т. ч. движение назад), выбранный интервал',
       answer_rule='|υ| = |x₂ − x₁| / (t₂ − t₁) на выбранном участке',
       mistakes=['делят координату на время, а не изменение координаты', 'берут весь интервал движения',
                 'учитывают знак проекции в ответе «по модулю»'],
       solve=_solve_6xt, kes=['1.2', '1.3'],
       fidelity=FN('1.2–1.3', 'координаты до десятков метров, время до 10 с, как на графиках банка',
                   'выделить нужный участок и изменение координаты', ', ответ в м/с'))
def g_6xt(rng):
    for _ in range(50):
        n = rng.choice([3, 4])
        ts = [0]
        for _ in range(n):
            ts.append(ts[-1] + rng.choice([1, 2, 2, 3, 4]))
        xs = [rng.choice([0, 2, 4, 5, 10, -5])]
        for _ in range(n):
            xs.append(xs[-1] + rng.choice([-10, -8, -6, -5, -4, 0, 3, 4, 5, 6, 8, 10, 12]))
        seg = rng.randrange(n)
        if xs[seg + 1] == xs[seg]:
            continue
        v = Fr(abs(xs[seg + 1] - xs[seg]), ts[seg + 1] - ts[seg])
        if exact(v, 1) is None:
            continue
        break
    else:
        raise Retry
    who = rng.choice(XT_WHO)
    row_t = ' | '.join(str(t) for t in ts)
    row_x = ' | '.join(sx(x) for x in xs)
    q = (f'{who.capitalize()} движется вдоль оси Ox, на каждом из участков между указанными моментами времени — '
         f'равномерно. В таблице приведены значения координаты x в разные моменты времени t.\n'
         f't, с: {row_t}\nx, м: {row_x}\nЧему равен модуль скорости движения в интервале времени от {ts[seg]} до '
         f'{ts[seg + 1]} с?')
    e = f'|υ| = |{sx(xs[seg + 1])} − ({sx(xs[seg])})| / ({ts[seg + 1]} − {ts[seg]}) = {exact(v)} м/с.'
    p = {'t': ts, 'x': xs, 'seg': seg}
    wrong = [Fr(abs(xs[seg + 1]), ts[seg + 1]) if ts[seg + 1] else 0, Fr(abs(xs[-1] - xs[0]), ts[-1]),
             abs(xs[seg + 1] - xs[seg])]
    return ncard('ph-oge-06-xt-speed', q, v, 'м/с', e, p, wrong)


def _solve_6avg(p):
    s = sum(Fr(x) for x in p['s'])
    t = sum(Fr(x) for x in p['t'])
    return exact(s / t * Fr(p['k']))


@proto('ph-oge-06-avg-speed', 'ОГЭ', 6, 'Средняя скорость (в т. ч. на двух участках), перевод единиц',
       invariant='υср = весь путь / всё время; часто нужен перевод минут в секунды, км в м',
       varies='кто движется (пешеход, велосипедист, поезд, шарик на столе), один или два участка, единицы',
       answer_rule='υср = (s₁ + s₂)/(t₁ + t₂) в требуемых единицах',
       mistakes=['среднее арифметическое скоростей', 'не перевели минуты в секунды', 'забыли второй участок'],
       solve=_solve_6avg, kes=['1.2'],
       fidelity=FN('1.1–1.2', 'пешеход 1200 м за 20 мин, шарик 150 см за 0,5 мин — масштаб банка',
                   'перевод единиц и среднее арифметическое скоростей', ', ответ в м/с или км/ч'))
def g_6avg(rng):
    kind = rng.choice(['one', 'two', 'two'])
    if kind == 'one':
        who, s, sunit, sk, t, tunit, tk = rng.choice([
            ('Пешеход, двигаясь по тротуару,', rng.choice([600, 900, 1200, 1500, 1800, 2400]), 'м', 1,
             rng.choice([10, 15, 20, 25, 30]), 'мин.', 60),
            ('Металлический шарик, катясь по столу,', rng.choice([60, 90, 120, 150, 180, 240]), 'см', Fr(1, 100),
             rng.choice([2, 3, 4, 5, 6, 10]), 'с', 1),
            ('Велосипедист', rng.choice([3, 6, 9, 12, 18]), 'км', 1000, rng.choice([10, 15, 20, 30, 45, 60]), 'мин.', 60),
            ('Лыжник', rng.choice([2, 3, 4, 5, 6]), 'км', 1000, rng.choice([10, 12, 15, 20, 25]), 'мин.', 60),
        ])
        S, T = [Fr(s) * sk], [Fr(t) * tk]
        q = f'{who} прошёл путь {sx(s)} {sunit} за {sx(t)} {tunit} Чему равна его средняя скорость?'
        if 'Шарик' in who or 'шарик' in who:
            q = (f'Скатившись по наклонному жёлобу, металлический шарик продолжил движение по полу и до остановки '
                 f'преодолел {sx(s)} см. Движение по полу длилось {sx(t)} с. Определите среднюю скорость шарика на '
                 'этом участке.')
        q = q.replace('км за', 'км за').replace('км Чему', 'км. Чему')
        unit, k = 'м/с', 1
    else:
        who = rng.choice(['Автомобиль', 'Велосипедист', 'Мотоциклист', 'Катер', 'Автобус'])
        v1 = rng.choice([10, 12, 15, 20, 25])
        t1 = rng.choice([10, 20, 30, 40, 60])
        s2 = rng.choice([200, 300, 400, 600, 900, 1200])
        t2 = rng.choice([10, 20, 30, 40, 50, 60])
        S, T = [Fr(v1 * t1), Fr(s2)], [Fr(t1), Fr(t2)]
        q = (f'{who} {t1} с двигался со скоростью {v1} м/с, а затем проехал ещё {s2} м за {t2} с. '
             f'Чему равна средняя скорость {("автомобиля" if who == "Автомобиль" else "его движения")} на всём пути?')
        if who == 'Катер':
            q = q.replace('проехал', 'проплыл')
        unit, k = 'м/с', 1
    v = sum(S) / sum(T)
    p = {'s': [str(x) for x in S], 't': [str(x) for x in T], 'k': 1}
    e = f'υср = s/t = {sx(sum(S))} м / {sx(sum(T))} с = {exact(v) or ""} м/с.'
    wrong = [sum(S) / sum(T) * 60, (S[0] / T[0] + S[-1] / T[-1]) / 2 if len(S) > 1 else S[0] / T[0] * Fr(36, 10),
             S[-1] / T[-1]]
    return ncard('ph-oge-06-avg-speed', q, v, unit, e, p, wrong)


def _solve_6acc(p):
    a, t, v, s = (V(p, k) if p.get(k) is not None else None for k in ('a', 't', 'v', 's'))
    f = p['find']
    if f == 'v':
        return exact(a * t)
    if f == 'a':
        return exact(v / t)
    if f == 's':
        return exact(a * t * t / 2)
    r = fsqrt(2 * s / a)
    return exact(r) if r is not None else None


ACC_WHO = [('Автомобиль', 'трогается с места у светофора'), ('Велосипедист', 'стартует с места на тренировке'),
           ('Поезд', 'отходит от платформы'), ('Лыжник', 'начинает спуск с горы без толчка'),
           ('Санки', 'начинают скатываться с ледяной горки, не имея начальной скорости'),
           ('Самолёт', 'начинает разбег по взлётной полосе')]


@proto('ph-oge-06-uniform-accel', 'ОГЭ', 6, 'Равноускоренное движение из состояния покоя: υ = at, s = at²/2',
       invariant='движение из покоя с постоянным ускорением; найти скорость, ускорение, путь или время',
       varies='кто движется, что дано и что найти, числа',
       answer_rule='υ = at; a = υ/t; s = at²/2; t = √(2s/a)',
       mistakes=['s = at (без 1/2)', 's = at²', 'a = t/υ'],
       solve=_solve_6acc, kes=['1.4'],
       fidelity=FN('1.4', 'ускорения 0,5–4 м/с², время до 20 с', 'множитель 1/2 в формуле пути',
                   ', ответ в м/с, м/с², м или с'))
def g_6acc(rng):
    who, act = rng.choice(ACC_WHO)
    find = rng.choice(['v', 'a', 's', 't'])
    a = rng.choice([Fr(1, 2), 1, Fr(3, 2), 2, Fr(5, 2), 3, 4])
    t = rng.choice([2, 4, 5, 6, 8, 10, 12, 15, 20])
    v, s = a * t, a * t * t / 2
    pl = who == 'Санки'
    if find == 'v':
        q = f'{who} {act} и движется равноускоренно; ускорение равно {sx(a)} м/с². Определите скорость, которую {"санки будут иметь" if pl else "он будет иметь"} спустя {t} с после начала движения.'
        x, unit, wrong = v, 'м/с', [a * t / 2, Fr(t) / a, a * t * t]
        e = f'υ = at = {sx(a)}·{t} = {exact(v)} м/с.'
    elif find == 'a':
        q = f'{who} {act} и за {t} с {"приобретают" if pl else "приобретает"} скорость {sx(v)} м/с. Чему равно ускорение, если его считать постоянным?'
        x, unit, wrong = a, 'м/с²', [v * t, Fr(t) / v, v / t / 2]
        e = f'a = υ/t = {sx(v)}/{t} = {exact(a)} м/с².'
    elif find == 's':
        q = f'{who} {act} и движется равноускоренно; ускорение равно {sx(a)} м/с². Определите путь, пройденный {"санками" if pl else "им"} за первые {t} с движения.'
        x, unit, wrong = s, 'м', [a * t, a * t * t, a * t / 2]
        e = f's = at²/2 = {sx(a)}·{t}²/2 = {exact(s)} м.'
    else:
        q = f'{who} {act} и движется равноускоренно; ускорение равно {sx(a)} м/с². Сколько времени {"понадобится санкам" if pl else "ему понадобится"}, чтобы пройти первые {sx(s)} м?'
        x, unit, wrong = Fr(t), 'с', [s / a, 2 * s / a, s * a]
        e = f't = √(2s/a) = √(2·{sx(s)}/{sx(a)}) = {t} с.'
    p = P(find=find, a=a, t=t, v=v, s=s)
    return ncard('ph-oge-06-uniform-accel', q, x, unit, e, p, wrong)


def _solve_6ff(p):
    g, f = V(p, 'g'), p['find']
    if f == 'v':
        return exact(g * V(p, 't'))
    if f == 'h':
        return exact(g * V(p, 't') ** 2 / 2)
    if f == 'hmax':
        return exact(V(p, 'v0') ** 2 / (2 * g))
    if f == 'tup':
        return exact(V(p, 'v0') / g)
    if f == 'dv':
        return exact(g * V(p, 't'))
    return None


PLANET = [(10, 'Земли', 'у поверхности Земли'), (Fr(16, 10), 'Луны', 'у поверхности Луны, где ускорение свободного '
          'падения равно 1,6 м/с² (атмосфера отсутствует)'), (Fr(37, 10), 'Меркурия', 'у поверхности Меркурия, где '
          'ускорение свободного падения равно 3,7 м/с² (атмосфера отсутствует)')]


@proto('ph-oge-06-free-fall', 'ОГЭ', 6, 'Свободное падение и бросок вверх: скорость, высота, время',
       invariant='движение с ускорением g без сопротивления воздуха; из покоя или бросок вертикально вверх',
       varies='тело (камень, мяч, яблоко, сосулька), Земля/Луна/Меркурий, что найти',
       answer_rule='υ = gt; h = gt²/2; hmax = υ₀²/(2g); tподъёма = υ₀/g; за каждую секунду скорость растёт на g',
       mistakes=['h = gt', 'hmax = υ₀²/g', 'g = 9,8 вместо 10'],
       solve=_solve_6ff, kes=['1.5', '1.14'],
       fidelity=FN('1.5, 1.14', 'время 1–5 с, скорости до 30 м/с; Луна 1,6 и Меркурий 3,7 м/с² — как в банке',
                   'множитель 1/2, подъём до верхней точки', ', ответ в м/с, м или с'))
def g_6ff(rng):
    g, gen_, where = rng.choice(PLANET)
    who = rng.choice(['Камень', 'Мяч', 'Сосулька', 'Яблоко', 'Шарик', 'Металлический болт'])
    find = rng.choice(['v', 'h', 'hmax', 'tup', 'dv'] if g == 10 else ['v', 'h', 'dv'])
    t = rng.choice([1, 2, 3, 4, 5]) if g == 10 else rng.choice([2, 3, 4, 5, 10])
    v0 = rng.choice([10, 15, 20, 25, 30])
    nr = 'Сопротивлением воздуха пренебречь.' if g == 10 else ''
    if find == 'v':
        q = f'{who} падает из состояния покоя {where}. Какую скорость он будет иметь через {t} с после начала падения? {nr}'
        x, unit, wrong = g * t, 'м/с', [g * t * t / 2, g * t / 2, g * t * t]
        e = f'υ = gt = {sx(g)}·{t} = {exact(g * t)} м/с.'
    elif find == 'h':
        q = f'{who} падает из состояния покоя {where}. Какой путь он пройдёт за {t} с? {nr}'
        x, unit, wrong = g * t * t / 2, 'м', [g * t, g * t * t, g * t / 2]
        e = f'h = gt²/2 = {sx(g)}·{t}²/2 = {exact(g * t * t / 2)} м.'
    elif find == 'dv':
        q = f'{who} свободно падает {where} из состояния покоя. На сколько увеличится его скорость за {t} с падения? {nr}'
        x, unit, wrong = g * t, 'м/с', [g * t * t / 2, g, g * t * 2]
        e = f'Δυ = gΔt = {sx(g)}·{t} = {exact(g * t)} м/с.'
    elif find == 'hmax':
        q = f'{who} брошен вертикально вверх с поверхности Земли со скоростью {v0} м/с. На какую максимальную высоту он поднимется? {nr}'
        x, unit, wrong = Fr(v0 * v0, 20), 'м', [Fr(v0 * v0, 10), Fr(v0, 10), Fr(v0 * v0, 2)]
        e = f'hmax = υ₀²/(2g) = {v0}²/20 = {exact(Fr(v0 * v0, 20))} м.'
    else:
        q = f'{who} брошен вертикально вверх со скоростью {v0} м/с. Через какое время он достигнет верхней точки траектории? {nr}'
        x, unit, wrong = Fr(v0, 10), 'с', [Fr(v0, 5), Fr(v0 * v0, 20), Fr(v0, 20)]
        e = f't = υ₀/g = {v0}/10 = {exact(Fr(v0, 10))} с.'
    q = q.replace('  ', ' ').strip()
    if who in ('Сосулька',):
        q = q.replace('Какую скорость он', 'Какую скорость она').replace('путь он', 'путь она').replace(
            'его скорость', 'её скорость').replace('брошен', 'брошена').replace('он поднимется', 'она поднимется').replace(
            'он достигнет', 'она достигнет')
    if who in ('Яблоко',):
        q = q.replace('Какую скорость он', 'Какую скорость оно').replace('путь он', 'путь оно').replace(
            'брошен', 'брошено').replace('он поднимется', 'оно поднимется').replace('он достигнет', 'оно достигнет')
    p = P(find=find, g=g, t=t, v0=v0)
    return ncard('ph-oge-06-free-fall', q, x, unit, e, p, wrong)


def _solve_6circ(p):
    f = p['find']
    N, t = V(p, 'N'), V(p, 't')
    if f == 'nu':
        return exact(N / t)
    if f == 'T':
        return exact(t / N)
    r = V(p, 'kv') ** 2 / V(p, 'kr')
    return exact(r if r > 1 else 1 / r)


ROT = ['барабан стиральной машины', 'колесо обозрения', 'лопасти ветряка', 'точильный круг',
       'грампластинка на проигрывателе', 'карусель', 'диск болгарки', 'шкив токарного станка']


@proto('ph-oge-06-circular', 'ОГЭ', 6, 'Движение по окружности: период, частота, центростремительное ускорение',
       invariant='равномерное движение по окружности; T = t/N, ν = N/t; a = υ²/R (во сколько раз изменится)',
       varies='что вращается, число оборотов и время (в т. ч. в минутах), изменение R и υ',
       answer_rule='ν = N/t [Гц], T = t/N [с]; aц₂/aц₁ = (kυ²)/kR',
       mistakes=['не перевели минуты в секунды', 'путают период и частоту', 'a ~ υ, а не υ²'],
       solve=_solve_6circ, kes=['1.6'],
       fidelity=FN('1.6', 'вентилятор 1200 об/мин, как в банке', 'перевод минут в секунды, T ↔ ν'))
def g_6circ(rng):
    find = rng.choice(['nu', 'T', 'ratio'])
    if find in ('nu', 'T'):
        what = rng.choice(ROT)
        mins = rng.choice([1, 2, 3, 4, 5])
        slow = what in ('колесо обозрения', 'карусель', 'лопасти ветряка', 'грампластинка на проигрывателе')
        N = rng.choice([30, 45, 60, 90, 100, 120]) if slow else rng.choice([240, 300, 480, 600, 1200, 1500, 2400, 3000])
        if what == 'колесо обозрения':
            mins = rng.choice([10, 15, 20, 30])
            N = rng.choice([1, 2, 3, 5])
        t = mins * 60
        verb = 'совершают' if what.startswith('лопасти') else 'совершает'
        if find == 'nu':
            q = f'Работая в равномерном режиме, {what} {verb} {N} полных оборотов за {mins} мин. Определите частоту вращения.'
            x, unit, wrong = Fr(N, t), 'Гц', [Fr(t, N), Fr(N, mins), Fr(N, t) * 60]
            e = f'ν = N/t = {N}/{t} с = {exact(Fr(N, t)) or ""} Гц.'
        else:
            q = f'Работая в равномерном режиме, {what} {verb} {N} полных оборотов за {mins} мин. Определите период вращения.'
            x, unit, wrong = Fr(t, N), 'с', [Fr(N, t), Fr(mins, N), Fr(t, N) * 60]
            e = f'T = t/N = {t} с/{N} = {exact(Fr(t, N)) or ""} с.'
        p = P(find=find, N=N, t=t, kr=1, kv=1)
    else:
        kr = rng.choice([Fr(1, 2), 2, 3, 4])
        kv = rng.choice([Fr(1, 2), 2, 3, 4])
        r_w = 'увеличили' if kr > 1 else 'уменьшили'
        v_w = 'увеличили' if kv > 1 else 'уменьшили'
        r_n = kr if kr > 1 else 1 / kr
        v_n = kv if kv > 1 else 1 / kv
        ratio = kv * kv / kr
        if ratio == 1:
            raise Retry
        up = ratio > 1
        q = (f'Точка на ободе вращающегося диска равномерно движется по окружности. В новом режиме работы станка '
             f'радиус траектории точки стал в {sx(r_n)} раза {"больше" if kr > 1 else "меньше"}, а её скорость — в {sx(v_n)} раза '
             f'{"больше" if kv > 1 else "меньше"}. Во сколько раз {"возросло" if up else "уменьшилось"} центростремительное ускорение точки?')
        x = ratio if up else 1 / ratio
        unit, wrong = 'раз(а)', [kv / kr if kv / kr > 1 else kr / kv, kv * kr if kv * kr > 1 else 1 / (kv * kr), kv * kv]
        e = f'a = υ²/R, a₂/a₁ = ({sx(kv)})²/{sx(kr)} = {sx(ratio)}.'
        p = P(find='ratio', N=1, t=1, kr=kr, kv=kv)
    return ncard('ph-oge-06-circular', q, x, unit, e, p, wrong)


def _solve_6spring(p):
    f = p['find']
    k, x, m = (V(p, a) for a in ('k', 'x', 'm'))
    if f == 'k':
        return exact(m * G / x)
    if f == 'x':
        return exact(m * G / k * 100)
    return exact(k * x / G * 1000)


@proto('ph-oge-06-spring', 'ОГЭ', 6, 'Закон Гука: груз на пружине (жёсткость, удлинение, масса)',
       invariant='груз висит на пружине в равновесии: kx = mg; единицы: граммы, сантиметры',
       varies='прибор (динамометр, безмен, пружина весов, подвес лампы), что найти, числа',
       answer_rule='k = mg/x; x = mg/k; m = kx/g',
       mistakes=['не перевели граммы в кг или см в м', 'F = kx без mg', 'k = x/F'],
       solve=_solve_6spring, kes=['1.13'],
       fidelity=FN('1.13', 'грузы 50–500 г, растяжение 1–10 см, k = 20–200 Н/м — как в банке',
                   'перевод г → кг, см → м', ', ответ в Н/м, см или г'))
def g_6spring(rng):
    what = rng.choice(['пружине', 'пружине школьного динамометра', 'пружине бытового безмена', 'резиновом шнуре',
                       'пружине игрушки-прыгуна'])
    for _ in range(40):
        m = Fr(rng.choice([50, 100, 150, 200, 250, 300, 400, 500]), 1000)
        k = rng.choice([20, 25, 40, 50, 80, 100, 125, 200, 250])
        x = m * G / k
        if (x * 1000).denominator == 1 and x <= Fr(1, 5):
            break
    else:
        raise Retry
    find = rng.choice(['k', 'x', 'm'])
    mg, xc = sx(m * 1000), sx(x * 100)
    if find == 'k':
        q = f'Груз массой {mg} г подвесили на {what}, и она растянулась на {xc} см. Чему равна жёсткость?'
        if 'шнуре' in what:
            q = q.replace('на резиновом шнуре, и она растянулась', 'на резиновый шнур, и он растянулся')
        else:
            q = q.replace(f'на {what}', 'на ' + what.replace('пружине', 'пружину'))
        val, unit, wrong = Fr(k), 'Н/м', [m * 1000 * G / (x * 100), m * G / x / 10, x / (m * G)]
        e = f'k = mg/x = {sx(m)}·10/{sx(x)} = {k} Н/м.'
    elif find == 'x':
        q = f'Груз массой {mg} г подвесили на {what} жёсткостью {k} Н/м. На сколько сантиметров растянулась пружина?'
        q = q.replace(f'на {what}', 'на ' + what.replace('пружине', 'пружину').replace('резиновом шнуре', 'резиновый шнур'))
        if 'шнур' in what:
            q = q.replace('растянулась пружина', 'растянулся шнур')
        val, unit, wrong = x * 100, 'см', [x, m * 1000 * G / k, m / k * 100]
        e = f'x = mg/k = {sx(m)}·10/{k} = {sx(x)} м = {exact(x * 100)} см.'
    else:
        q = f'Когда к {what} жёсткостью {k} Н/м подвесили груз, растяжение составило {xc} см. Чему равна масса груза?'
        q = q.replace('к пружине', 'к пружине').replace('к резиновом шнуре', 'к резиновому шнуру')
        val, unit, wrong = m * 1000, 'г', [m, k * x * 100 / G, k * x * 1000]
        e = f'm = kx/g = {k}·{sx(x)}/10 = {sx(m)} кг = {exact(m * 1000)} г.'
    p = P(find=find, k=k, x=x, m=m)
    return ncard('ph-oge-06-spring', q, val, unit, e, p, wrong)


def _solve_6fric(p):
    f = p['find']
    if f == 'Ftr':
        return exact(V(p, 'mu') * V(p, 'm') * G)
    if f == 'mu':
        return exact(V(p, 'F') / (V(p, 'm') * G))
    if f == 'a':
        return exact((V(p, 'F') - V(p, 'mu') * V(p, 'm') * G) / V(p, 'm'))
    return exact(abs(V(p, 'F1') - V(p, 'F2')) / V(p, 'm'))


@proto('ph-oge-06-newton-friction', 'ОГЭ', 6, 'Второй закон Ньютона и сила трения скольжения',
       invariant='тело на горизонтальной поверхности: Fтр = μmg; равномерное движение — тяга равна трению; '
                 'ускорение от равнодействующей сил',
       varies='тело (брусок, ящик, санки, шкаф), что найти (Fтр, μ, a), силы и массы',
       answer_rule='Fтр = μmg; μ = F/(mg) при равномерном движении; a = (F − Fтр)/m или a = |F₁ − F₂|/m',
       mistakes=['a = F/m без трения', 'μ = F/m', 'складывают противоположные силы'],
       solve=_solve_6fric, kes=['1.10', '1.12'],
       fidelity=FN('1.10–1.12', 'бруски 0,2–2 кг, ящики 10–50 кг, μ = 0,1–0,5', 'учёт силы трения/направлений сил',
                   ', ответ в Н, м/с² или безразмерный'))
def g_6fric(rng):
    find = rng.choice(['Ftr', 'mu', 'a', 'a2'])
    body, m = rng.choice([('Брусок', rng.choice([Fr(1, 5), Fr(2, 5), Fr(1, 2), 1, 2])),
                          ('Ящик', rng.choice([10, 20, 25, 40, 50])), ('Санки с грузом', rng.choice([10, 20, 30])),
                          ('Деревянный кубик', rng.choice([Fr(1, 2), 1, Fr(3, 2)]))])
    mu = rng.choice([Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(3, 10), Fr(2, 5), Fr(1, 2)])
    ms = sx(m)
    if find == 'Ftr':
        q = f'{body} массой {ms} кг скользит по горизонтальной поверхности. Коэффициент трения скольжения равен {sx(mu)}. Чему равна сила трения скольжения?'
        x, unit, wrong = mu * m * G, 'Н', [mu * m, m * G, mu * m * G * 10]
        e = f'Fтр = μmg = {sx(mu)}·{ms}·10 = {exact(mu * m * G) or ""} Н.'
        p = P(find=find, mu=mu, m=m)
    elif find == 'mu':
        Fv = mu * m * G
        q = f'{body} массой {ms} кг равномерно тянут по горизонтальному полу, прикладывая горизонтальную силу {sx(Fv)} Н. Чему равен коэффициент трения скольжения?'
        x, unit, wrong = mu, '', [Fv / m, m * G / Fv, Fv / (m * G) * 10]
        e = f'При равномерном движении Fтяги = Fтр = μmg, μ = {sx(Fv)}/({ms}·10) = {exact(mu)}.'
        p = P(find=find, F=Fv, m=m)
    elif find == 'a':
        Fv = mu * m * G + m * rng.choice([Fr(1, 2), 1, 2])
        q = f'{body} массой {ms} кг тянут по горизонтальной поверхности горизонтальной силой {sx(Fv)} Н. Коэффициент трения скольжения {sx(mu)}. С каким ускорением движется тело?'
        x, unit, wrong = (Fv - mu * m * G) / m, 'м/с²', [Fv / m, (Fv + mu * m * G) / m, Fv - mu * m * G]
        e = f'a = (F − μmg)/m = ({sx(Fv)} − {sx(mu * m * G)})/{ms} = {exact(x) or ""} м/с².'
        p = P(find=find, F=Fv, mu=mu, m=m)
    else:
        F1 = rng.choice([2, 3, 4, 5, 6, 8, 10, 12]) * (m if m >= 10 else 1)
        F2 = rng.choice([1, 2, 3, 4]) * (m if m >= 10 else 1)
        if F1 == F2:
            raise Retry
        q = (f'На покоящийся {body.lower() if body != "Санки с грузом" else "груз на санках"} массой {ms} кг, находящийся на гладкой горизонтальной поверхности, '
             f'начинают действовать две горизонтальные силы {sx(F1)} Н и {sx(F2)} Н, направленные вдоль одной прямой в '
             'противоположные стороны. Чему равен модуль ускорения тела?')
        x, unit, wrong = Fr(abs(F1 - F2)) / m, 'м/с²', [Fr(F1 + F2) / m, Fr(F1) / m, Fr(abs(F1 - F2))]
        e = f'a = |F₁ − F₂|/m = {sx(abs(F1 - F2))}/{ms} = {exact(x) or ""} м/с².'
        p = P(find='a2', F1=F1, F2=F2, m=m)
    return ncard('ph-oge-06-newton-friction', q, x, unit, e, p, wrong)


def _solve_6grav(p):
    r = V(p, 'k1') * V(p, 'k2') / V(p, 'kr') ** 2
    return exact(r if r > 1 else 1 / r)


@proto('ph-oge-06-gravity-ratio', 'ОГЭ', 6, 'Закон всемирного тяготения: во сколько раз изменится сила',
       invariant='F = Gm₁m₂/r²; изменение масс и расстояния в несколько раз',
       varies='тела (шары, спутник и планета, астероиды), множители для масс и расстояния',
       answer_rule='F₂/F₁ = k₁k₂/kr²',
       mistakes=['забывают квадрат расстояния', 'умножают, а не делят на kr²'],
       solve=_solve_6grav, kes=['1.14'],
       fidelity=FN('1.14', 'множители 2–4, как в банке («свинцовые шары»)', 'квадрат расстояния'))
def g_6grav(rng):
    k1, k2 = rng.choice([1, 2, 3, 4, Fr(1, 2)]), rng.choice([1, 2, 3, 4, Fr(1, 2)])
    kr = rng.choice([1, 2, 3, Fr(1, 2)])
    r = k1 * k2 / kr ** 2
    if r == 1 or (k1 == 1 and k2 == 1) and kr == 1:
        raise Retry
    who = rng.choice([('Два свинцовых шара', 'шаров'), ('Два астероида', 'астероидов'), ('Две стальные болванки', 'болванок'),
                      ('Два космических корабля', 'кораблей')])
    parts = []
    if k1 != 1 and k1 == k2:
        parts.append(f'массу каждого из {who[1]} {"увеличить" if k1 > 1 else "уменьшить"} в {sx(k1 if k1 > 1 else 1 / k1)} раза')
    else:
        for i, k in ((1, k1), (2, k2)):
            if k != 1:
                parts.append(f'массу {"первого" if i == 1 else "второго"} тела {"увеличить" if k > 1 else "уменьшить"} в {sx(k if k > 1 else 1 / k)} раза')
    if kr != 1:
        parts.append(f'{"удалить" if kr > 1 else "сблизить"} тела так, чтобы расстояние между их центрами стало в {sx(kr if kr > 1 else 1 / kr)} раза {"больше" if kr > 1 else "меньше"}')
    up = r > 1
    q = f'{who[0]} находятся в космическом пространстве вдали от других тел. Во сколько раз {"возрастёт" if up else "уменьшится"} сила их гравитационного притяжения, если {" и ".join(parts)}?'
    x = r if up else 1 / r
    e = f'F ~ m₁m₂/r²: F₂/F₁ = {sx(k1)}·{sx(k2)}/{sx(kr)}² = {sx(r)}.'
    wrong = [k1 * k2 / kr if k1 * k2 / kr > 1 else kr / (k1 * k2), k1 * k2 * kr ** 2, k1 * k2]
    return ncard('ph-oge-06-gravity-ratio', q, x, 'раз(а)', e, P(k1=k1, k2=k2, kr=kr), wrong)


def _solve_6mom(p):
    f = p['find']
    m1, m2, v1 = V(p, 'm1'), V(p, 'm2'), V(p, 'v1')
    if f == 'u':
        return exact(m1 * v1 / (m1 + m2))
    if f == 'v1':
        return exact(V(p, 'u') * (m1 + m2) / m1)
    if f == 'p':
        return exact(m1 * v1)
    return exact(m1 * v1 / m2)


@proto('ph-oge-06-momentum', 'ОГЭ', 6, 'Импульс тела, неупругий удар, отдача (закон сохранения импульса)',
       invariant='p = mυ; при неупругом ударе и отдаче суммарный импульс системы сохраняется',
       varies='тела (шары, тележки, вагоны, лодка и человек), что найти: импульс, общую скорость, начальную скорость, '
              'скорость отдачи',
       answer_rule='p = mυ; u = m₁υ₁/(m₁ + m₂); υ₁ = u(m₁ + m₂)/m₁; υ₂ = m₁υ₁/m₂',
       mistakes=['u = υ₁/2', 'делят на m₂ вместо m₁ + m₂', 'не переводят граммы в кг'],
       solve=_solve_6mom, kes=['1.15', '1.16'],
       fidelity=FN('1.15–1.16', 'шары 1–5 кг, скорости до 10 м/с; вагоны — тонны', 'сумма масс после сцепки'))
def g_6mom(rng):
    find = rng.choice(['u', 'v1', 'p', 'rec'])
    kind = rng.choice([('шар', 'шаром', 'кг'), ('тележка', 'тележкой', 'кг'), ('вагон', 'вагоном', 'т')])
    m1, m2 = rng.choice([1, 2, 3, 4, 5, 6]), rng.choice([1, 2, 3, 4, 6])
    v1 = rng.choice([2, 3, 4, 5, 6, 8, 10])
    mu = kind[2]
    if find == 'u':
        q = (f'Налетев на покоящийся {kind[0] if kind[0] != "тележка" else "тележку"} массой {m2} {mu}, {kind[0]} массой {m1} {mu}, имевш{"ая" if kind[0] == "тележка" else "ий"} скорость {v1} м/с, '
             f'сцепляется с {"ней" if kind[0] == "тележка" else "ним"}. Определите скорость тел сразу после сцепки.')
        x, wrong = Fr(m1 * v1, m1 + m2), [Fr(m1 * v1, m2), Fr(v1, 2), Fr(m2 * v1, m1 + m2)]
        e = f'm₁υ₁ = (m₁ + m₂)u, u = {m1}·{v1}/{m1 + m2} = {exact(x) or ""} м/с.'
        p = P(find=find, m1=m1, m2=m2, v1=v1)
    elif find == 'v1':
        u = rng.choice([1, 2, 3, 4])
        q = (f'Движущийся {kind[0]} массой {m1} {mu} сталкивается с неподвижным {kind[1]} массой {m2} {mu}, после чего '
             f'они движутся вместе со скоростью {u} м/с. Какой была скорость первого тела до удара?')
        x, wrong = Fr(u * (m1 + m2), m1), [Fr(u * m1, m1 + m2), Fr(u * m2, m1), Fr(u * (m1 + m2), m2)]
        e = f'υ₁ = u(m₁ + m₂)/m₁ = {u}·{m1 + m2}/{m1} = {exact(x) or ""} м/с.'
        p = P(find=find, m1=m1, m2=m2, v1=0, u=u)
    elif find == 'p':
        mm = rng.choice([Fr(1, 10), Fr(2, 10), Fr(1, 2), 2, 5, 60, 1000, 1500])
        v = rng.choice([2, 4, 5, 10, 15, 20])
        who = {Fr(1, 10): 'Теннисный мяч', Fr(2, 10): 'Хоккейная шайба', Fr(1, 2): 'Футбольный мяч', 2: 'Ядро',
               5: 'Шар для боулинга', 60: 'Конькобежец', 1000: 'Легковой автомобиль', 1500: 'Автомобиль'}[mm]
        ms = f'{sx(mm * 1000)} г' if mm < 1 else (f'{sx(mm / 1000)} т' if mm >= 1000 else f'{sx(mm)} кг')
        q = f'Определите модуль импульса, которым обладает {who.lower()}, если {"его" if who not in ("Хоккейная шайба",) else "её"} масса {ms}, а скорость {v} м/с.'
        x, wrong = mm * v, [mm * v * v / 2, mm * 1000 * v if mm < 1 else mm / 1000 * v, Fr(v) / mm]
        e = f'p = mυ = {sx(mm)}·{v} = {exact(mm * v) or ""} кг·м/с.'
        p = P(find=find, m1=mm, m2=1, v1=v)
        return ncard('ph-oge-06-momentum', q, x, 'кг·м/с', e, p, wrong)
    else:
        mb = rng.choice([40, 50, 60])
        kboat = rng.choice([2, 3, 4, 5])
        vb = rng.choice([1, 2, 3, 4])
        q = (f'Мальчик массой {mb} кг прыгает в горизонтальном направлении с неподвижной лодки массой {mb * kboat} кг '
             f'со скоростью {vb} м/с относительно берега. С какой скоростью начнёт двигаться лодка? Сопротивлением воды пренебречь.')
        x, wrong = Fr(vb, kboat), [Fr(vb * kboat), Fr(vb, kboat + 1), Fr(vb)]
        e = f'0 = mυ − Mu, u = mυ/M = {mb}·{vb}/{mb * kboat} = {exact(x) or ""} м/с.'
        p = P(find='rec', m1=mb, m2=mb * kboat, v1=vb)
    if mu == 'т' and find in ('u', 'v1'):
        q = q.replace('Движущийся вагон', 'Движущийся вагон').replace('тележка', 'тележка')
    if kind[0] == 'тележка':
        q = q.replace('движущийся со скоростью', 'движущаяся со скоростью').replace('Движущийся тележка', 'Движущаяся тележка')
    return ncard('ph-oge-06-momentum', q, x, 'м/с', e, p, wrong)


def _solve_6en(p):
    f = p['find']
    m = V(p, 'm')
    if f == 'Ek':
        return exact(m * V(p, 'v') ** 2 / 2)
    if f == 'Ep':
        return exact(m * G * V(p, 'h'))
    if f == 'v':
        return exact(fsqrt(2 * G * V(p, 'h')))
    if f == 'h':
        return exact(V(p, 'v') ** 2 / (2 * G))
    if f == 'Ek_top':
        return exact(m * G * V(p, 'h'))
    if f == 'ratio':
        k = V(p, 'k')
        return exact(k * k)
    return exact(m * G * (V(p, 'h') - V(p, 'h2')))


EN_WHO = [('Мяч', 'm', [Fr(2, 5), Fr(1, 2)]), ('Камень', 'm', [Fr(1, 2), 1, 2, 4]), ('Снежок', 'm', [Fr(1, 10), Fr(1, 5)]),
          ('Гиря', 'f', [2, 4, 5]), ('Ядро', 'n', [4, 5]), ('Теннисный мяч', 'm', [Fr(1, 20), Fr(1, 10)]),
          ('Яблоко', 'n', [Fr(1, 5), Fr(1, 4)]), ('Кирпич', 'm', [2, 4])]


@proto('ph-oge-06-energy', 'ОГЭ', 6, 'Кинетическая и потенциальная энергия, закон сохранения энергии, работа силы тяжести',
       invariant='Eк = mυ²/2; Eп = mgh; без сопротивления воздуха Eк + Eп = const; работа силы тяжести = mgΔh',
       varies='тело (мяч, камень, санки, яблоко), что найти, числа; «во сколько раз изменилась Eк»',
       answer_rule='подстановка в формулу / приравнивание энергий; Eк₂/Eк₁ = k²',
       mistakes=['Eк = mυ²', 'Eк ~ υ (без квадрата)', 'не переводят граммы в кг', 'h — высота над полом, а не над столом'],
       solve=_solve_6en, kes=['1.17', '1.18', '1.19'],
       fidelity=FN('1.17–1.19', 'массы 0,1–5 кг, высоты до 20 м — как в банке', 'квадрат скорости, выбор нулевого '
                   'уровня', ', ответ в Дж, м/с, м или «в … раз»'))
def g_6en(rng):
    find = rng.choice(['Ek', 'Ep', 'v', 'h', 'Ek_top', 'ratio', 'work'])
    who, gnd, ms_ = rng.choice(EN_WHO)
    m = rng.choice(ms_)
    ms = f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    if find == 'Ek':
        v = rng.choice([2, 4, 5, 6, 10, 20])
        q = f'{who} ({ms}) в полёте в некоторый момент имеет скорость {v} м/с. Определите кинетическую энергию тела в этот момент.'
        x, unit, wrong = m * v * v / 2, 'Дж', [m * v * v, m * v / 2, m * 1000 * v * v / 2 if m < 1 else m * v]
        e = f'Eк = mυ²/2 = {sx(m)}·{v}²/2 = {exact(x) or ""} Дж.'
        p = P(find=find, m=m, v=v)
    elif find == 'Ep':
        h = rng.choice([2, 3, 5, 8, 10, 15, 20])
        q = f'{who} массой {ms} находится на высоте {h} м над поверхностью земли. Чему равна его потенциальная энергия относительно поверхности земли?'
        x, unit, wrong = m * G * h, 'Дж', [m * h, m * G * h / 2, m * 1000 * G * h if m < 1 else m * G]
        e = f'Eп = mgh = {sx(m)}·10·{h} = {exact(x) or ""} Дж.'
        p = P(find=find, m=m, h=h)
    elif find == 'v':
        h = rng.choice([Fr(1, 5), Fr(4, 5), Fr(9, 5), Fr(16, 5), 5, Fr(36, 5), 20, 45])
        q = f'{who} падает из состояния покоя с высоты {sx(h)} м. Какую скорость он будет иметь у самой земли? Сопротивлением воздуха пренебречь.'
        x, unit, wrong = fsqrt(20 * h), 'м/с', [20 * h, 10 * h, 2 * h]
        if x is None:
            raise Retry
        e = f'mgh = mυ²/2, υ = √(2gh) = √(20·{sx(h)}) = {exact(x) or ""} м/с.'
        p = P(find=find, m=m, h=h)
    elif find == 'h':
        v = rng.choice([2, 4, 5, 6, 8, 10, 12, 15, 20])
        q = f'{who} бросили вертикально вверх со скоростью {v} м/с. На какую максимальную высоту он поднимется? Сопротивлением воздуха пренебречь.'
        x, unit, wrong = Fr(v * v, 20), 'м', [Fr(v * v, 10), Fr(v, 10), Fr(v * v, 2)]
        e = f'mυ²/2 = mgh, h = υ²/(2g) = {v}²/20 = {exact(x) or ""} м.'
        p = P(find=find, m=m, v=v)
    elif find == 'Ek_top':
        h = rng.choice([5, 10, 15, 20, 25])
        q = (f'{who} массой {ms}, брошенный вертикально вверх, поднялся на максимальную высоту {h} м. Чему была равна '
             'его кинетическая энергия в момент броска? Сопротивлением воздуха пренебречь.')
        x, unit, wrong = m * G * h, 'Дж', [m * G * h / 2, m * h, 2 * m * G * h]
        e = f'Eк₀ = Eп max = mgh = {sx(m)}·10·{h} = {exact(x) or ""} Дж.'
        p = P(find=find, m=m, h=h)
    elif find == 'ratio':
        k = rng.choice([2, 3, 4, 5])
        up = rng.random() < 0.5
        veh = rng.choice(['автомобиля', 'велосипедиста', 'поезда', 'лыжника', 'катера'])
        q = (f'За некоторое время скорость {veh} стала в {k} раза {"больше" if up else "меньше"}, чем была. Во сколько раз '
             f'при этом {"возросла" if up else "уменьшилась"} кинетическая энергия {veh}?')
        x, unit, wrong = Fr(k * k), 'раз(а)', [Fr(k), Fr(2 * k), Fr(k, 2)]
        e = f'Eк ~ υ², поэтому Eк изменилась в {k}² = {k * k} раз.'
        p = P(find=find, m=m, k=k)
    else:
        h1 = rng.choice([3, 4, 5, 6])
        h2 = rng.choice([1, 2])
        q = (f'С антресоли, расположенной на высоте {h1} м над полом, соскользнул {who.lower()} массой {ms} и упал на '
             f'сиденье табурета высотой {h2} м. Какую работу совершила сила тяжести?')
        x, unit, wrong = m * G * (h1 - h2), 'Дж', [m * G * h1, m * G * (h1 + h2), m * (h1 - h2)]
        e = f'A = mg(h₁ − h₂) = {sx(m)}·10·({h1} − {h2}) = {exact(x) or ""} Дж.'
        p = P(find='work', m=m, h=h1, h2=h2)
    if gnd != 'm':
        end = 'а' if gnd == 'f' else 'о'
        for s_old, s_new in (('его кинетическая', 'её кинетическая' if gnd == 'f' else 'его кинетическая'),
                     ('его потенциальная', 'её потенциальная' if gnd == 'f' else 'его потенциальная'),
                     ('он будет', 'она будет' if gnd == 'f' else 'оно будет'),
                     ('он поднимется', 'она поднимется' if gnd == 'f' else 'оно поднимется'),
                     ('брошенный', 'брошенная' if gnd == 'f' else 'брошенное'), ('поднялся', 'поднял' + ('ась' if gnd == 'f' else 'ось')),
                     ('соскользнул и', 'соскользнул' + end + ' и'), ('и упал на', 'и упал' + end + ' на')):
            q = q.replace(s_old, s_new)
    return ncard('ph-oge-06-energy', q, x, unit, e, p, wrong)


def _solve_6work(p):
    f = p['find']
    if f == 'A':
        return exact(V(p, 'F') * V(p, 's'))
    if f == 'N':
        return exact(V(p, 'm') * G * V(p, 'h') / V(p, 't'))
    return exact(V(p, 'N') * V(p, 't') / 1000)


@proto('ph-oge-06-work-power', 'ОГЭ', 6, 'Механическая работа и мощность',
       invariant='A = Fs (сила вдоль перемещения), A = mgh; N = A/t',
       varies='что делают (тянут санки, поднимают груз краном, работает двигатель), что найти, единицы (кВт, кДж, мин)',
       answer_rule='A = Fs; N = mgh/t; A = Nt',
       mistakes=['N = At', 'забыли g при подъёме', 'не перевели минуты/кВт'],
       solve=_solve_6work, kes=['1.17'],
       fidelity=FN('1.17', 'подъёмники, краны, лебёдки — массы 50–1000 кг', 'перевод единиц, mgh'))
def g_6work(rng):
    find = rng.choice(['A', 'N', 'At'])
    if find == 'A':
        who = rng.choice(['Мальчик равномерно тянет санки по горизонтальной дороге, прикладывая силу',
                          'Трактор равномерно тащит борону, развивая силу тяги',
                          'Рабочий равномерно передвигает ящик по полу, прикладывая горизонтальную силу',
                          'Лошадь равномерно везёт телегу с силой тяги'])
        Fv = rng.choice([20, 40, 50, 80, 100, 150, 200, 500]) * (10 if 'Трактор' in who else 1)
        s = rng.choice([5, 10, 20, 25, 50, 100])
        q = f'{who} {Fv} Н, направленную вдоль перемещения. Какую работу совершает эта сила на пути {s} м?'
        x, unit, wrong = Fr(Fv * s), 'Дж', [Fr(Fv, s), Fr(Fv * s, 2), Fr(Fv * s * 10)]
        e = f'A = Fs = {Fv}·{s} = {Fv * s} Дж.'
        p = P(find=find, F=Fv, s=s)
    elif find == 'N':
        who = rng.choice(['Подъёмный кран', 'Лебёдка', 'Строительный подъёмник', 'Лифт'])
        m = rng.choice([50, 100, 200, 250, 400, 500, 800, 1000])
        h = rng.choice([2, 3, 5, 6, 10, 12, 15, 20])
        t = rng.choice([5, 10, 20, 25, 40, 50, 60])
        q = f'За {t} с {who.lower()} {"поднял" if who in ("Подъёмный кран", "Строительный подъёмник", "Лифт") else "подняла"} с постоянной скоростью {rng.choice(["бетонную плиту", "поддон с кирпичом", "контейнер", "ящик с оборудованием"])} массой {m} кг на {h} м. Определите мощность, развиваемую при этом (потерями энергии пренебречь).'
        x, unit, wrong = Fr(m * G * h, t), 'Вт', [Fr(m * h, t), Fr(m * G * h), Fr(m * G * h * t)]
        e = f'N = mgh/t = {m}·10·{h}/{t} = {exact(x) or ""} Вт.'
        p = P(find=find, m=m, h=h, t=t)
    else:
        Nk = rng.choice([Fr(1, 2), 1, 2, 3, 5, 10, 20])
        mins = rng.choice([1, 2, 5, 10])
        who = rng.choice(['Двигатель насоса', 'Электродвигатель лебёдки', 'Мотор лодки', 'Двигатель бетономешалки'])
        q = f'{who} мощностью {sx(Nk)} кВт работал {mins} мин. Какую работу он совершил?'
        x, unit, wrong = Nk * 1000 * mins * 60 / 1000, 'кДж', [Nk * mins, Nk * mins * 60 * 1000, Nk * 1000 * mins / 1000]
        e = f'A = Nt = {sx(Nk * 1000)} Вт·{mins * 60} с = {exact(x) or ""} кДж.'
        p = P(find='At', N=Nk * 1000, t=mins * 60)
    return ncard('ph-oge-06-work-power', q, x, unit, e, p, wrong)


# ------------------------------------------------------------------ 7. Механика: плотность, давление, плавание, рычаги, колебания


def _solve_7rho(p):
    f = p['find']
    if f == 'rho':
        return exact(V(p, 'm') / V(p, 'V'))
    if f == 'cap':
        return exact(V(p, 'm') / V(p, 'rho') * 1000)
    return exact(V(p, 'rho') * V(p, 'V'))


CAN7 = [('канистра', 'канистры'), ('топливный бак мотоцикла', 'бака'), ('бутыль', 'бутыли'), ('бочка', 'бочки'),
        ('бидон', 'бидона'), ('аквариум', 'аквариума')]
LIQ7 = ['бензин', 'керосин', 'масло машинное', 'спирт', 'вода', 'глицерин', 'молоко цельное']
SOL7 = ['мрамор', 'алюминий', 'сталь', 'медь', 'свинец', 'стекло оконное', 'парафин', 'лёд', 'цинк', 'олово', 'латунь']


@proto('ph-oge-07-density', 'ОГЭ', 7, 'Плотность, масса и объём (вместимость сосуда, масса детали)',
       invariant='m = ρV; перевод литров в м³ (1 л = 0,001 м³), см³ ↔ м³, г ↔ кг',
       varies='вещество (из таблицы плотностей КИМ), сосуд или деталь, что найти',
       answer_rule='ρ = m/V; V = m/ρ (в литрах); m = ρV',
       mistakes=['не перевели литры в м³', 'V = mρ', 'плотность в г/см³ вместо кг/м³'],
       solve=_solve_7rho, kes=['1.7'],
       fidelity=FN('1.7', 'канистры 10–40 л, детали десятки–сотни см³ — как в банке («канистра вмещает 36 кг масла»)',
                   'перевод л → м³ и г ↔ кг', ', ответ в кг/м³, л, г или кг'))
def g_7rho(rng):
    find = rng.choice(['rho', 'cap', 'm'])
    if find == 'rho':
        liq = rng.choice(LIQ7)
        Vl = rng.choice([2, 4, 5, 8, 10, 12, 15, 20])
        m = Fr(RHO[liq] * Vl, 1000)
        can, _ = rng.choice(CAN7)
        q = (f'Масса жидкости, целиком заполняющей {can.replace("канистра", "канистру").replace("бутыль", "бутыль").replace("бочка", "бочку")} '
             f'вместимостью {Vl} л, равна {sx(m)} кг. Определите плотность этой жидкости.')
        x, unit, wrong = Fr(RHO[liq]), 'кг/м³', [m / Vl, m * Vl, m / Vl * 100]
        e = f'ρ = m/V = {sx(m)} кг / {sx(Fr(Vl, 1000))} м³ = {RHO[liq]} кг/м³.'
        p = P(find=find, m=m, V=Fr(Vl, 1000))
    elif find == 'cap':
        liq = rng.choice(LIQ7)
        Vl = rng.choice([5, 10, 12, 15, 20, 25, 40, 50])
        m = Fr(RHO[liq] * Vl, 1000)
        can, can_g = rng.choice(CAN7)
        q = (f'В {can.replace("канистра", "канистру").replace("бутыль", "бутыль").replace("бочка", "бочку")} доверху налили '
             f'{liq} массой {sx(m)} кг. Какова вместимость {can_g}? Плотность '
             'жидкости возьмите из справочных данных.')
        q = q.replace(f'налили {liq}', f'налили {LIQ_ACC.get(liq, liq)}')
        x, unit, wrong = Fr(Vl), 'л', [m * RHO[liq] / 1000, Fr(Vl, 1000), m]
        e = f'V = m/ρ = {sx(m)}/{RHO[liq]} = {sx(Fr(Vl, 1000))} м³ = {Vl} л.'
        p = P(find=find, m=m, rho=RHO[liq])
    else:
        sol = rng.choice(SOL7)
        Vc = rng.choice([10, 20, 25, 40, 50, 80, 100, 150, 200])
        det = rng.choice(['деталь', 'брусок', 'грузик', 'кубик', 'шарик'])
        q = (f'Объём сплошного тела ({det}) из {GEN[sol]} измерили с помощью мензурки: он оказался равен {Vc} см³. '
             f'Какова масса тела?')
        x, unit, wrong = Fr(RHO[sol] * Vc, 1000), 'г', [Fr(Vc * 1000, RHO[sol]), Fr(RHO[sol] * Vc), Fr(RHO[sol] * Vc, 1000000)]
        e = f'm = ρV = {sx(Fr(RHO[sol], 1000))} г/см³ · {Vc} см³ = {exact(x) or ""} г.'
        p = P(find=find, rho=Fr(RHO[sol], 1000), V=Vc)
    return ncard('ph-oge-07-density', q, x, unit, e, p, wrong)


LIQ_ACC = {'вода': 'воду', 'масло машинное': 'машинное масло', 'молоко цельное': 'молоко'}


def _solve_7ps(p):
    return exact(V(p, 'm') * G / (V(p, 'S') * V(p, 'n')) / V(p, 'k'))


PS7 = [('Холодильник', 'стоит на четырёх ножках', 4, 'ножки', [40, 45, 50, 60, 64, 72, 80, 90], 'cm', [4, 5, 6, 8, 9, 10, 12, 16, 20]),
       ('Стол', 'стоит на четырёх ножках', 4, 'ножки', [16, 18, 20, 24, 25, 30, 32, 40], 'cm', [4, 5, 6, 8, 10, 12, 16]),
       ('Гусеничный трактор', 'опирается на две гусеницы', 2, 'гусеницы', [4800, 5000, 6000, 7200, 8000, 9000, 10000, 12000],
        'm', [Fr(3, 5), Fr(4, 5), 1, Fr(6, 5), Fr(3, 2), 2]),
       ('Лыжник', 'стоит на двух лыжах', 2, 'лыжи', [48, 50, 54, 60, 64, 70, 72, 80], 'cm', [1200, 1500, 1600, 1800, 2000, 2400]),
       ('Мальчик', 'стоит на полу на двух ногах', 2, 'подошвы', [36, 40, 42, 45, 48, 50, 54, 60], 'cm', [120, 125, 140, 150, 160, 180, 200]),
       ('Контейнер', 'стоит на полу одной гранью', 1, 'грани', [120, 150, 200, 240, 300, 360, 400, 500], 'm', [Fr(1, 5), Fr(1, 4), Fr(2, 5), Fr(1, 2), Fr(3, 4), 1]),
       ('Кирпичная тумба', 'стоит на земле своим основанием', 1, 'тумбы', [180, 240, 300, 360, 450], 'm', [Fr(1, 10), Fr(3, 20), Fr(1, 5), Fr(1, 4)])]


@proto('ph-oge-07-pressure-solid', 'ОГЭ', 7, 'Давление твёрдого тела на опору: p = mg/S с учётом числа опор',
       invariant='p = F/S, F = mg; площадь опоры — сумма площадей всех опор; см² → м²',
       varies='тело (холодильник, стол, трактор, лыжник, мальчик), число опор, масса, площадь',
       answer_rule='p = mg/(nS₁), ответ в кПа',
       mistakes=['берут площадь одной опоры', 'не перевели см² в м²', 'p = mS'],
       solve=_solve_7ps, kes=['1.21'],
       fidelity=FN('1.21', 'массы и площади реальных предметов (см², м²)', 'число опор и перевод см² → м²', ', ответ в кПа'))
def g_7ps(rng):
    who, how, n, part, ms, su, Ss = rng.choice(PS7)
    for _ in range(40):
        m = rng.choice(ms)
        Sv = rng.choice(Ss)
        S = Fr(Sv, 10000) if su == 'cm' else Fr(Sv)
        pk = m * G / (n * S) / 1000
        if exact(pk, 1) is not None:
            break
    else:
        raise Retry
    Sshow = f'{sx(Sv)} см²' if su == 'cm' else f'{sx(S)} м²'
    if n == 1:
        q = f'{who} массой {sx(m)} кг {how}. Площадь опоры равна {Sshow}. Какое давление {who.lower()} оказывает на опору?'
    else:
        q = f'{who} массой {sx(m)} кг {how}. Площадь опоры одной {part} равна {Sshow}. Какое давление {who.lower()} оказывает на опору?'
    wrong = [m * G / S / 1000, m / (n * S) / 1000, pk * 1000]
    e = f'p = mg/(nS) = {sx(m)}·10/({n}·{sx(S)} м²) = {exact(pk) or ""} кПа.'
    return ncard('ph-oge-07-pressure-solid', q, pk, 'кПа', e, P(m=m, S=S, n=n, k=1000), wrong)


def _solve_7hyd(p):
    f = p['find']
    if f == 'p':
        return exact(V(p, 'rho') * G * V(p, 'h') / V(p, 'k'))
    if f == 'h':
        return exact(V(p, 'p') / (V(p, 'rho') * G))
    return exact(V(p, 'rho') * V(p, 'h') / V(p, 'h2'))


@proto('ph-oge-07-hydrostatic', 'ОГЭ', 7, 'Давление жидкости: p = ρgh, манометр, сообщающиеся сосуды',
       invariant='гидростатическое давление ρgh; разность уровней в манометре; равновесие двух жидкостей в U-трубке '
                 'ρ₁h₁ = ρ₂h₂',
       varies='жидкость, глубина, что найти (давление, глубина, плотность второй жидкости), сюжет',
       answer_rule='p = ρgh; h = p/(ρg); ρ₂ = ρ₁h₁/h₂',
       mistakes=['не перевели см в м', 'добавляют атмосферное давление без запроса', 'ρ₂ = ρ₁h₂/h₁'],
       solve=_solve_7hyd, kes=['1.21'],
       fidelity=FN('1.21', 'глубины до десятков метров, манометры — см', 'перевод единиц, обратная пропорция в U-трубке',
                   ', ответ в Па, кПа, м или кг/м³'))
def g_7hyd(rng):
    find = rng.choice(['p', 'h', 'rho2', 'man'])
    if find == 'p':
        liq, place = rng.choice([('вода', 'на дне бассейна глубиной'), ('вода морская', 'на глубине, на которой работает водолаз, —'),
                                 ('керосин', 'на дне цистерны, заполненной керосином на высоту'),
                                 ('масло машинное', 'на дне бака, заполненного маслом на высоту'),
                                 ('вода', 'на дне пруда глубиной')])
        h = rng.choice([Fr(3, 2), 2, Fr(5, 2), 3, 4, 5, 6, 8, 10, 12, 15, 20] if 'морская' not in liq else [10, 15, 20, 25, 30, 40, 50, 60])
        x = Fr(RHO[liq] * G * h, 1000)
        q = f'Определите давление, создаваемое жидкостью {place} {h} м. Атмосферное давление не учитывайте.'
        e = f'p = ρgh = {RHO[liq]}·10·{h} = {RHO[liq] * G * h} Па = {exact(x) or ""} кПа.'
        wrong = [x * 1000, Fr(RHO[liq] * h, 1000), x + 100]
        p = P(find='p', rho=RHO[liq], h=h, k=1000)
        unit = 'кПа'
    elif find == 'h':
        pk = rng.choice([15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 120, 150, 200, 250, 300, 400, 500])
        x = Fr(pk * 1000, 1000 * G)
        who = rng.choice(['опущенный в глубокий колодец', 'закреплённый на батискафе в пресноводном озере',
                          'установленный на опоре моста под водой', 'прикреплённый к якорю буя в водохранилище'])
        q = (f'Датчик давления, {who}, показывает давление воды {pk} кПа (без учёта атмосферного давления). '
             'На какой глубине находится датчик?')
        e = f'h = p/(ρg) = {pk * 1000}/(1000·10) = {exact(x)} м.'
        wrong = [Fr(pk), x * 10, Fr(pk * 1000, 1000)]
        p = P(find='h', p=pk * 1000, rho=1000)
        unit = 'м'
    elif find == 'rho2':
        other = rng.choice(['керосин', 'масло машинное', 'бензин', 'спирт'])
        h2 = rng.choice([5, 10, 15, 20, 25, 30, 40, 50])
        h1 = Fr(RHO[other] * h2, 1000)
        if (h1 * 10).denominator != 1:
            raise Retry
        q = (f'В открытую U-образную трубку налили воду, а затем в одно колено долили несмешивающуюся с водой жидкость. '
             f'Высота столба этой жидкости над границей раздела равна {h2} см, а уровень воды в другом колене '
             f'находится выше границы раздела на {sx(h1)} см. Определите плотность долитой жидкости.')
        x = Fr(RHO[other])
        e = f'ρ₂h₂ = ρвh₁, ρ₂ = 1000·{sx(h1)}/{h2} = {RHO[other]} кг/м³.'
        wrong = [Fr(1000 * h2) / h1, Fr(1000) * h1, Fr(RHO[other], 1000)]
        p = P(find='rho2', rho=1000, h=h1, h2=h2)
        unit = 'кг/м³'
    else:
        dh = rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 16, 20, 25])
        liq = rng.choice(['вода', 'спирт', 'ртуть', 'глицерин'])
        x = Fr(RHO[liq] * G * dh, 100)
        q = (f'Одно колено открытого U-образного манометра, заполненного жидкостью ({liq}), подсоединили к газовому '
             f'баллону. Уровень жидкости в открытом колене оказался на {dh} см выше, чем в колене, соединённом с '
             'баллоном. На сколько давление газа в баллоне больше атмосферного?')
        e = f'Δp = ρgΔh = {RHO[liq]}·10·{sx(Fr(dh, 100))} = {exact(x) or ""} Па.'
        wrong = [Fr(RHO[liq] * G * dh), x / 2, x + 100000]
        p = P(find='p', rho=RHO[liq], h=Fr(dh, 100), k=1)
        unit = 'Па'
    return ncard('ph-oge-07-hydrostatic', q, x, unit, e, p, wrong)


def _solve_7arch(p):
    f = p['find']
    if f == 'F':
        return exact(V(p, 'rho') * G * V(p, 'V') * V(p, 'part'))
    if f == 'P':
        return exact(V(p, 'P0') - V(p, 'rho') * G * V(p, 'V'))
    if f == 'V':
        return exact(V(p, 'F') / (V(p, 'rho') * G) * 1000000)
    return exact(V(p, 'P0') - V(p, 'P1'))


@proto('ph-oge-07-archimedes', 'ОГЭ', 7, 'Выталкивающая сила: Fa = ρж g Vпогр, вес тела в жидкости',
       invariant='Fa = ρж·g·Vпогр; вес в жидкости = вес в воздухе − Fa; показания динамометра',
       varies='тело (камень, рыба, поплавок, гиря, буй), жидкость, доля погружения, что найти',
       answer_rule='Fa = ρж g V (V — объём погружённой части); P = P₀ − Fa; V = Fa/(ρж g); Fa = P₀ − P₁',
       mistakes=['берут плотность тела вместо плотности жидкости', 'не учитывают, что погружена половина тела',
                 'не переводят см³ в м³'],
       solve=_solve_7arch, kes=['1.23'],
       fidelity=FN('1.23', 'объёмы 0,001–2 м³ и десятки–сотни см³, как в банке', 'плотность жидкости, доля погружения',
                   ', ответ в Н или см³'))
def g_7arch(rng):
    find = rng.choice(['F', 'F', 'P', 'V', 'dyn'])
    liq = rng.choice(['вода', 'вода морская', 'керосин', 'спирт', 'глицерин'])
    if find == 'F':
        body, Vs, part, ptxt = rng.choice([
            ('рыбу', [Fr(1, 1000), Fr(2, 1000), Fr(5, 1000)], 1, 'плавающую в толще жидкости'),
            ('пенопластовый буй', [Fr(1, 50), Fr(1, 20), Fr(1, 10)], Fr(1, 2), 'погружённый в жидкость наполовину'),
            ('камень', [Fr(1, 1000), Fr(2, 1000), Fr(4, 1000), Fr(1, 100)], 1, 'лежащий на дне'),
            ('понтон', [1, 2, 4, 5], Fr(1, 2), 'погружённый наполовину'),
            ('деревянный брусок', [Fr(1, 1000), Fr(2, 1000), Fr(4, 1000)], Fr(3, 4), 'погружённый на три четверти объёма')])
        Vb = rng.choice(Vs)
        if body in ('рыбу',):
            liq = rng.choice(['вода', 'вода морская'])
        x = Fr(RHO[liq]) * G * Vb * part
        q = f'Определите выталкивающую силу, действующую на {body} объёмом {sx(Vb)} м³, {ptxt} (жидкость — {"морская вода" if liq == "вода морская" else liq}).'
        e = f'Fa = ρж g V·(доля) = {RHO[liq]}·10·{sx(Vb)}·{sx(part)} = {exact(x) or ""} Н.'
        wrong = [Fr(RHO[liq]) * G * Vb if part != 1 else x / 2, Fr(RHO[liq]) * Vb * part, x * 10]
        p = P(find='F', rho=RHO[liq], V=Vb, part=part)
        unit = 'Н'
    elif find == 'P':
        mat = rng.choice(['алюминий', 'сталь', 'медь', 'мрамор'])
        Vc = rng.choice([100, 200, 250, 400, 500])
        Vb = Fr(Vc, 1000000)
        P0 = Fr(RHO[mat]) * G * Vb
        x = P0 - Fr(RHO[liq]) * G * Vb
        q = (f'Сплошной цилиндр из {GEN[mat]} объёмом {Vc} см³, подвешенный к динамометру, полностью погрузили в '
             f'{INS.get(liq, liq)}. Что показывает динамометр?')
        e = f'P = ρт g V − ρж g V = ({RHO[mat]} − {RHO[liq]})·10·{sx(Vb)} = {exact(x) or ""} Н.'
        wrong = [P0, Fr(RHO[liq]) * G * Vb, P0 + Fr(RHO[liq]) * G * Vb]
        p = P(find='P', P0=P0, rho=RHO[liq], V=Vb)
        unit = 'Н'
    elif find == 'V':
        Vc = rng.choice([50, 100, 200, 250, 400, 500, 800])
        F = Fr(RHO[liq]) * G * Vc / 1000000
        q = (f'На полностью погружённое в жидкость ({"морская вода" if liq == "вода морская" else liq}) тело действует '
             f'выталкивающая сила {sx(F)} Н. Определите объём тела.')
        x = Fr(Vc)
        e = f'V = Fa/(ρж g) = {sx(F)}/({RHO[liq]}·10) = {sx(Fr(Vc, 1000000))} м³ = {Vc} см³.'
        wrong = [Fr(Vc, 1000000) * 1000, F * RHO[liq] * G, Fr(Vc * 10)]
        p = P(find='V', F=F, rho=RHO[liq])
        unit = 'см³'
    else:
        P0 = rng.choice([Fr(3, 2), 2, Fr(5, 2), 3, 4, 5])
        Fa = rng.choice([Fr(1, 5), Fr(2, 5), Fr(1, 2), Fr(3, 5), 1])
        if Fa >= P0:
            raise Retry
        P1 = P0 - Fa
        obj = rng.choice(['металлический грузик', 'камень', 'гайку', 'фарфоровую статуэтку', 'стальной болт'])
        q = (f'Ученик подвесил {obj} к динамометру: в воздухе прибор показал {sx(P0)} Н, а при полном погружении '
             f'{"груза" if obj == "металлический грузик" else "тела"} в жидкость — {sx(P1)} Н. Чему равна выталкивающая сила?')
        x = Fa
        e = f'Fa = P₀ − P₁ = {sx(P0)} − {sx(P1)} = {exact(x)} Н.'
        wrong = [P0 + P1, P1, P0]
        p = P(find='dyn', P0=P0, P1=P1)
        unit = 'Н'
    return ncard('ph-oge-07-archimedes', q, x, unit, e, p, wrong)


def _solve_7lev(p):
    f = p['find']
    if f == 'F':
        return exact(V(p, 'F1') * V(p, 'l1') / V(p, 'l2'))
    if f == 'l':
        return exact(V(p, 'F1') * V(p, 'l1') / V(p, 'F2'))
    return exact(V(p, 'm1') * V(p, 'l1') / V(p, 'l2'))


@proto('ph-oge-07-lever', 'ОГЭ', 7, 'Равновесие рычага: F₁l₁ = F₂l₂',
       invariant='правило моментов для лёгкого рычага; плечи в см, силы в Н или массы грузов',
       varies='сюжет (качели, лом, гаечный ключ, коромысло весов, рычаг в лаборатории), что найти',
       answer_rule='F₂ = F₁l₁/l₂; l₂ = F₁l₁/F₂; m₂ = m₁l₁/l₂',
       mistakes=['прямая пропорция вместо обратной', 'путают плечо с длиной рычага'],
       solve=_solve_7lev, kes=['1.20'],
       fidelity=FN('1.20', 'как в демоверсии 2027 №7: F₂ = 6 Н, плечи 15 и 25 см', 'обратная пропорциональность силы '
                   'и плеча', ', ответ в Н, см или кг'))
def g_7lev(rng):
    find = rng.choice(['F', 'F', 'l', 'm'])
    if find in ('F', 'l'):
        F1 = rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20])
        l1 = rng.choice([5, 10, 12, 15, 20, 25, 30, 40, 50])
        l2 = rng.choice([5, 10, 15, 20, 25, 30, 40, 50, 60])
        if l1 == l2:
            raise Retry
        F2 = Fr(F1 * l1, l2)
        ctx = rng.choice(['Лёгкий рычаг находится в равновесии под действием двух сил, приложенных по разные стороны от оси.',
                          'На уроке ученик уравновесил лёгкий рычаг, подвесив груз с одной стороны от оси и потянув '
                          'динамометром с другой.',
                          'Лёгкий стержень, закреплённый на оси, удерживается в горизонтальном положении двумя вертикальными силами.'])
        if find == 'F':
            q = f'{ctx} Первая сила равна {F1} Н, её плечо {l1} см; плечо второй силы {l2} см. Чему равен модуль второй силы?'
            x, unit, wrong = F2, 'Н', [Fr(F1 * l2, l1), Fr(F1), Fr(F1 * l1 * l2, 100)]
            e = f'F₁l₁ = F₂l₂, F₂ = {F1}·{l1}/{l2} = {exact(F2) or ""} Н.'
            p = P(find='F', F1=F1, l1=l1, l2=l2)
        else:
            if exact(F2, 1) is None:
                raise Retry
            q = f'{ctx} Первая сила равна {F1} Н, её плечо {l1} см; вторая сила равна {sx(F2)} Н. Чему равно плечо второй силы?'
            x, unit, wrong = Fr(l2), 'см', [Fr(F2 * l1, F1), Fr(l1), Fr(l2, 100)]
            e = f'l₂ = F₁l₁/F₂ = {F1}·{l1}/{sx(F2)} = {l2} см.'
            p = P(find='l', F1=F1, l1=l1, F2=F2)
    else:
        m1 = rng.choice([20, 25, 30, 35, 40, 50])
        l1 = rng.choice([Fr(3, 2), 2, Fr(5, 2), 3])
        l2 = rng.choice([1, Fr(3, 2), 2, Fr(5, 2), 3])
        if l1 == l2:
            raise Retry
        x = m1 * l1 / l2
        q = (f'Качели-балансир уравновешены: мальчик массой {m1} кг сидит на расстоянии {sx(l1)} м от опоры, а его '
             f'{"младшая сестра" if x < m1 else "старший брат"} — по другую сторону на расстоянии {sx(l2)} м. Какова масса '
             f'{"сестры" if x < m1 else "брата"}? Массой доски пренебречь.')
        unit, wrong = 'кг', [m1 * l2 / l1, Fr(m1), m1 * l1 * l2]
        e = f'm₁l₁ = m₂l₂, m₂ = {m1}·{sx(l1)}/{sx(l2)} = {exact(x) or ""} кг.'
        p = P(find='m', m1=m1, l1=l1, l2=l2)
    return ncard('ph-oge-07-lever', q, x, unit, e, p, wrong)


def _solve_7pul(p):
    k = 2 if p['mov'] else 1
    if p['find'] == 'F':
        return exact((V(p, 'm') + V(p, 'mb')) * G / k)
    return exact(V(p, 'F') * k / G - V(p, 'mb'))


@proto('ph-oge-07-pulley', 'ОГЭ', 7, 'Блоки: подвижный (выигрыш в силе в 2 раза) и неподвижный',
       invariant='равномерный подъём груза; неподвижный блок F = mg, подвижный F = (m + mблока)g/2',
       varies='груз (ведро, мешок, бадья, ящик), блок, масса блока (0 или задана), что найти',
       answer_rule='F = mg (неподвижный), F = (m + mб)g/2 (подвижный); m = kF/g − mб',
       mistakes=['для неподвижного блока делят на 2', 'забывают массу подвижного блока'],
       solve=_solve_7pul, kes=['1.20'],
       fidelity=FN('1.20', 'грузы 10–200 кг, как в банке', 'какой блок даёт выигрыш в силе', ', ответ в Н или кг'))
def g_7pul(rng):
    mov = rng.random() < 0.65
    find = rng.choice(['F', 'm'])
    load = rng.choice(['ведро с раствором', 'мешок с цементом', 'бадью с песком', 'ящик с инструментами', 'бочку с водой'])
    m = rng.choice([10, 15, 20, 25, 30, 40, 50, 60, 80, 100, 200])
    mb = rng.choice([0, 0, 1, 2, 5]) if mov else 0
    blk = 'подвижного блока' if mov else 'неподвижного блока'
    btxt = f' Масса блока {mb} кг, трением пренебречь.' if mb else ' Блок и верёвку считать невесомыми, трением пренебречь.'
    F = Fr((m + mb) * G, 2 if mov else 1)
    if find == 'F':
        q = f'С помощью {blk} рабочий равномерно поднимает {load} массой {m} кг.{btxt} С какой силой он тянет за свободный конец верёвки?'
        x, unit = F, 'Н'
        wrong = [Fr(m * G), Fr(m * G, 2) if not mov else Fr(m * G, 4), Fr(m, 2)]
        e = f'F = {"(m + mб)g/2" if mov else "mg"} = {exact(F) or ""} Н.'
        p = P(find='F', m=m, mb=mb, mov=mov)
    else:
        q = f'Прикладывая к свободному концу верёвки силу {sx(F)} Н, рабочий с помощью {blk} равномерно поднимает {load}.{btxt} Какова масса груза?'
        x, unit = Fr(m), 'кг'
        wrong = [F / G, F * 2, F / G / 2]
        e = f'm = {"2F/g − mб" if mov else "F/g"} = {m} кг.'
        p = P(find='m', F=F, mb=mb, mov=mov)
    return ncard('ph-oge-07-pulley', q, x, unit, e, p, wrong)


def _solve_7osc(p):
    f = p['find']
    if f == 'T_half':
        return exact(2 * V(p, 't'))
    if f == 'nu_half':
        return exact(1 / (2 * V(p, 't')))
    if f == 'T_quarter':
        return exact(4 * V(p, 't'))
    if f == 'lam':
        return exact(V(p, 'v') / V(p, 'nu'))
    if f == 'v':
        return exact(V(p, 'lam') * V(p, 'nu'))
    if f == 'nu':
        return exact(V(p, 'N') / V(p, 't'))
    return exact(V(p, 'v') * V(p, 't') / 2)


@proto('ph-oge-07-oscillation-wave', 'ОГЭ', 7, 'Колебания и волны: период, частота, длина волны, эхо',
       invariant='T = t/N, ν = 1/T; от крайнего положения до крайнего — T/2, до положения равновесия — T/4; '
                 'λ = υ/ν; эхо: s = υt/2',
       varies='маятник (шарик на нити, груз на пружине, качели), волна (на воде, звук), что найти',
       answer_rule='по соответствующей формуле',
       mistakes=['время «от крайнего до крайнего» принимают за период', 'эхо: забывают делить на 2', 'λ = υν'],
       solve=_solve_7osc, kes=['1.24', '1.25', '1.27', '1.28'],
       fidelity=FN('1.24–1.28', 'маятники с периодами 0,2–4 с, звук 340 м/с (дано в условии)',
                   'доля периода; путь звука туда и обратно', ', ответ в с, Гц, м или м/с'))
def g_7osc(rng):
    find = rng.choice(['T_half', 'nu_half', 'T_quarter', 'lam', 'v', 'nu', 'echo'])
    if find in ('T_half', 'nu_half', 'T_quarter'):
        who = rng.choice(['шарик на нити', 'груз на пружине', 'маятник настенных часов', 'качели с ребёнком', 'люстра, раскачавшаяся от сквозняка'])
        t = rng.choice([Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1, Fr(3, 2), 2])
        if find == 'T_quarter':
            q = f'Наблюдая свободные колебания (объект — {who}), ученик заметил, что движение от крайнего положения к положению равновесия занимает {sx(t)} с. Определите период колебаний.'
            x, unit, wrong = 4 * t, 'с', [2 * t, t, 1 / (4 * t)]
            e = f'От крайнего положения до положения равновесия — четверть периода: T = 4·{sx(t)} = {exact(4 * t) or ""} с.'
        else:
            q = f'Наблюдая свободные колебания (объект — {who}), ученик заметил, что переход из одного крайнего положения в другое занимает {sx(t)} с. Чему равна {"частота" if find == "nu_half" else "период"} колебаний?'
            if find == 'nu_half':
                q = q.replace('Чему равна частота', 'Чему равна частота')
                x, unit, wrong = 1 / (2 * t), 'Гц', [1 / t, 2 * t, 1 / (4 * t)]
                e = f'T = 2·{sx(t)} = {sx(2 * t)} с, ν = 1/T = {exact(x) or ""} Гц.'
            else:
                q = q.replace('Чему равна период', 'Чему равен период')
                x, unit, wrong = 2 * t, 'с', [t, 4 * t, 1 / (2 * t)]
                e = f'Из одного крайнего положения в другое — половина периода: T = 2·{sx(t)} = {exact(2 * t) or ""} с.'
        p = P(find=find, t=t)
    elif find in ('lam', 'v'):
        kind = rng.choice(['water', 'sound'])
        if kind == 'water':
            nu = rng.choice([Fr(1, 2), 1, 2, Fr(5, 2), 4, 5])
            lam = rng.choice([Fr(1, 5), Fr(1, 2), 1, Fr(3, 2), 2, 3])
            v = lam * nu
            src = 'по поверхности озера бежит волна'
        else:
            v = 340
            nu = rng.choice([170, 340, 680, 850, 1360, 1700])
            lam = Fr(v, nu)
            src = 'в воздухе распространяется звуковая волна'
        if find == 'lam':
            q = f'Со скоростью {sx(v)} м/с {src}; частота колебаний частиц среды {sx(nu)} Гц. Чему равна длина волны?'
            x, unit, wrong = lam, 'м', [v * nu, nu / v, v / nu / 2]
            e = f'λ = υ/ν = {sx(v)}/{sx(nu)} = {exact(lam) or ""} м.'
            p = P(find='lam', v=v, nu=nu)
        else:
            q = f'Известно, что {src} с длиной волны {sx(lam)} м и частотой {sx(nu)} Гц. Определите скорость распространения волны.'
            x, unit, wrong = v, 'м/с', [lam / nu, nu / lam, lam * nu * 2]
            e = f'υ = λν = {sx(lam)}·{sx(nu)} = {exact(v) or ""} м/с.'
            p = P(find='v', lam=lam, nu=nu)
    elif find == 'nu':
        N = rng.choice([10, 20, 30, 40, 50, 60])
        t = rng.choice([5, 10, 15, 20, 25, 30, 40])
        who = rng.choice(['поплавок на волнах', 'груз на пружине', 'ветка дерева на ветру', 'маятник'])
        q = f'За {t} с {who} совершил {N} полных колебаний. Определите частоту колебаний.'
        if who.startswith('ветка'):
            q = q.replace('совершил', 'совершила')
        x, unit, wrong = Fr(N, t), 'Гц', [Fr(t, N), Fr(N * t), Fr(N, t) * 2]
        e = f'ν = N/t = {N}/{t} = {exact(x) or ""} Гц.'
        p = P(find='nu', N=N, t=t)
    else:
        t = rng.choice([1, 2, 3, 4, 5, 6])
        v = rng.choice([340, 1500]) if rng.random() < 0.7 else 340
        who = ('Турист крикнул, стоя перед отвесной скалой, и услышал эхо' if v == 340 else
               'Эхолот судна послал звуковой импульс ко дну и принял отражённый сигнал')
        q = f'{who} через {t} с. Скорость звука {"в воздухе" if v == 340 else "в воде"} {v} м/с. На каком расстоянии {"находится скала" if v == 340 else "от эхолота находится дно"}?'
        x, unit, wrong = Fr(v * t, 2), 'м', [Fr(v * t), Fr(v, t), Fr(v * t, 4)]
        e = f'Звук прошёл путь туда и обратно: s = υt/2 = {v}·{t}/2 = {exact(x)} м.'
        p = P(find='echo', v=v, t=t)
    return ncard('ph-oge-07-oscillation-wave', q, x, unit, e, p, wrong)


