def _solve_11n(p):
    A, Z = p['A'], p['Z']
    return exact({'p': Z, 'n': A - Z, 'e': Z, 'nucl': A}[p['what']])


@proto('ph-oge-11-nucleons', 'ОГЭ', 11, 'Состав атома и ядра: протоны, нейтроны, электроны, нуклоны',
       invariant='Z — число протонов (и электронов нейтрального атома), A — число нуклонов, N = A − Z',
       varies='изотоп (обозначение ᴬ_ZX или словами), что найти',
       answer_rule='протонов Z, нейтронов A − Z, электронов Z, нуклонов A',
       mistakes=['нейтроны = A', 'электроны = A − Z'],
       solve=_solve_11n, kes=['4.2', '4.3'],
       fidelity=FN('4.2–4.3', 'изотопы из банка и Периодической системы', 'N = A − Z'))
def g_11n(rng):
    sym, name, Z, A = rng.choice(NUCL)
    what = rng.choice(['p', 'n', 'n', 'e', 'nucl'])
    mode = rng.choice(['sym', 'word'])
    iso = f'ядро изотопа {name} {nuc(A, Z, sym)}' if mode == 'sym' else f'ядро изотопа {name}-{A} (порядковый номер {Z})'
    atom = f'нейтральный атом изотопа {name} {nuc(A, Z, sym)}' if mode == 'sym' else f'нейтральный атом {name}-{A} (порядковый номер {Z})'
    qq = {'p': f'Определите число протонов, входящих в {iso}.', 'n': f'Определите число нейтронов, входящих в {iso}.',
          'e': f'Определите число электронов, которые имеет {atom}.', 'nucl': f'Определите общее число нуклонов, из которых состоит {iso}.'}[what]
    if what == 'nucl' and mode == 'word':
        qq = (f'В ядре атома {name} содержится {Z} протонов и {A - Z} нейтронов. Каково массовое число этого изотопа?')
    x = {'p': Z, 'n': A - Z, 'e': Z, 'nucl': A}[what]
    e = f'Z = {Z}, A = {A}: протонов {Z}, нейтронов {A - Z}, электронов (в нейтральном атоме) {Z}.'
    wrong = [A, A - Z, Z, A + Z]
    return ncard('ph-oge-11-nucleons', qq, Fr(x), '', e, {'A': A, 'Z': Z, 'what': what}, [w for w in wrong if w != x])


def _solve_11d(p):
    A, Z = p['A'], p['Z']
    for d in p['chain']:
        if d == 'a':
            A, Z = A - 4, Z - 2
        else:
            Z = Z + 1
    if p['dir'] == 'back':
        A, Z = p['A'], p['Z']
        for d in p['chain']:
            if d == 'a':
                A, Z = A + 4, Z + 2
            else:
                Z = Z - 1
    return str(A if p['ask'] == 'A' else Z)


@proto('ph-oge-11-decay', 'ОГЭ', 11, 'α- и β-распад: массовое и зарядовое число продукта (или исходного ядра)',
       invariant='α-распад: A − 4, Z − 2; β⁻-распад: A не меняется, Z + 1; законы сохранения заряда и массового числа',
       varies='ядро, тип и число распадов (1–2), прямая или обратная задача, что спрашивают (A или Z)',
       answer_rule='применить правила смещения нужное число раз',
       mistakes=['при β-распаде уменьшают Z', 'при α-распаде A − 2', 'путают прямую и обратную задачу'],
       solve=_solve_11d, kes=['4.1', '4.4', '4.5'],
       fidelity=FN('4.1', 'как в банке: «изотоп тория ²³⁰₉₀Th испытывает α-распад…», два последовательных α-распада',
                   'правила смещения'))
def g_11d(rng):
    direction = rng.choice(['fwd', 'fwd', 'back'])
    if direction == 'fwd':
        # прямая задача — только реально радиоактивные ядра с их типом распада
        sym, name, Z, A, d0 = rng.choice(RADIO)
        chain = [d0] if rng.random() < 0.7 or d0 == 'b' else [d0, d0]
    else:
        sym, name, Z, A = rng.choice([x for x in NUCL if x[2] >= 20])
        chain = rng.choice([['a'], ['b'], ['a', 'a'], ['a', 'b']] if Z > 60 else [['b']])
    ask = rng.choice(['A', 'Z'])
    desc = {('a',): 'α-распад', ('b',): 'β⁻-распад', ('a', 'a'): 'два последовательных α-распада',
            ('b', 'b'): 'два последовательных β⁻-распада', ('a', 'b'): 'α-распад, а затем β⁻-распад'}[tuple(chain)]
    wA = 'массовое' if ask == 'A' else 'зарядовое'
    if direction == 'fwd':
        q = f'Радиоактивное ядро {nuc(A, Z, sym)} (изотоп {name}) претерпевает {desc}. Определите {wA} число ядра — продукта распада.'
    else:
        dg = {('a',): 'α-распада', ('b',): 'β⁻-распада', ('a', 'a'): 'двух последовательных α-распадов',
              ('b', 'b'): 'двух последовательных β⁻-распадов', ('a', 'b'): 'α-распада и последующего β⁻-распада'}[tuple(chain)]
        q = f'Ядро {nuc(A, Z, sym)} (изотоп {name}) появилось вследствие {dg} некоторого материнского ядра. Определите {wA} число материнского ядра.'
    p = {'A': A, 'Z': Z, 'chain': chain, 'dir': direction, 'ask': ask}
    x = int(_solve_11d(p))
    e = 'α-распад: A − 4, Z − 2; β⁻-распад: Z + 1, A не меняется. Ответ: ' + str(x) + '.'
    wrong = [A - 2, Z - 1, A + 4, Z + 2, A, Z]
    return ncard('ph-oge-11-decay', q, Fr(x), '', e, p, [w for w in wrong if w != x])


