PSYM = {(1, 0, 'n'): '¹₀n', (1, 1, 'p'): '¹₁p', (4, 2, 'He'): '⁴₂He'}


def _solve_11r(p):
    A = sum(a for a, z in p['L']) - sum(a for a, z in p['R'])
    Z = sum(z for a, z in p['L']) - sum(z for a, z in p['R'])
    return str(A if p['ask'] == 'A' else Z)


@proto('ph-oge-11-reaction', 'ОГЭ', 11, 'Ядерная реакция: массовое/зарядовое число неизвестной частицы',
       invariant='сумма массовых чисел и сумма зарядовых чисел до и после реакции одинаковы',
       varies='реакция (синтез, деление, α-частицы, нейтроны), что спрашивают',
       answer_rule='A_X = ΣA до − ΣA после (известных), Z_X — аналогично',
       mistakes=['забывают коэффициент перед нейтронами', 'путают A и Z'],
       solve=_solve_11r, kes=['4.5'],
       fidelity=FN('4.5', 'как в демоверсии 2027 №11 (²³⁸U + ¹²C → X + 4n)', 'коэффициенты перед частицами'))
def g_11r(rng):
    L, R, X = rng.choice(REACT11)
    ask = rng.choice(['A', 'Z'])
    render = lambda t: PSYM.get(t, nuc(*t))
    from collections import Counter as _C
    def side(xs):
        cnt = _C(xs)
        return ' + '.join((f'{k}' if k > 1 else '') + render(t) for t, k in cnt.items())
    rhs_parts = [t for t in R]
    rng.shuffle(rhs_parts)
    if R:
        eq = f'{side(L)} → X + {side(R)}' if rng.random() < 0.5 else f'{side(L)} → {side(R)} + X'
    else:
        eq = f'{side(L)} → X'
    wA = "массовое" if ask == "A" else "зарядовое"
    q = rng.choice([f'Определите {wA} число ядра (частицы) X в ядерной реакции {eq}.',
                    f'Ядерная реакция записана так: {eq}. Чему равно {wA} число X?',
                    f'При бомбардировке ядер протекает реакция {eq}. Найдите {wA} число X.'])
    p = {'L': [[a, z] for a, z, s in L], 'R': [[a, z] for a, z, s in R], 'ask': ask}
    x = int(_solve_11r(p))
    if x < 0:
        raise Retry
    e = f'Сохраняются суммы массовых и зарядовых чисел: X = ᴬ_Z с A = {X[0]}, Z = {X[1]}.'
    wrong = [X[0] + 1, X[1] + 1, X[0] if ask == 'Z' else X[1], sum(a for a, z, s in L)]
    c = ncard('ph-oge-11-reaction', q, Fr(x) if x > 0 else Fr(1), '', e, p, [w for w in wrong if w != x])
    if x == 0:
        c['a'] = '0'
    return c


def _solve_11hl(p):
    f = p['find']
    if f == 'N':
        return exact(V(p, 'N0') / 2 ** (V(p, 't') / V(p, 'T')))
    if f == 'T':
        n = 0
        N0, N = V(p, 'N0'), V(p, 'N')
        while N0 > N:
            N0 /= 2
            n += 1
        return exact(V(p, 't') / n)
    return exact(V(p, 'T') * V(p, 'n'))


@proto('ph-oge-11-half-life', 'ОГЭ', 11, 'Период полураспада: сколько ядер (граммов) останется, найти период',
       invariant='за каждый период полураспада число нераспавшихся ядер уменьшается вдвое',
       varies='изотоп, начальное число ядер или масса, время (кратно T), что найти',
       answer_rule='N = N₀/2^(t/T); T = t/n, где 2ⁿ = N₀/N; t = nT',
       mistakes=['N = N₀ − N₀·t/(2T)', 'считают число распавшихся вместо оставшихся'],
       solve=_solve_11hl, kes=['4.1'],
       fidelity=FN('4.1', 'как в банке: график N(t) заменён данными; периоды — часы, дни, годы', 'остаток vs распавшиеся',
                   ', ответ в числах ядер, граммах, сутках или годах'))
def g_11hl(rng):
    find = rng.choice(['N', 'N', 'T', 't'])
    iso, T, unit_t = rng.choice([('йода-131', 8, 'сут'), ('радона-222', 4, 'сут'), ('кобальта-60', 5, 'лет'),
                                 ('стронция-90', 29, 'лет'), ('цезия-137', 30, 'лет'), ('фосфора-32', 14, 'сут'),
                                 ('натрия-24', 15, 'ч')])
    n = rng.choice([1, 2, 3, 4])
    t = T * n
    ut = {'сут': 'сут', 'лет': 'лет', 'ч': 'ч'}[unit_t]
    kind = rng.choice(['N', 'm'])
    N0 = rng.choice([800, 1600, 2000, 4000, 8000, 16000]) if kind == 'N' else rng.choice([8, 16, 32, 40, 64, 80, 120, 160])
    N = Fr(N0, 2 ** n)
    what0 = f'{N0} ядер' if kind == 'N' else f'{N0} г'
    unit_a = '' if kind == 'N' else 'г'
    if find == 'N':
        q = f'В образце содержалось {what0} радиоактивного {iso}, период полураспада которого {T} {ut}. {"Сколько ядер" if kind == "N" else "Какая масса"} этого изотопа останется нераспавшимся через {t} {ut}?'
        q = q.replace('нераспавшимся', 'нераспавшейся') if kind == 'm' else q
        x, unit = N, unit_a
        wrong = [N0 - N, Fr(N0, 2 * n), Fr(N0, n)]
        e = f'n = t/T = {n}; N = N₀/2ⁿ = {N0}/{2 ** n} = {exact(N) or ""}.'
        p = P(find='N', N0=N0, t=t, T=T)
    elif find == 'T':
        q = f'За {t} {ut} количество нераспавшихся ядер радиоактивного изотопа уменьшилось в {2 ** n} раз{"а" if 2 ** n < 5 else ""}. Чему равен период полураспада изотопа?'
        x, unit = Fr(T), ut
        wrong = [Fr(t, 2 ** n), Fr(t * 2), Fr(t, 2) if n != 2 else Fr(t)]
        e = f'{2 ** n} = 2^{n}, значит прошло {n} периода(ов): T = {t}/{n} = {T} {ut}.'
        p = P(find='T', N0=2 ** n, N=1, t=t)
    else:
        q = f'Период полураспада {iso} {T} {ut}. Через какое время из {what0} этого изотопа останется {sx(N)}{" ядер" if kind == "N" else " г"}?'
        x, unit = Fr(t), ut
        wrong = [Fr(T * 2 ** n), Fr(T, n), Fr(T * (n + 1))]
        e = f'{N0}/{sx(N)} = {2 ** n} = 2^{n}, t = {n}T = {t} {ut}.'
        p = P(find='t', T=T, n=n)
    if exact(x) is None:
        raise Retry
    return ncard('ph-oge-11-half-life', q, x, unit, e, p, wrong)


# =====================================================================================================================
# ЗАДАНИЯ 12–13. Как изменяются величины (соответствие: величина → увеличивается/уменьшается/не изменяется)
# =====================================================================================================================
# Генератор берёт ожидаемый характер изменения из «правила» сценария; solve() пересчитывает его НЕЗАВИСИМО —
# по численной модели процесса (значения величины до и после), сравнивая числа.

CH3 = ['увеличивается', 'уменьшается', 'не изменяется']
CH3_PAST = ['увеличилась', 'уменьшилась', 'не изменилась']
UP, DOWN, SAME = '1', '2', '3'


def _cmp(b, a):
    return UP if a > b else DOWN if a < b else SAME


# ---- численные модели (для solve)

def _m_throw(p):
    m, g, H = 1, 10, Fr(20)  # полная энергия = mgH
    h1, h2 = (Fr(5), Fr(12)) if p['dir'] == 'up' else (Fr(12), Fr(5))
    Ek = lambda h: m * g * (H - h)
    return {'скорость': (Ek(h1) * 2, Ek(h2) * 2), 'кинетическая энергия': (Ek(h1), Ek(h2)),
            'потенциальная энергия': (m * g * h1, m * g * h2), 'полная механическая энергия': (m * g * H, m * g * H),
            'ускорение': (g, g), 'модуль импульса': (Ek(h1), Ek(h2))}


def _m_pend(p):
    A, k = Fr(10), 1
    x1, x2 = (A, Fr(3)) if p['dir'] == 'to_eq' else (Fr(3), A)
    E = k * A * A / 2
    Ep = lambda x: k * x * x / 2
    return {'кинетическая энергия': (E - Ep(x1), E - Ep(x2)), 'потенциальная энергия': (Ep(x1), Ep(x2)),
            'полная механическая энергия': (E, E), 'скорость груза': (E - Ep(x1), E - Ep(x2)),
            'период колебаний': (Fr(2), Fr(2))}


def _m_stop(p):
    v1, v2 = Fr(5), Fr(1)
    E0 = 100
    return {'кинетическая энергия': (v1 * v1 / 2, v2 * v2 / 2), 'внутренняя энергия': (E0, E0 + (v1 * v1 - v2 * v2) / 2),
            'полная энергия (механическая и внутренняя)': (E0 + v1 * v1 / 2, E0 + v1 * v1 / 2),
            'масса': (Fr(1), Fr(1))}


def _m_orbit(p):
    r1, r2 = (Fr(1), Fr(2)) if p['dir'] == 'out' else (Fr(2), Fr(1))
    v = lambda r: 1 / r  # квадрат скорости ~ 1/r
    return {'скорость движения': (v(r1), v(r2)), 'период обращения': (r1 ** 3, r2 ** 3),
            'сила притяжения к Земле': (1 / r1 ** 2, 1 / r2 ** 2), 'центростремительное ускорение': (1 / r1 ** 2, 1 / r2 ** 2)}


def _m_dyn(p):
    mg, rho, V = Fr(20), 1000, Fr(1, 1000)
    s1, s2 = (Fr(1), Fr(1, 2)) if p['stage'] == 'emerge' else (Fr(1), Fr(1))
    if p['stage'] == 'sink':
        s1, s2 = Fr(1, 3), Fr(1)
    Fa = lambda s: rho * 10 * V * s
    return {'показания динамометра': (mg - Fa(s1), mg - Fa(s2)), 'выталкивающая сила': (Fa(s1), Fa(s2)),
            'сила тяжести, действующая на груз': (mg, mg)}


def _m_float(p):
    m = Fr(1000)
    r1, r2 = (Fr(1000), Fr(1030)) if p['dir'] == 'to_sea' else (Fr(1030), Fr(1000))
    return {'глубина погружения (осадка)': (m / r1, m / r2), 'выталкивающая сила': (m, m), 'сила тяжести': (m, m)}


def _m_gas(p):
    if p['mode'] == 'iso':
        V1, V2 = (Fr(2), Fr(1)) if p['dir'] == 'down' else (Fr(1), Fr(2))
        T1 = T2 = Fr(300)
    else:
        V1 = V2 = Fr(1)
        T1, T2 = (Fr(300), Fr(360)) if p['dir'] == 'heat' else (Fr(360), Fr(300))
    return {'давление газа': (T1 / V1, T2 / V2), 'плотность газа': (1 / V1, 1 / V2), 'объём газа': (V1, V2),
            'масса газа': (Fr(1), Fr(1)), 'средняя скорость теплового движения молекул': (T1, T2),
            'внутренняя энергия газа': (T1, T2)}


def _m_heat(p):
    T1, T2 = (Fr(20), Fr(80)) if p['dir'] == 'heat' else (Fr(80), Fr(20))
    V = lambda T: 1 + T / 10000
    return {'внутренняя энергия': (T1, T2), 'средняя скорость движения молекул': (T1, T2),
            'плотность вещества': (1 / V(T1), 1 / V(T2)), 'объём тела': (V(T1), V(T2)), 'масса тела': (Fr(1), Fr(1))}


def _m_phase(p):
    t = Fr(p['t'])
    gain = p['proc'] in ('melt', 'boil')
    U1, U2 = (Fr(100), Fr(150)) if gain else (Fr(150), Fr(100))
    return {'температура': (t, t), 'внутренняя энергия': (U1, U2),
            'средняя кинетическая энергия молекул': (t, t), 'масса вещества': (Fr(1), Fr(1))}


def _m_incline(p):
    # брусок на наклонной плоскости с трением: движение вниз с ускорением или вверх после толчка
    h1, h2 = (Fr(2), Fr(1)) if p['dir'] == 'down' else (Fr(1), Fr(2))
    v1, v2 = (Fr(1), Fr(3)) if p['dir'] == 'down' else (Fr(3), Fr(1))
    Emech = lambda h, v: 10 * h + v * v / 2
    return {'скорость бруска': (v1, v2), 'потенциальная энергия бруска': (10 * h1, 10 * h2),
            'полная механическая энергия бруска': (Emech(h1, v1), Emech(h1, v1) - 3),
            'сила трения скольжения': (Fr(2), Fr(2)), 'сила тяжести': (Fr(10), Fr(10))}


def _solve_ch(p):
    models = {'throw': _m_throw, 'pend': _m_pend, 'stop': _m_stop, 'orbit': _m_orbit, 'dyn': _m_dyn,
              'float': _m_float, 'gas': _m_gas, 'heat': _m_heat, 'phase': _m_phase, 'incline': _m_incline,
              'net': _m_net, 'rheo': _m_rheo, 'spiral': _m_spiral, 'elec': _m_elec, 'ion': _m_ion, 'light': _m_light,
              'lens': _m_lens, 'mirror': _m_mirror, 'decay': _m_decay, 'eye': _m_eye, 'magnet': _m_magnet}
    vals = models[p['scen']](p)
    return {LET[i]: _cmp(*vals[q]) for i, q in enumerate(p['qs'])}


# ---- сценарии: (текст, {величина: правило '1'/'2'/'3'}, параметры)

def _sc_throw(rng):
    d = rng.choice(['up', 'down'])
    who = rng.choice(['Мяч', 'Камень', 'Снежок', 'Теннисный мяч', 'Резиновый мячик'])
    if d == 'up':
        t = rng.choice([f'{who} бросили вертикально вверх с поверхности земли. Рассмотрим его движение вверх до верхней точки.',
                        f'{who}, подброшенный вертикально вверх, поднимается к верхней точке траектории.'])
    else:
        t = rng.choice([f'{who} падает вниз с балкона из состояния покоя.', f'{who} свободно падает с крыши сарая на землю.'])
    t += ' Сопротивлением воздуха пренебречь.'
    r = {'скорость': UP if d == 'down' else DOWN, 'кинетическая энергия': UP if d == 'down' else DOWN,
         'потенциальная энергия': DOWN if d == 'down' else UP, 'полная механическая энергия': SAME, 'ускорение': SAME,
         'модуль импульса': UP if d == 'down' else DOWN}
    return t, r, {'dir': d}


def _sc_pend(rng):
    d = rng.choice(['to_eq', 'from_eq'])
    who = rng.choice(['Математический маятник (шарик на нити)', 'Груз на пружине', 'Качели'])
    path = 'от крайнего положения к положению равновесия' if d == 'to_eq' else 'от положения равновесия к крайнему положению'
    t = f'{who} совершает свободные незатухающие колебания. Рассмотрим движение {path}.'
    if who == 'Качели':
        t = t.replace('совершает', 'совершают')
    r = {'кинетическая энергия': UP if d == 'to_eq' else DOWN, 'потенциальная энергия': DOWN if d == 'to_eq' else UP,
         'полная механическая энергия': SAME, 'скорость груза': UP if d == 'to_eq' else DOWN, 'период колебаний': SAME}
    return t, r, {'dir': d}


def _sc_stop(rng):
    t = rng.choice(['Шайба, скользящая по льду, постепенно останавливается из-за трения.',
                    'Пуля пробивает деревянную доску и вылетает из неё с меньшей скоростью.',
                    'Санки, скатившиеся с горки, тормозят на горизонтальном участке и останавливаются.',
                    'Автомобиль с выключенным двигателем тормозит на горизонтальной дороге.',
                    'Мяч, катящийся по ровному газону, постепенно замедляется и останавливается.',
                    'Кёрлинговый камень скользит по льду и останавливается.',
                    'Велосипедист, перестав крутить педали, катится по ровной дороге и останавливается.'])
    r = {'кинетическая энергия': DOWN, 'внутренняя энергия': UP, 'полная энергия (механическая и внутренняя)': SAME,
         'масса': SAME}
    return t + ' Рассматривается система «тело и окружающие тела».', r, {}


def _sc_orbit(rng):
    d = rng.choice(['out', 'in'])
    who = rng.choice(['Искусственный спутник Земли', 'Космический корабль', 'Орбитальная станция'])
    t = f'{who} перешёл с одной круговой орбиты вокруг Земли на другую круговую орбиту {"большего" if d == "out" else "меньшего"} радиуса.'
    if who == 'Орбитальная станция':
        t = t.replace('перешёл', 'перешла')
    r = {'скорость движения': DOWN if d == 'out' else UP, 'период обращения': UP if d == 'out' else DOWN,
         'сила притяжения к Земле': DOWN if d == 'out' else UP, 'центростремительное ускорение': DOWN if d == 'out' else UP}
    return t, r, {'dir': d}


def _sc_dyn(rng):
    st = rng.choice(['emerge', 'sink', 'inside'])
    load = rng.choice(['металлический цилиндр', 'гирю', 'камень', 'латунный груз'])
    if st == 'emerge':
        t = f'Подвешенный к динамометру {load} медленно вытаскивают из стакана с водой: часть груза уже над водой, и она увеличивается.'
    elif st == 'sink':
        t = f'Подвешенный к динамометру {load} медленно опускают в стакан с водой от момента касания воды до полного погружения.'
    else:
        t = f'Подвешенный к динамометру {load}, полностью погружённый в воду, медленно поднимают, не вынимая из воды.'
    t = t.replace('Подвешенный к динамометру гирю', 'Подвешенную к динамометру гирю')
    Fa = {'emerge': DOWN, 'sink': UP, 'inside': SAME}[st]
    dyn = {'emerge': UP, 'sink': DOWN, 'inside': SAME}[st]
    r = {'показания динамометра': dyn, 'выталкивающая сила': Fa, 'сила тяжести, действующая на груз': SAME}
    return t, r, {'stage': st}


def _sc_float(rng):
    d = rng.choice(['to_sea', 'to_river'])
    who = rng.choice(['Грузовой теплоход', 'Катер', 'Буксир', 'Плот', 'Танкер', 'Рыболовецкий траулер', 'Прогулочная яхта'])
    t = f'{who} {"выходит из устья реки в море" if d == "to_sea" else "заходит из моря в пресноводную реку"} (солёная вода плотнее пресной). Масса судна не меняется.'
    if who == 'Плот':
        t = t.replace('Масса судна', 'Масса плота')
    if who == 'Прогулочная яхта':
        t = t.replace('выходит', 'выходит').replace('Масса судна', 'Масса яхты')
    r = {'глубина погружения (осадка)': DOWN if d == 'to_sea' else UP, 'выталкивающая сила': SAME, 'сила тяжести': SAME}
    return t, r, {'dir': d}


def _sc_gas(rng):
    mode = rng.choice(['iso', 'heat'])
    if mode == 'iso':
        d = rng.choice(['down', 'up'])
        t = (f'Газ находится в цилиндре под герметичным поршнем. Поршень медленно {"вдвигают внутрь" if d == "down" else "выдвигают наружу"}; '
             'температура газа при этом не меняется.')
        r = {'давление газа': UP if d == 'down' else DOWN, 'плотность газа': UP if d == 'down' else DOWN,
             'объём газа': DOWN if d == 'down' else UP, 'масса газа': SAME, 'средняя скорость теплового движения молекул': SAME}
    else:
        d = rng.choice(['heat', 'cool'])
        t = f'Газ в плотно закрытом жёстком баллоне {"нагревают" if d == "heat" else "охлаждают"}.'
        r = {'давление газа': UP if d == 'heat' else DOWN, 'плотность газа': SAME, 'объём газа': SAME, 'масса газа': SAME,
             'средняя скорость теплового движения молекул': UP if d == 'heat' else DOWN,
             'внутренняя энергия газа': UP if d == 'heat' else DOWN}
    return t, r, {'mode': mode, 'dir': d}


def _sc_heat(rng):
    d = rng.choice(['heat', 'cool'])
    who = rng.choice(['Стальной шарик', 'Медная монета', 'Алюминиевая ложка', 'Свинцовая пластинка'])
    how = rng.choice(['в пламени спиртовки', 'в кипящей воде']) if d == 'heat' else rng.choice(['в морозильной камере', 'на морозе'])
    t = f'{who} {"нагревают" if d == "heat" else "охлаждают"} {how} (агрегатное состояние не меняется).'
    t = t.replace(f'{who} нагревают', f'{who} нагревают').replace('Медная монета нагревают', 'Медную монету нагревают')
    t = {'Медная монета': t.replace('Медная монета', 'Медную монету'), 'Алюминиевая ложка': t.replace('Алюминиевая ложка', 'Алюминиевую ложку'),
         'Свинцовая пластинка': t.replace('Свинцовая пластинка', 'Свинцовую пластинку')}.get(who, t)
    r = {'внутренняя энергия': UP if d == 'heat' else DOWN, 'средняя скорость движения молекул': UP if d == 'heat' else DOWN,
         'плотность вещества': DOWN if d == 'heat' else UP, 'объём тела': UP if d == 'heat' else DOWN, 'масса тела': SAME}
    return t, r, {'dir': d}


def _sc_phase(rng):
    proc, t_, txt = rng.choice([('melt', 0, 'Лёд, нагретый до 0 °С, плавится в тёплой комнате.'),
                                ('cryst', 0, 'Вода, охлаждённая до 0 °С, кристаллизуется на морозе.'),
                                ('boil', 100, 'Вода в открытом чайнике кипит при нормальном атмосферном давлении.'),
                                ('cond', 100, 'Водяной пар при 100 °С конденсируется на холодной крышке, превращаясь в воду той же температуры.'),
                                ('melt', 232, 'Олово в тигле, нагретое до температуры плавления, плавится.'),
                                ('cryst', 327, 'Расплавленный свинец при температуре кристаллизации затвердевает.')])
    gain = proc in ('melt', 'boil')
    r = {'температура': SAME, 'внутренняя энергия': UP if gain else DOWN, 'средняя кинетическая энергия молекул': SAME,
         'масса вещества': SAME}
    return txt, r, {'proc': proc, 't': t_}


def _sc_incline(rng):
    d = rng.choice(['down', 'up'])
    where = rng.choice(['наклонной плоскости', 'наклонной доски', 'деревянного жёлоба, установленного под углом'])
    t = (f'Брусок соскальзывает с {where} с ускорением. Трение между бруском и поверхностью есть.' if d == 'down' else
         f'Бруску сообщили скорость, направленную вверх вдоль {where}, и он скользит вверх, замедляясь. Трение есть.')
    r = {'скорость бруска': UP if d == 'down' else DOWN, 'потенциальная энергия бруска': DOWN if d == 'down' else UP,
         'полная механическая энергия бруска': DOWN, 'сила трения скольжения': SAME, 'сила тяжести': SAME}
    return t, r, {'dir': d}


SC12 = {'throw': _sc_throw, 'pend': _sc_pend, 'stop': _sc_stop, 'orbit': _sc_orbit, 'dyn': _sc_dyn, 'float': _sc_float,
        'gas': _sc_gas, 'heat': _sc_heat, 'phase': _sc_phase, 'incline': _sc_incline}


# ---- 13: электромагнитные и квантовые

def _m_net(p):
    n1, n2 = (p['n'], p['n'] + p['k']) if p['dir'] == 'on' else (p['n'] + p['k'], p['n'])
    U, R = Fr(220), Fr(100)
    return {'общее сопротивление цепи': (R / n1, R / n2), 'общая сила тока': (U * n1 / R, U * n2 / R),
            'общая потребляемая мощность': (U * U * n1 / R, U * U * n2 / R), 'напряжение на каждом приборе': (U, U)}


def _m_rheo(p):
    E, R1 = Fr(12), Fr(4)
    r1, r2 = (Fr(2), Fr(6)) if p['dir'] == 'more' else (Fr(6), Fr(2))
    I = lambda r: E / (R1 + r)
    el = p.get('el', 'резистор')
    return {'сила тока в цепи': (I(r1), I(r2)), f'напряжение на элементе «{el}»': (I(r1) * R1, I(r2) * R1),
            'напряжение на реостате': (I(r1) * r1, I(r2) * r2), f'сопротивление элемента «{el}»': (R1, R1)}


def _m_spiral(p):
    U = Fr(220)
    R1, R2 = (Fr(50), Fr(40)) if p['dir'] == 'short' else (Fr(40), Fr(50))
    return {'сопротивление спирали': (R1, R2), 'сила тока в спирали': (U / R1, U / R2), 'мощность прибора': (U * U / R1, U * U / R2),
            'напряжение на спирали': (U, U)}


def _m_elec(p):
    if p.get('sub') == 'ion':
        return _m_ion(p)
    e_rod = 1 if p['rod'] == 'ebonite' else -1  # эбонит получает электроны, стекло отдаёт
    Ne, me = Fr(10 ** 6), Fr(1, 10 ** 9)
    rod = (Ne, Ne + e_rod * 1000)
    cloth = (Ne, Ne - e_rod * 1000)
    return {'число электронов на палочке': rod, 'масса палочки': (rod[0] * me + 5, rod[1] * me + 5),
            'число электронов на ткани': cloth, 'масса ткани': (cloth[0] * me + 7, cloth[1] * me + 7),
            'число протонов в палочке': (Fr(5), Fr(5))}


def _m_ion(p):
    Z = 11
    ne2 = Z + 1 if p['ion'] == 'neg' else Z - 1
    return {'число электронов': (Fr(Z), Fr(ne2)), 'заряд ядра': (Fr(Z), Fr(Z)), 'число протонов': (Fr(Z), Fr(Z)),
            'масса частицы': (Fr(23) + Fr(Z, 1836), Fr(23) + Fr(ne2, 1836))}


NIDX = {'воздух': Fr(1), 'вода': Fr(4, 3), 'стекло': Fr(3, 2)}


def _m_light(p):
    n1, n2 = NIDX[p['m1']], NIDX[p['m2']]
    return {'скорость распространения света': (1 / n1, 1 / n2), 'длина волны': (1 / n1, 1 / n2),
            'частота световой волны': (Fr(1), Fr(1))}


def _m_lens(p):
    if p.get('sub') == 'mirror':
        return _m_mirror(p)
    F = Fr(10)
    d1, d2 = Fr(p['d1']) * F, Fr(p['d2']) * F
    f = lambda d: d * F / (d - F)
    return {'расстояние от линзы до изображения': (f(d1), f(d2)), 'размер изображения': (f(d1) / d1, f(d2) / d2),
            'фокусное расстояние линзы': (F, F)}


def _m_mirror(p):
    d1, d2 = (Fr(1), Fr(2)) if p['dir'] == 'away' else (Fr(2), Fr(1))
    return {'размер изображения': (Fr(1), Fr(1)), 'расстояние от предмета до изображения': (2 * d1, 2 * d2),
            'расстояние от зеркала до изображения': (d1, d2)}


def _m_decay(p):
    A, Z = 226, 88
    A2, Z2 = (A - 4, Z - 2) if p['kind'] == 'a' else (A, Z + 1)
    return {'зарядовое число ядра': (Fr(Z), Fr(Z2)), 'массовое число ядра': (Fr(A), Fr(A2)),
            'число нейтронов в ядре': (Fr(A - Z), Fr(A2 - Z2)), 'число протонов в ядре': (Fr(Z), Fr(Z2))}


def _m_eye(p):
    d1, d2 = (Fr(1000), Fr(1, 4)) if p['dir'] == 'near' else (Fr(1, 4), Fr(1000))
    f_img = Fr(17, 1000)
    Dp = lambda d: 1 / d + 1 / f_img
    return {'оптическая сила хрусталика': (Dp(d1), Dp(d2)), 'фокусное расстояние хрусталика': (1 / Dp(d1), 1 / Dp(d2)),
            'расстояние от хрусталика до сетчатки': (f_img, f_img)}


def _sc_core(rng):
    ins = rng.random() < 0.5
    coil = rng.choice(['катушки с током', 'катушки школьного электромагнита', 'обмотки реле', 'катушки, подключённой к батарейке'])
    coil_acc = coil.replace('катушки', 'катушку').replace('обмотки', 'обмотку').replace('подключённой', 'подключённую')
    t = (f'Из {coil} вынули железный сердечник. Сила тока не изменилась.' if not ins else
         f'В {coil_acc} вставили железный сердечник. Сила тока не изменилась.')
    r = {'магнитное действие катушки': UP if ins else DOWN, 'число притянутых гвоздей': UP if ins else DOWN,
         'сопротивление обмотки': SAME}
    return t, r, {'what': 'core_in' if ins else 'core_out'}


def _m_magnet(p):
    if p['what'].startswith('core'):
        mu1, mu2 = (Fr(1), Fr(100)) if p['what'] == 'core_in' else (Fr(100), Fr(1))
        return {'магнитное действие катушки': (mu1, mu2), 'число притянутых гвоздей': (mu1 // 2, mu2 // 2),
                'сопротивление обмотки': (Fr(3), Fr(3))}
    n1, n2 = (Fr(100), Fr(200)) if p['what'] == 'turns' else (Fr(100), Fr(100))
    I1, I2 = (Fr(1), Fr(1)) if p['what'] == 'turns' else ((Fr(1), Fr(2)) if p['what'] == 'current_up' else (Fr(2), Fr(1)))
    return {'магнитное действие катушки': (n1 * I1, n2 * I2), 'число притянутых гвоздей': (n1 * I1 // 50, n2 * I2 // 50),
            'сопротивление обмотки': (n1, n2) if p['what'] == 'turns' else (Fr(1), Fr(1))}


def _sc_net(rng):
    d = rng.choice(['on', 'off'])
    place, devs = rng.choice([('На кухне', ['электрочайник', 'микроволновую печь', 'тостер', 'кофеварку']),
                              ('В комнате', ['настольную лампу', 'телевизор', 'обогреватель', 'пылесос']),
                              ('В мастерской', ['дрель', 'паяльник', 'точило', 'лампу'])])
    dev = rng.choice(devs)
    t = (f'{place} в сеть уже включены несколько приборов. {"Дополнительно в розетку включают" if d == "on" else "Из розетки выключают"} {dev} '
         '(все приборы подключены к сети параллельно).')
    r = {'общее сопротивление цепи': DOWN if d == 'on' else UP, 'общая сила тока': UP if d == 'on' else DOWN,
         'общая потребляемая мощность': UP if d == 'on' else DOWN, 'напряжение на каждом приборе': SAME}
    return t, r, {'dir': d, 'n': rng.choice([1, 2, 3]), 'k': 1}


def _sc_rheo(rng):
    d = rng.choice(['more', 'less'])
    el = rng.choice(['Резистор', 'Лампа', 'Нагревательный элемент', 'Электрический звонок'])
    src = rng.choice(['батарее', 'источнику постоянного напряжения', 'лабораторному блоку питания'])
    how = rng.choice([f'Ползунок реостата сдвигают так, что его сопротивление {"увеличивается" if d == "more" else "уменьшается"}.',
                      f'Ползунок реостата перемещают так, что длина включённой в цепь части обмотки {"увеличивается" if d == "more" else "уменьшается"}.'])
    t = f'{el} и реостат соединены последовательно и подключены к {src}. {how} Сопротивление элемента «{el.lower()}» считать постоянным.'
    r = {'сила тока в цепи': DOWN if d == 'more' else UP, 'напряжение на резисторе': DOWN if d == 'more' else UP,
         'напряжение на реостате': UP if d == 'more' else DOWN, 'сопротивление резистора': SAME}
    r = {k.replace('резисторе', 'элементе «' + el.lower() + '»').replace('резистора', 'элемента «' + el.lower() + '»'): v for k, v in r.items()}
    return t, r, {'dir': d, 'el': el.lower()}


def _sc_spiral(rng):
    d = rng.choice(['short', 'long'])
    dev = rng.choice(['электроплитки', 'паяльника', 'обогревателя'])
    t = (f'Перегоревшую спираль {dev} заменили: новая спираль из той же проволоки, но {"короче" if d == "short" else "длиннее"} '
         'прежней. Прибор включают в ту же сеть.')
    r = {'сопротивление спирали': DOWN if d == 'short' else UP, 'сила тока в спирали': UP if d == 'short' else DOWN,
         'мощность прибора': UP if d == 'short' else DOWN, 'напряжение на спирали': SAME}
    return t, r, {'dir': d}


def _sc_elec(rng):
    if rng.random() < 0.4:
        return _sc_ion(rng)
    rod = rng.choice(['ebonite', 'glass'])
    t = ('Эбонитовую палочку потёрли о шерстяную ткань, и палочка зарядилась отрицательно.' if rod == 'ebonite' else
         'Стеклянную палочку потёрли о шёлковую ткань, и палочка зарядилась положительно.')
    s = 1 if rod == 'ebonite' else -1
    r = {'число электронов на палочке': UP if s > 0 else DOWN, 'масса палочки': UP if s > 0 else DOWN,
         'число электронов на ткани': DOWN if s > 0 else UP, 'масса ткани': DOWN if s > 0 else UP,
         'число протонов в палочке': SAME}
    return t, r, {'rod': rod}


def _sc_ion(rng):
    ion = rng.choice(['neg', 'pos'])
    atom = rng.choice(['натрия', 'хлора', 'кислорода', 'калия', 'фтора', 'кальция', 'серы'])
    how = rng.choice(['В результате электризации', 'При ионизации', 'В ходе химической реакции'])
    t = f'{how} нейтральный атом {atom} превратился в {"отрицательный" if ion == "neg" else "положительный"} ион.'
    r = {'число электронов': UP if ion == 'neg' else DOWN, 'заряд ядра': SAME, 'число протонов': SAME,
         'масса частицы': UP if ion == 'neg' else DOWN}
    return t, r, {'ion': ion, 'sub': 'ion'}


def _sc_light(rng):
    m1, m2 = pick(rng, list(NIDX), 2)
    col = rng.choice(['красного', 'зелёного', 'синего', 'фиолетового'])
    src = rng.choice(['лазерной указки', 'лазерного уровня', 'светодиодного фонарика с фильтром'])
    to = {'воздух': 'в воздух', 'вода': 'в воду аквариума', 'стекло': 'в стеклянный брусок'}[m2]
    fr = {'воздух': 'из воздуха', 'вода': 'из воды аквариума', 'стекло': 'из стеклянного бруска'}[m1]
    if m1 != 'воздух' and m2 != 'воздух':
        to = {'вода': 'в воду', 'стекло': 'в стекло'}[m2]
        fr = {'вода': 'из воды', 'стекло': 'из стекла'}[m1]
    t = f'Узкий пучок {col} света от {src} проходит {fr} {to}.' + (' Показатель преломления стекла больше, чем воды.' if 'воздух' not in (m1, m2) else '')
    up = NIDX[m2] < NIDX[m1]
    r = {'скорость распространения света': UP if up else DOWN, 'длина волны': UP if up else DOWN,
         'частота световой волны': SAME}
    return t, r, {'m1': m1, 'm2': m2}


def _sc_lens(rng):
    if rng.random() < 0.3:
        return _sc_mirror(rng)
    d1, d2 = rng.choice([(3, 2), (4, 3), (Fr(5, 2), Fr(3, 2)), (Fr(3, 2), Fr(5, 4)), (2, 3), (Fr(3, 2), 3), (Fr(5, 4), 2)])
    desc = lambda d: ('за двойным фокусным расстоянием' if d > 2 else 'на двойном фокусном расстоянии' if d == 2 else
                      'между фокусом и двойным фокусом')
    t = (f'Предмет, находившийся {desc(Fr(d1))} от собирающей линзы (на расстоянии {sx(d1)}F), переместили в точку на расстоянии '
         f'{sx(d2)}F от линзы (F — фокусное расстояние). Изображение на экране каждый раз действительное.')
    closer = Fr(d2) < Fr(d1)
    r = {'расстояние от линзы до изображения': UP if closer else DOWN, 'размер изображения': UP if closer else DOWN,
         'фокусное расстояние линзы': SAME}
    return t, r, {'d1': str(Fr(d1)), 'd2': str(Fr(d2))}


def _sc_mirror(rng):
    d = rng.choice(['away', 'to'])
    who = rng.choice(['Человек', 'Девочка', 'Кот', 'Ученик с книгой в руках', 'Робот-пылесос'])
    where = rng.choice([('висящего на стене', 'висящему на стене'), ('стоящего в прихожей', 'стоящему в прихожей'),
                        ('закреплённого на дверце шкафа', 'закреплённому на дверце шкафа')])
    t = (f'{who} отходит от плоского зеркала, {where[0]}.' if d == 'away' else f'{who} подходит к плоскому зеркалу, {where[1]}.')
    t = t.replace('Девочка отходит', 'Девочка отходит').replace('Робот-пылесос отходит', 'Робот-пылесос отъезжает').replace('Робот-пылесос подходит', 'Робот-пылесос подъезжает')
    r = {'размер изображения': SAME, 'расстояние от предмета до изображения': UP if d == 'away' else DOWN,
         'расстояние от зеркала до изображения': UP if d == 'away' else DOWN}
    return t, r, {'dir': d, 'sub': 'mirror'}


def _sc_decay(rng):
    k = rng.choice(['a', 'b'])
    who = rng.choice(['радия-226', 'тория-230', 'урана-238', 'полония-210']) if k == 'a' else rng.choice(
        ['стронция-90', 'цезия-137', 'йода-131', 'кобальта-60'])
    t = f'Ядро {who} испытывает {"α-распад" if k == "a" else "β⁻-распад"}. Сравните ядро-продукт с исходным ядром.'
    r = {'зарядовое число ядра': DOWN if k == 'a' else UP, 'массовое число ядра': DOWN if k == 'a' else SAME,
         'число нейтронов в ядре': DOWN, 'число протонов в ядре': DOWN if k == 'a' else UP}
    return t, r, {'kind': k}


def _sc_eye(rng):
    d = rng.choice(['near', 'far'])
    (far_g, far_a), (near_g, near_a) = rng.choice([
        (('с облаков над лесом', 'на облака над лесом'), ('с карты в руках', 'на карту в руках')),
        (('с самолёта в небе', 'на самолёт в небе'), ('с экрана телефона', 'на экран телефона')),
        (('с дальнего берега реки', 'на дальний берег реки'), ('с поплавка у самого берега', 'на поплавок у самого берега')),
        (('с заходящего Солнца', 'на заходящее Солнце'), ('с собаки у своих ног', 'на собаку у своих ног')),
        (('с доски в конце класса', 'на доску в конце класса'), ('с тетради на парте', 'на тетрадь на парте'))])
    who = rng.choice(['Человек', 'Ученик', 'Водитель', 'Рыбак'])
    t = f'{who} переводит взгляд {far_g + " " + near_a if d == "near" else near_g + " " + far_a}.'
    r = {'оптическая сила хрусталика': UP if d == 'near' else DOWN, 'фокусное расстояние хрусталика': DOWN if d == 'near' else UP,
         'расстояние от хрусталика до сетчатки': SAME}
    return t, r, {'dir': d}


def _sc_magnet(rng):
    what = rng.choice(['turns', 'current_up', 'current_down'])
    if rng.random() < 0.35:
        return _sc_core(rng)
    obj = rng.choice(['электромагнита школьного набора', 'самодельного электромагнита (провод, намотанный на гвоздь)',
                      'электромагнита подъёмного крана', 'электромагнитного замка', 'электромагнита сортировочной установки'])
    t = {'turns': f'Обмотку {obj} перемотали, сделав вдвое больше витков того же провода; с помощью реостата установили '
                  'прежнюю силу тока.',
         'current_up': f'Силу тока в обмотке {obj} увеличили с помощью реостата.',
         'current_down': f'Силу тока в обмотке {obj} уменьшили с помощью реостата.'}[what]
    up = what != 'current_down'
    r = {'магнитное действие катушки': UP if up else DOWN, 'число притянутых гвоздей': UP if up else DOWN,
         'сопротивление обмотки': UP if what == 'turns' else SAME}
    return t, r, {'what': what}


SC13 = {'net': _sc_net, 'rheo': _sc_rheo, 'spiral': _sc_spiral, 'elec': _sc_elec, 'ion': _sc_ion, 'light': _sc_light,
        'lens': _sc_lens, 'mirror': _sc_mirror, 'decay': _sc_decay, 'eye': _sc_eye, 'magnet': _sc_magnet}

HEAD12 = ['Как изменяются перечисленные ниже физические величины? Для каждой величины подберите характер её изменения.',
          'Определите, как меняются указанные физические величины в описанном процессе.',
          'Для каждой из указанных величин определите, как она изменяется.']


def _change_card(pid, rng, scen_table, keys):
    scen = rng.choice(keys)
    t, rule, p = scen_table[scen](rng)
    qs = pick(rng, list(rule), 2)
    left = [q_[0].upper() + q_[1:] for q_ in qs]
    ask = rng.choice(['Как изменяются при этом физические величины, указанные в таблице?',
                      'Как при этом изменяются перечисленные ниже величины?',
                      'Как в описанном процессе изменяются указанные физические величины?'])
    q = (f'{t} {ask} Для каждой величины определите соответствующий характер изменения. '
         'Запишите в таблицу выбранные цифры для каждой физической величины. Цифры в ответе могут повторяться.')
    a = {LET[i]: rule[x] for i, x in enumerate(qs)}
    p = dict(p, scen=scen, qs=qs)
    word = {UP: 'увеличивается', DOWN: 'уменьшается', SAME: 'не изменяется'}
    e = '; '.join(f'{x} — {word[rule[x]]}' for x in qs) + '.'
    return pcard(pid, q, a, e, k='match', o=match_opts(left, CH3), p=p)


F12 = lambda kes, scale, trap: F(MATCH_FMT + ' (2 величины, 3 варианта изменения)', 'как в демоверсии 2027 №12–13: '
                                 'описание процесса и «Для каждой величины определите соответствующий характер '
                                 'изменения»', 'Б', 5, scale, trap, kes, SC2)

for _key, _title, _kes, _scale, _trap in [
    ('throw', 'Бросок вверх/падение: скорость, энергии, ускорение', ['1.5', '1.18', '1.19'], 'мяч, камень', 'Eк ↔ Eп, E = const, a = g'),
    ('pend', 'Колебания маятника: энергии и скорость на участке', ['1.24', '1.19'], 'маятник, груз на пружине, качели', 'направление движения'),
    ('stop', 'Торможение из-за трения: кинетическая и внутренняя энергия', ['1.19', '2.6'], 'шайба, пуля, санки', 'полная энергия сохраняется'),
    ('orbit', 'Переход спутника на другую круговую орбиту', ['1.6', '1.14'], 'спутник, корабль, станция', 'скорость уменьшается с ростом радиуса'),
    ('dyn', 'Груз на динамометре входит в воду / выходит из воды', ['1.21', '1.23'], 'груз на динамометре в стакане', 'Fa зависит от погружённого объёма'),
    ('float', 'Судно переходит из реки в море и обратно', ['1.23'], 'теплоход, катер, плот', 'Fa = mg не меняется, меняется осадка'),
    ('gas', 'Газ под поршнем (изотермически) или в закрытом сосуде (нагрев)', ['1.21', '2.2', '2.6'], 'цилиндр с поршнем, баллон', 'масса и плотность газа'),
    ('heat', 'Нагревание/охлаждение твёрдого тела', ['2.1', '2.2', '2.5'], 'шарик, монета, ложка', 'плотность уменьшается при нагревании'),
    ('phase', 'Плавление, кристаллизация, кипение, конденсация', ['2.10', '2.12'], 'лёд, вода, олово, свинец', 'температура постоянна, U меняется'),
    ('incline', 'Брусок на наклонной плоскости с трением', ['1.12', '1.19'], 'брусок', 'механическая энергия убывает из-за трения'),
]:
    def _mk(key):
        def g(rng):
            return _change_card(f'ph-oge-12-{key}', rng, SC12, [key])
        g.__name__ = f'g_12_{key}'
        return g
    proto(f'ph-oge-12-{_key}', 'ОГЭ', 12, _title,
          invariant='процесс задан словами; для двух величин из перечня определить характер изменения',
          varies='сюжет и направление процесса, выбор двух величин из перечня',
          answer_rule='по закону сохранения/определению величины; solve() считает величины до и после по численной модели',
          mistakes=[_trap], solve=_solve_ch, kind='param', kes=_kes, fidelity=F12('/'.join(_kes), _scale, _trap))(_mk(_key))

for _key, _title, _kes, _scale, _trap in [
    ('net', 'Включение/выключение параллельных потребителей в сети', ['3.9', '3.10'], 'кухня, комната, мастерская', 'при параллельном подключении R уменьшается'),
    ('rheo', 'Реостат последовательно с резистором: ток и напряжения', ['3.8', '3.9'], 'цепь с реостатом', 'перераспределение напряжений'),
    ('spiral', 'Укороченная/удлинённая спираль при том же напряжении', ['3.7', '3.10'], 'плитка, паяльник', 'мощность растёт при уменьшении R'),
    ('elec', 'Электризация тел и образование ионов: электроны, протоны, масса', ['3.1', '4.2'], 'эбонит–шерсть, стекло–шёлк, атом → ион', 'переходят только электроны; заряд ядра не меняется'),
    ('light', 'Переход света из одной среды в другую', ['3.19', '3.22'], 'воздух, вода, стекло', 'частота не меняется'),
    ('lens', 'Перемещение предмета перед собирающей линзой или плоским зеркалом', ['3.21', '3.24'], 'положения относительно F и 2F, человек у зеркала', 'ближе к F — изображение дальше и больше; в зеркале размер не меняется'),
    ('decay', 'α- и β-распад: A, Z, N', ['4.1', '4.3'], 'радий, уран, стронций, цезий', 'при β⁻-распаде Z растёт, N убывает'),
    ('eye', 'Глаз: аккомодация при переводе взгляда', ['3.25'], 'дальний/ближний предмет', 'оптическая сила растёт при взгляде вблизь'),
    ('magnet', 'Электромагнит: витки и сила тока', ['3.12', '3.13'], 'катушка с сердечником', 'магнитное действие ~ nI'),
]:
    def _mk13(key):
        def g(rng):
            return _change_card(f'ph-oge-13-{key}', rng, SC13, [key])
        g.__name__ = f'g_13_{key}'
        return g
    proto(f'ph-oge-13-{_key}', 'ОГЭ', 13, _title,
          invariant='процесс задан словами; для двух величин определить характер изменения',
          varies='сюжет и направление процесса, выбор двух величин',
          answer_rule='по законам электродинамики/оптики/ядерной физики; solve() — численная модель до/после',
          mistakes=[_trap], solve=_solve_ch, kind='param', kes=_kes, fidelity=F12('/'.join(_kes), _scale, _trap))(_mk13(_key))


# =====================================================================================================================
# ЗАДАНИЕ 14. Таблица (вместо графика): выберите два верных утверждения
# =====================================================================================================================
# Утверждения собираются с истинностью «по построению» (из параметров процесса); solve() проверяет каждое
# утверждение заново по таблице значений, записанной в карточке.

HEAD14 = ['Используя данные таблицы, выберите из предложенного перечня два верных утверждения. Укажите их номера.']


def _many_card(pid, rng, text, stm, p, e):
    """stm — список (текст, истинность, код); берём 2 верных + 3 неверных, перемешиваем."""
    tr = [s for s in stm if s[1]]
    fa = [s for s in stm if not s[1]]
    if len(tr) < 2 or len(fa) < 3:
        raise Retry
    chosen = shuffled(rng, pick(rng, tr, 2) + pick(rng, fa, 3))
    if len({s[0] for s in chosen}) < 5:
        raise Retry
    o = opts([s[0] for s in chosen])
    a = sorted(str(i + 1) for i, s in enumerate(chosen) if s[1])
    p = dict(p, st=[s[2] for s in chosen])
    return pcard(pid, text, a, e, k='many', o=o, p=p)


# ---- 14a. нагревание (охлаждение) кристаллического вещества: t(τ)

def _solve_14heat(p):
    ts, tau = [Fr(x) for x in p['t']], p['tau']
    plateau = [i for i in range(len(ts) - 1) if ts[i] == ts[i + 1]]
    i0, i1 = plateau[0], plateau[-1] + 1
    tm = ts[i0]
    heating = ts[-1] > ts[0]
    s1 = abs(ts[i0] - ts[0]) / (tau[i0] - tau[0])
    s2 = abs(ts[-1] - ts[i1]) / (tau[-1] - tau[i1])
    res = []
    for code in p['st']:
        k, v = code[0], code[1] if len(code) > 1 else None
        if k == 'tm':
            ok = tm == Fr(v)
        elif k == 'dur':
            ok = tau[i1] - tau[i0] == v
        elif k == 'state':  # (state, момент)
            j = tau.index(code[2])
            st = 'first' if j < i0 else 'mix' if j < i1 else 'second' if j > i1 else 'mix_end'
            if st == 'mix_end':
                st = 'mix'
            first = 'solid' if heating else 'liquid'
            second = 'liquid' if heating else 'solid'
            real = {'first': first, 'second': second, 'mix': 'mix'}[st]
            ok = real == v
        elif k == 'cmp_c':  # «теплоёмкость жидкости больше, чем твёрдого»: при равной мощности — меньший наклон
            s_sol, s_liq = (s1, s2) if heating else (s2, s1)
            ok = (s_liq < s_sol) == (v == 'liq_more')
        elif k == 'U_const':
            ok = False
        elif k == 'U_dir':
            ok = (v == 'up') == heating
        else:
            ok = False
        res.append(ok)
    return sorted(str(i + 1) for i, ok in enumerate(res) if ok)


SUB14 = [('олово', 232), ('свинец', 327), ('нафталин', 80), ('парафин', 55), ('лёд', 0), ('цинк', 420), ('алюминий', 660)]


@proto('ph-oge-14-heating-curve', 'ОГЭ', 14, 'Нагревание/охлаждение кристаллического вещества: таблица t(τ), два верных утверждения',
       invariant='вещество равномерно нагревают (охлаждают); участок постоянной температуры — плавление (кристаллизация)',
       varies='вещество, режим (нагрев/охлаждение), длительности участков, скорости изменения температуры, утверждения',
       answer_rule='температура плавления — горизонтальный участок; при равной мощности меньший наклон ⇔ большая c; '
                   'внутренняя энергия при плавлении растёт',
       mistakes=['считают, что при плавлении внутренняя энергия не меняется', 'наклон ↔ теплоёмкость наоборот',
                 'путают момент начала и конца плавления'],
       solve=_solve_14heat, kind='param', kes=['2.8', '2.12'],
       fidelity=F('две цифры (номера верных утверждений), порядок не важен', 'как в банке: «график зависимости температуры '
                  't от времени τ…», здесь — таблица значений', 'П', 5, 'температуры и время как на графиках банка',
                  'плато = плавление; внутренняя энергия; сравнение теплоёмкостей по наклону', '2.8–2.12', SC2M))
def g_14heat(rng):
    sub_, tm = rng.choice(SUB14)
    heating = rng.random() < 0.6
    step = rng.choice([1, 2])
    a, b, c = rng.choice([2, 3, 4]), rng.choice([2, 3, 4, 5]), rng.choice([2, 3])
    s1, s2 = rng.choice([5, 10, 15, 20]), rng.choice([5, 10, 20, 30])
    if s1 == s2:
        raise Retry
    tau, ts = [], []
    t0 = tm - s1 * a if heating else tm + s1 * a
    for i in range(a + b + c + 1):
        tau.append(i * step)
        if i <= a:
            ts.append(t0 + (s1 * i if heating else -s1 * i))
        elif i <= a + b:
            ts.append(tm)
        else:
            j = i - a - b
            ts.append(tm + (s2 * j if heating else -s2 * j))
    proc = 'нагревают' if heating else 'охлаждают'
    start = 'твёрдом' if heating else 'жидком'
    q = (f'Вещество ({sub_}), находившееся в {start} состоянии, равномерно {proc} {"на плитке постоянной мощности" if heating else ", отводя от него каждую минуту одинаковое количество теплоты"}. '
         f'В таблице приведены результаты измерения его температуры t через равные промежутки времени τ.\n'
         f'τ, мин: {" | ".join(str(x) for x in tau)}\nt, °С: {" | ".join(ru(x) for x in ts)}\n{rng.choice(HEAD14)}')
    q = q.replace('охлаждают , отводя', 'охлаждают, отводя')
    dur = b * step
    i0, i1 = a, a + b
    first, second = ('твёрдом', 'жидком') if heating else ('жидком', 'твёрдом')
    liq_more = (s2 < s1) if heating else (s1 < s2)
    stm = [
        (f'Температура {"плавления" if heating else "кристаллизации"} вещества равна {ru(tm)} °С.', True, ['tm', str(tm)]),
        (f'Температура {"плавления" if heating else "кристаллизации"} вещества равна {ru(ts[-1])} °С.', ts[-1] == tm, ['tm', str(ts[-1])]),
        (f'Процесс {"плавления" if heating else "кристаллизации"} длился {dur} мин.', True, ['dur', dur]),
        (f'Процесс {"плавления" if heating else "кристаллизации"} длился {dur + step} мин.', False, ['dur', dur + step]),
        (f'В момент τ = {tau[a + b + 1]} мин вещество находилось в {second} состоянии.', True,
         ['state', 'liquid' if heating else 'solid', tau[a + b + 1]]),
        (f'В момент τ = {tau[1]} мин вещество находилось в {second} состоянии.', False,
         ['state', 'liquid' if heating else 'solid', tau[1]]),
        (f'В момент τ = {tau[a + 1]} мин часть вещества находилась в твёрдом, а часть — в жидком состоянии.', True,
         ['state', 'mix', tau[a + 1]]),
        ('Удельная теплоёмкость вещества в жидком состоянии больше, чем в твёрдом.', liq_more, ['cmp_c', 'liq_more']),
        ('Удельная теплоёмкость вещества в жидком состоянии меньше, чем в твёрдом.', not liq_more, ['cmp_c', 'liq_less']),
        (f'Во время {"плавления" if heating else "кристаллизации"} внутренняя энергия вещества не изменялась.', False, ['U_const']),
        (f'Во время {"плавления" if heating else "кристаллизации"} внутренняя энергия вещества {"увеличивалась" if heating else "уменьшалась"}.', True,
         ['U_dir', 'up' if heating else 'down']),
    ]
    p = {'t': [str(x) for x in ts], 'tau': tau}
    e = (f'Горизонтальный участок ({tau[i0]}–{tau[i1]} мин) — {"плавление" if heating else "кристаллизация"} при {ru(tm)} °С; '
         f'при этом внутренняя энергия {"растёт" if heating else "уменьшается"}. При постоянной мощности быстрее нагревается '
         '(охлаждается) состояние с меньшей удельной теплоёмкостью.')
    return _many_card('ph-oge-14-heating-curve', rng, q, stm, p, e)


# ---- 14b. движение двух тел: таблица x(t)

def _solve_14xt(p):
    t, x1, x2 = p['t'], [Fr(v) for v in p['x1']], [Fr(v) for v in p['x2']]
    v1 = (x1[-1] - x1[0]) / (t[-1] - t[0])
    v2 = (x2[-1] - x2[0]) / (t[-1] - t[0])
    res = []
    for code in p['st']:
        k = code[0]
        if k == 'v':
            ok = abs(v1 if code[1] == 1 else v2) == Fr(code[2])
        elif k == 'meet':
            j = t.index(code[1]) if code[1] in t else None
            ok = j is not None and x1[j] == x2[j]
        elif k == 'neg':
            ok = (v1 if code[1] == 1 else v2) < 0
        elif k == 'faster':
            ok = abs(v1) > abs(v2)
        elif k == 'path':
            j = t.index(code[2])
            xs = x1 if code[1] == 1 else x2
            ok = abs(xs[j] - xs[0]) == Fr(code[3])
        elif k == 'rest':
            ok = (v1 if code[1] == 1 else v2) == 0
        else:
            ok = False
        res.append(ok)
    return sorted(str(i + 1) for i, ok in enumerate(res) if ok)


@proto('ph-oge-14-motion-table', 'ОГЭ', 14, 'Равномерное движение двух тел: таблица координат, два верных утверждения',
       invariant='два тела движутся равномерно вдоль Ox; по таблице x(t) оценить скорости, направления, встречу, путь',
       varies='начальные координаты, скорости (в т. ч. отрицательные), моменты времени, кто движется, утверждения',
       answer_rule='υ = Δx/Δt; встреча — равные координаты в один момент; путь = |Δx|',
       mistakes=['скорость = x/t', 'встреча — равные скорости', 'путь = конечная координата'],
       solve=_solve_14xt, kind='param', kes=['1.2', '1.3'],
       fidelity=F('две цифры (номера верных утверждений)', 'как в банке: «графики зависимости координаты x от времени t '
                  'для … тел» (здесь — таблица)', 'П', 5, 'координаты до 100 м, время до 10 с', 'встреча ≠ равные '
                  'скорости; знак проекции', '1.2–1.3', SC2M))
def g_14xt(rng):
    who = rng.choice([('велосипедист', 'пешеход'), ('автобус', 'автомобиль'), ('лодка', 'катер'), ('тело 1', 'тело 2'),
                      ('мотоциклист', 'грузовик')])
    for _ in range(50):
        v1 = rng.choice([1, 2, 3, 4, 5, -2, -3])
        v2 = rng.choice([-5, -4, -3, -2, -1, 0, 1, 2, 6])
        x10 = rng.choice([0, 5, 10, 20])
        x20 = rng.choice([10, 20, 30, 40, 50, 60])
        if v1 == v2 or x10 == x20:
            continue
        tm = Fr(x20 - x10, v1 - v2)
        if tm.denominator == 1 and 0 < tm <= 8:
            break
    else:
        raise Retry
    tm = int(tm)
    ts = list(range(0, max(tm + 2, 5) + 1)) if rng.random() < 0.5 else list(range(0, max(tm + 2, 6) + 1, 1))
    x1 = [x10 + v1 * t for t in ts]
    x2 = [x20 + v2 * t for t in ts]
    n1, n2 = who
    q = (f'Два тела — {n1} (1) и {n2} (2) — движутся равномерно вдоль оси Ox. В таблице указаны их координаты в разные моменты времени.\n'
         f't, с: {" | ".join(str(t) for t in ts)}\nx₁, м: {" | ".join(ru(x) for x in x1)}\nx₂, м: {" | ".join(ru(x) for x in x2)}\n'
         f'{rng.choice(HEAD14)}')
    tp = rng.choice(ts[2:])
    stm = [
        (f'Модуль скорости тела 1 равен {abs(v1)} м/с.', True, ['v', 1, abs(v1)]),
        (f'Модуль скорости тела 1 равен {abs(v1) + 1} м/с.', False, ['v', 1, abs(v1) + 1]),
        (f'Модуль скорости тела 2 равен {abs(v2)} м/с.', True, ['v', 2, abs(v2)]) if v2 != 0 else
        ('Тело 2 всё время покоится.', True, ['rest', 2]),
        (f'Тела встретились в момент времени t = {tm} с.', True, ['meet', tm]),
        (f'Тела встретились в момент времени t = {tm + 1} с.', False, ['meet', tm + 1]),
        ('Тело 2 движется в направлении, противоположном направлению оси Ox.', v2 < 0, ['neg', 2]),
        ('Тело 1 движется в направлении, противоположном направлению оси Ox.', v1 < 0, ['neg', 1]),
        ('Модуль скорости тела 1 больше модуля скорости тела 2.', abs(v1) > abs(v2), ['faster']),
        (f'За первые {tp} с тело 1 прошло путь {abs(v1) * tp} м.', True, ['path', 1, tp, abs(v1) * tp]),
        (f'За первые {tp} с тело 1 прошло путь {abs(x1[ts.index(tp)])} м.', abs(x1[ts.index(tp)]) == abs(v1) * tp,
         ['path', 1, tp, abs(x1[ts.index(tp)])]),
    ]
    p = {'t': ts, 'x1': x1, 'x2': x2}
    e = f'υ₁ = {v1} м/с, υ₂ = {v2} м/с (по изменению координат за 1 с); координаты совпадают при t = {tm} с.'
    return _many_card('ph-oge-14-motion-table', rng, q, stm, p, e)


# ---- 14c. справочная таблица свойств веществ

PROPS14 = {  # вещество: (плотность кг/м³, c Дж/(кг·°С), t плавления °С, ρэл Ом·мм²/м или None)
    'алюминий': (2700, 920, 660, Fr(28, 1000)), 'медь': (8900, 400, 1085, Fr(17, 1000)), 'железо': (7800, 460, 1539, Fr(1, 10)),
    'свинец': (11350, 130, 327, Fr(21, 100)), 'олово': (7300, 230, 232, Fr(12, 100)), 'цинк': (7100, 400, 420, Fr(59, 1000)),
    'серебро': (10500, 250, 962, Fr(16, 1000)), 'никель': (8900, 460, 1455, Fr(73, 1000)),
}


def _solve_14mat(p):
    T = p['table']
    res = []
    for code in p['st']:
        k, a, b = code[0], code[1], code[2] if len(code) > 2 else None
        if k == 'mass_eqV':
            ok = T[a][0] > T[b][0]
        elif k == 'vol_eqm':
            ok = T[a][0] < T[b][0]
        elif k == 'heat_more':
            ok = T[a][1] > T[b][1]
        elif k == 'melts_in':  # a расплавится в расплаве b (при температуре плавления b)
            ok = T[a][2] < T[b][2]
        elif k == 'R_more':
            ok = Fr(T[a][3]) > Fr(T[b][3])
        elif k == 'cool_faster':  # при равной массе и отдаче теплоты быстрее остывает тело с меньшей c
            ok = T[a][1] < T[b][1]
        else:
            ok = False
        res.append(ok)
    return sorted(str(i + 1) for i, ok in enumerate(res) if ok)


@proto('ph-oge-14-materials-table', 'ОГЭ', 14, 'Справочная таблица свойств веществ: два верных утверждения',
       invariant='таблица плотности, удельной теплоёмкости, температуры плавления и удельного сопротивления; утверждения '
                 'о телах равного объёма/массы/размеров',
       varies='набор веществ (из справочных данных), сравниваемые пары и свойства',
       answer_rule='m = ρV; Q = cmΔt; тело расплавится в расплаве, если его tпл ниже; R = ρl/S',
       mistakes=['при равной массе объём больше у более плотного', 'путают теплоёмкость и температуру плавления'],
       solve=_solve_14mat, kind='dict', kes=['1.7', '2.8', '2.12', '3.7'],
       fidelity=F('две цифры (номера верных утверждений)', 'как в банке: «В справочнике физических свойств различных '
                  'материалов представлена следующая таблица»', 'П', 5, 'справочные значения КИМ',
                  'равный объём vs равная масса; tпл', '1.7, 2.8, 2.12, 3.7', SC2M))
def g_14mat(rng):
    subs = pick(rng, list(PROPS14), 5)
    T = {s: [PROPS14[s][0], PROPS14[s][1], PROPS14[s][2], str(PROPS14[s][3])] for s in subs}
    rows = '\n'.join(f'{s}: {sx(Fr(v[0], 1000))} г/см³ | {v[1]} Дж/(кг·°С) | {v[2]} °С | {sx(Fr(v[3]))} Ом·мм²/м' for s, v in T.items())
    q = ('В таблице приведены некоторые свойства веществ: плотность в твёрдом состоянии, удельная теплоёмкость, '
         'температура плавления, удельное электрическое сопротивление (при 20 °С).\n' + rows + '\n' + rng.choice(HEAD14))
    stm = []
    G2 = lambda s: GEN.get(s, s)
    for _ in range(40):
        a, b = pick(rng, subs, 2)
        kind = rng.choice(['mass_eqV', 'vol_eqm', 'heat_more', 'melts_in', 'R_more', 'cool_faster'])
        if kind == 'mass_eqV':
            t_ = f'Масса сплошного кубика из {G2(a)} больше массы кубика того же объёма из {G2(b)}.'
            ok = T[a][0] > T[b][0]
        elif kind == 'vol_eqm':
            t_ = f'При равной массе объём бруска из {G2(a)} больше объёма бруска из {G2(b)}.'
            ok = T[a][0] < T[b][0]
        elif kind == 'heat_more':
            t_ = f'Для нагревания на 10 °С детали из {G2(a)} потребуется больше теплоты, чем для детали той же массы из {G2(b)}.'
            ok = T[a][1] > T[b][1]
        elif kind == 'melts_in':
            t_ = f'Кусочек {G2(a)} расплавится, если его опустить в расплавленн{"ую" if b in ("медь",) else "ое" if b in ("олово", "серебро") else "ый"} {b}, находящ{"уюся" if b in ("медь",) else "ееся" if b in ("олово", "серебро") else "ийся"} при температуре плавления.'
            ok = T[a][2] < T[b][2]
        elif kind == 'R_more':
            t_ = f'Сопротивление проволоки из {G2(a)} больше сопротивления проволоки таких же длины и сечения из {G2(b)}.'
            ok = Fr(T[a][3]) > Fr(T[b][3])
        else:
            t_ = f'Два тела равной массы из {G2(a)} и {G2(b)} отдают одинаковое количество теплоты; тело из {G2(a)} остынет на большее число градусов.'
            ok = T[a][1] < T[b][1]
        col = {'mass_eqV': 0, 'vol_eqm': 0, 'heat_more': 1, 'melts_in': 2, 'R_more': 3, 'cool_faster': 1}[kind]
        if T[a][col] == T[b][col]:
            continue
        if t_ not in [s[0] for s in stm]:
            stm.append((t_, ok, [kind, a, b]))
    p = {'table': T}
    e = 'Сравниваем нужные столбцы таблицы: m = ρV, V = m/ρ, Q = cmΔt, R = ρl/S; тело плавится, если температура выше его tпл.'
    return _many_card('ph-oge-14-materials-table', rng, q, stm, p, e)


# ---- 14d. колебания двух маятников: таблица x(t)

def _solve_14osc(p):
    t = [Fr(v) for v in p['t']]
    X = [[Fr(v) for v in p['x1']], [Fr(v) for v in p['x2']]]
    def amp(x):
        return max(abs(v) for v in x)
    def period(x):
        # момент первого возвращения в начальное положение с тем же направлением: ищем повтор последовательности
        n = len(x)
        for k in range(1, n):
            if n - k >= 3 and all(x[i] == x[i + k] for i in range(n - k)):
                return t[k] - t[0]
        return None
    res = []
    for code in p['st']:
        k = code[0]
        if k == 'A':
            ok = amp(X[code[1] - 1]) == Fr(code[2])
        elif k == 'T':
            ok = period(X[code[1] - 1]) == Fr(code[2])
        elif k == 'nu_more':
            ok = period(X[0]) < period(X[1])
        elif k == 'len_more':
            ok = period(X[0]) > period(X[1])
        elif k == 'A_more':
            ok = amp(X[0]) > amp(X[1])
        else:
            ok = False
        res.append(ok)
    return sorted(str(i + 1) for i, ok in enumerate(res) if ok)


@proto('ph-oge-14-oscillation-table', 'ОГЭ', 14, 'Колебания двух маятников: таблица смещений, два верных утверждения',
       invariant='по значениям x(t) определить амплитуды и периоды, сравнить частоты и длины нитей (T ~ √l)',
       varies='амплитуды, периоды (кратные шагу таблицы), шаг по времени, утверждения',
       answer_rule='A — наибольшее |x|; T — время полного повтора; ν = 1/T; больший период — длиннее нить',
       mistakes=['амплитуда = размах от −A до +A', 'путают период и полупериод', 'больше частота — длиннее нить'],
       solve=_solve_14osc, kind='param', kes=['1.24', '1.25'],
       fidelity=F('две цифры (номера верных утверждений)', 'как в банке: «графики зависимости смещения x от времени t при '
                  'колебаниях двух математических маятников» (здесь — таблица)', 'П', 5, 'амплитуды в см, периоды 0,4–4 с',
                  'амплитуда vs размах; полупериод', '1.24–1.25', SC2M))
def g_14osc(rng):
    step = rng.choice([Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1])
    k1, k2 = rng.choice([(4, 8), (8, 4), (4, 4), (8, 8)])
    A1, A2 = rng.choice([2, 3, 4, 5, 6, 8]), rng.choice([2, 3, 4, 5, 6, 8])
    n = 13
    sgn = rng.choice([1, -1])
    ser = lambda k, A: [Fr(round(sgn * A * math.sin(2 * math.pi * i / k), 1)).limit_denominator(10) for i in range(n)]
    X1, X2 = ser(k1, A1), ser(k2, A2)
    ts = [step * i for i in range(n)]
    T1, T2 = step * k1, step * k2
    q = ('Два математических маятника совершают гармонические колебания. В таблице приведены смещения грузов от положения '
         'равновесия в разные моменты времени (значения округлены до десятых).\n'
         f't, с: {" | ".join(sx(v) for v in ts)}\nx₁, см: {" | ".join(ru(v) for v in X1)}\n'
         f'x₂, см: {" | ".join(ru(v) for v in X2)}\n{rng.choice(HEAD14)}')
    stm = [
        (f'Амплитуда колебаний первого маятника равна {A1} см.', True, ['A', 1, A1]),
        (f'Амплитуда колебаний первого маятника равна {2 * A1} см.', False, ['A', 1, 2 * A1]),
        (f'Амплитуда колебаний второго маятника равна {A2} см.', True, ['A', 2, A2]),
        (f'Амплитуда колебаний второго маятника равна {2 * A2} см.', False, ['A', 2, 2 * A2]),
        (f'Период колебаний первого маятника равен {sx(T1)} с.', True, ['T', 1, str(T1)]),
        (f'Период колебаний второго маятника равен {sx(T2 / 2)} с.', False, ['T', 2, str(T2 / 2)]),
        (f'Период колебаний второго маятника равен {sx(T2)} с.', True, ['T', 2, str(T2)]),
        ('Частота колебаний первого маятника больше частоты колебаний второго.', T1 < T2, ['nu_more']),
        ('Длина нити первого маятника больше длины нити второго маятника.', T1 > T2, ['len_more']),
        ('Амплитуда колебаний первого маятника больше, чем второго.', A1 > A2, ['A_more']),
    ]
    if T1 == T2:
        stm = [s_ for s_ in stm if s_[2][0] not in ('nu_more', 'len_more')]
    p = {'t': [str(v) for v in ts], 'x1': [str(v) for v in X1], 'x2': [str(v) for v in X2]}
    e = f'A₁ = {A1} см, A₂ = {A2} см; T₁ = {sx(T1)} с, T₂ = {sx(T2)} с. Чем больше период, тем длиннее нить (T ~ √l).'
    return _many_card('ph-oge-14-oscillation-table', rng, q, stm, p, e)


# ---- 14e. фрагмент Периодической системы: протоны, нейтроны, изотопы

PT14 = [('H', 'водород', 1, 1), ('He', 'гелий', 2, 4), ('Li', 'литий', 3, 7), ('Be', 'бериллий', 4, 9), ('B', 'бор', 5, 11),
        ('C', 'углерод', 6, 12), ('N', 'азот', 7, 14), ('O', 'кислород', 8, 16), ('F', 'фтор', 9, 19), ('Ne', 'неон', 10, 20),
        ('Na', 'натрий', 11, 23), ('Mg', 'магний', 12, 24), ('Al', 'алюминий', 13, 27), ('Si', 'кремний', 14, 28),
        ('P', 'фосфор', 15, 31), ('S', 'сера', 16, 32), ('Cl', 'хлор', 17, 35), ('Ar', 'аргон', 18, 40), ('K', 'калий', 19, 39),
        ('Ca', 'кальций', 20, 40)]


def _solve_14pt(p):
    T = {r[0]: r for r in p['rows']}
    res = []
    for code in p['st']:
        k = code[0]
        if k == 'n':
            s, v = code[1], code[2]
            ok = T[s][3] - T[s][2] == v
        elif k == 'p':
            ok = T[code[1]][2] == code[2]
        elif k == 'beta':  # β⁻-распад ядра a даёт ядро b (с тем же A)
            a, b = code[1], code[2]
            ok = T[b][2] == T[a][2] + 1
        elif k == 'alpha':
            a, b = code[1], code[2]
            ok = T[b][2] == T[a][2] - 2
        elif k == 'e':
            ok = T[code[1]][2] == code[2]
        else:
            ok = False
        res.append(ok)
    return sorted(str(i + 1) for i, ok in enumerate(res) if ok)


@proto('ph-oge-14-periodic-table', 'ОГЭ', 14, 'Фрагмент Периодической системы: состав ядер, распады — два верных утверждения',
       invariant='по порядковому номеру и массовому числу определить число протонов, нейтронов, электронов; '
                 'элемент-продукт α/β-распада',
       varies='фрагмент таблицы (4–5 соседних элементов), утверждения',
       answer_rule='Z — протоны и электроны; A − Z — нейтроны; α: Z − 2; β⁻: Z + 1',
       mistakes=['нейтроны = A', 'β⁻-распад уменьшает Z'],
       solve=_solve_14pt, kind='dict', kes=['4.1', '4.3', '4.5'],
       fidelity=F('две цифры (номера верных утверждений)', 'как в банке: «фрагмент Периодической системы химических '
                  'элементов Д. И. Менделеева»', 'П', 5, 'лёгкие элементы 1–20', 'N = A − Z; правило смещения',
                  '4.1–4.5', SC2M))
def g_14pt(rng):
    i = rng.randrange(0, len(PT14) - 5)
    rows = PT14[i:i + 5]
    tab = '\n'.join(f'{r[0]} ({r[1]}): порядковый номер {r[2]}, массовое число наиболее распространённого изотопа {r[3]}' for r in rows)
    q = f'Ниже приведены данные для пяти элементов из Периодической системы химических элементов Д. И. Менделеева.\n{tab}\n{rng.choice(HEAD14)}'
    stm = []
    for r in rows:
        stm.append((f'Число нейтронов в ядре атома {r[0]} (A = {r[3]}) равно {r[3] - r[2]}.', True, ['n', r[0], r[3] - r[2]]))
        stm.append((f'Число нейтронов в ядре атома {r[0]} (A = {r[3]}) равно {r[3]}.', False, ['n', r[0], r[3]]))
        stm.append((f'Число электронов в нейтральном атоме {r[0]} равно {r[3] - r[2]}.', r[3] - r[2] == r[2], ['e', r[0], r[3] - r[2]]))
    for a, b in zip(rows, rows[1:]):
        stm.append((f'В результате β⁻-распада ядра {a[0]} образуется ядро элемента {b[0]}.', True, ['beta', a[0], b[0]]))
        stm.append((f'В результате β⁻-распада ядра {b[0]} образуется ядро элемента {a[0]}.', False, ['beta', b[0], a[0]]))
    for a, b in zip(rows, rows[2:]):
        stm.append((f'В результате α-распада ядра {b[0]} образуется ядро элемента {a[0]}.', True, ['alpha', b[0], a[0]]))
    # фильтр: истинность по правилам
    p = {'rows': [list(r) for r in rows]}
    e = 'Число протонов = Z, нейтронов = A − Z; при β⁻-распаде Z увеличивается на 1, при α-распаде уменьшается на 2.'
    return _many_card('ph-oge-14-periodic-table', rng, q, stm, p, e)


# =====================================================================================================================
# ЗАДАНИЕ 15. Прямые измерения: показание прибора с погрешностью, цена деления; выбор установки для опыта
# =====================================================================================================================

INSTR15 = [  # (прибор, величина, единица, цена крупной оцифрованной отметки, число делений между ними, предел, что измеряют)
    ('мензурка', 'объём воды', 'мл', [10, 20, 50], [2, 4, 5, 10], [100, 150, 200, 250], 'В мензурку налита вода'),
    ('термометр', 'температура воздуха', '°С', [10], [2, 5, 10], [50, 100], 'Термометр висит в классе'),
    ('динамометр', 'вес груза', 'Н', [1], [2, 4, 5, 10], [4, 5], 'К динамометру подвешен груз'),
    ('амперметр', 'сила тока', 'А', [1, Fr(1, 2)], [2, 5, 10], [2, 3, 5], 'Амперметр включён в цепь'),
    ('вольтметр', 'напряжение', 'В', [1, 2, 5], [2, 5, 10], [6, 10, 15], 'Вольтметр подключён к лампе'),
    ('линейка', 'длина бруска', 'см', [1], [10, 2], [20, 30], 'Брусок приложили к линейке'),
    ('барометр-анероид', 'атмосферное давление', 'мм рт. ст.', [10], [2, 5, 10], [790, 800], 'Барометр висит в кабинете'),
]


def _solve_15read(p):
    div = Fr(p['big']) / p['n']
    val = Fr(p['mark']) + div * p['k']
    err = div / 2 if p['half'] else div
    return str(p['codes'].index([str(val), str(err)]) + 1)


@proto('ph-oge-15-reading', 'ОГЭ', 15, 'Показание прибора с учётом погрешности (половина цены деления или цена деления)',
       invariant='по описанию шкалы найти цену деления, показание и записать результат (x ± Δx)',
       varies='прибор (мензурка, термометр, динамометр, амперметр, вольтметр, линейка, барометр), шкала, положение '
              'указателя, правило погрешности',
       answer_rule='цена деления = (разность соседних оцифрованных отметок)/(число делений); показание = отметка + k·цена; '
                   'Δ — по условию (половина цены деления или цена деления)',
       mistakes=['считают число штрихов вместо промежутков', 'погрешность — половина вместо целой цены (или наоборот)',
                 'показание берут по ближайшей оцифрованной отметке'],
       solve=_solve_15read, kind='param', kes=['1.29', '2.17', '3.28'],
       fidelity=F('одна цифра (номер верного ответа из 4)', 'как в банке: «Запишите результат измерения … с учётом '
                  'абсолютной погрешности, которая равна …» (рисунок шкалы заменён описанием)', 'Б', 2,
                  'шкалы школьных приборов', 'цена деления и выбор погрешности', '1.29, 2.17, 3.28', SC1))
def g_15read(rng):
    dev, what, unit, bigs, ns, lims, ctx = rng.choice(INSTR15)
    big = Fr(rng.choice(bigs))
    n = rng.choice(ns)
    div = big / n
    if dev == 'барометр-анероид':
        mark = rng.choice([740, 750, 760, 770])
    else:
        mark = big * rng.randrange(1 if dev != 'термометр' else 0, 4)
    k = rng.randrange(1, n)
    half = rng.random() < 0.6
    val = mark + div * k
    err = div / 2 if half else div
    if exact(val, 2) is None or exact(err, 2) is None:
        raise Retry
    ptr = 'Уровень жидкости' if dev in ('мензурка', 'термометр') else 'Край бруска' if dev == 'линейка' else 'Стрелка прибора'
    parts_ = 'части' if 2 <= n <= 4 else 'частей'
    q = (f'{ctx}. Шкала прибора ({dev}) оцифрована через каждые {sx(big)} {unit}; промежуток между соседними оцифрованными '
         f'отметками разделён штрихами на {n} равных {parts_}. {ptr} находится на {k}-м штрихе после отметки '
         f'{sx(mark)} {unit}{"" if unit.endswith(".") else "."} Запишите результат измерения ({what}), учитывая, что абсолютная погрешность измерения равна '
         f'{"половине цены деления" if half else "цене деления"}.')
    cands = [(val, err), (val, div if half else div / 2), (mark + big / (n - 1) * k if n > 2 else mark + div * (k + 1), err),
             (mark, err), (val, big)]
    seen, items = set(), []
    for v_, e_ in cands:
        key = (v_, e_)
        if key in seen or exact(v_, 2) is None or exact(e_, 2) is None:
            continue
        seen.add(key)
        items.append(([str(v_), str(e_)], f'({sx(v_)} ± {sx(e_)}) {unit}'))
    if len(items) < 4:
        raise Retry
    items = [items[0]] + pick(rng, items[1:], 3)
    items = shuffled(rng, items)
    p = {'big': str(big), 'n': n, 'mark': str(mark), 'k': k, 'half': half, 'codes': [c for c, _ in items]}
    e = f'Цена деления {sx(big)}/{n} = {sx(div)} {unit}; показание {sx(mark)} + {k}·{sx(div)} = {sx(val)} {unit}; Δ = {sx(err)} {unit}'.rstrip('.') + '.'
    return pcard('ph-oge-15-reading', q, _solve_15read(p), e, k='one', o=opts([t for _, t in items]), p=p)


def _solve_15div(p):
    div = Fr(p['big']) / p['n']
    return str(p['codes'].index([str(div), str(p['lim'])]) + 1)


@proto('ph-oge-15-scale', 'ОГЭ', 15, 'Цена деления и предел измерения прибора',
       invariant='по описанию шкалы найти цену деления и верхний предел измерения',
       varies='прибор, оцифровка шкалы, число делений, предел',
       answer_rule='цена деления = разность соседних оцифрованных значений / число промежутков; предел — наибольшее значение шкалы',
       mistakes=['путают цену деления и предел', 'число штрихов вместо промежутков', 'миллиамперы ↔ амперы'],
       solve=_solve_15div, kind='param', kes=['1.29', '3.28'],
       fidelity=F('одна цифра (номер верного ответа из 4)', 'как в банке: «Чему равны соответственно цена деления и '
                  'предел измерения …?»', 'Б', 2, 'шкалы школьных приборов', 'цена деления ↔ предел', '1.29, 3.28', SC1))
def g_15div(rng):
    dev, what, unit, bigs, ns, lims, ctx = rng.choice([x for x in INSTR15 if x[0] != 'барометр-анероид'])
    big = Fr(rng.choice(bigs))
    n = rng.choice(ns)
    lim = rng.choice([L for L in lims if Fr(L) % big == 0] or [big * 5])
    div = big / n
    if exact(div, 2) is None:
        raise Retry
    q = (f'Шкала прибора ({dev}) начинается с нуля, оцифрована через каждые {sx(big)} {unit} и заканчивается отметкой '
         f'{sx(lim)} {unit}; между соседними оцифрованными отметками {n - 1} штрих{"а" if 2 <= n - 1 <= 4 else "ов" if n - 1 >= 5 else ""} '
         f'(то есть {n} промежутков). Чему равны соответственно цена деления и предел измерения прибора?')
    cands = [(div, lim), (big / (n - 1) if n > 2 else div * 2, lim), (lim, div), (div, lim - big), (big, lim)]
    seen, items = set(), []
    for d_, l_ in cands:
        if (d_, l_) in seen or exact(d_, 2) is None:
            continue
        seen.add((d_, l_))
        items.append(([str(Fr(d_)), str(Fr(l_))], f'{sx(d_)} {unit}; {sx(l_)} {unit}'))
    if len(items) < 4:
        raise Retry
    items = shuffled(rng, [items[0]] + pick(rng, items[1:], 3))
    p = {'big': str(big), 'n': n, 'lim': str(Fr(lim)), 'codes': [c for c, _ in items]}
    e = f'Цена деления {sx(big)}/{n} = {sx(div)} {unit}, предел измерения {sx(lim)} {unit}.'
    return pcard('ph-oge-15-scale', q, _solve_15div(p), e, k='one', o=opts([t for _, t in items]), p=p)


# --- выбор пары установок: изменяется только исследуемый параметр
SETUP15 = {  # параметр (им. п.): (род. п., значения)
    'pend': ('зависит ли период колебаний нитяного маятника от {x}', {'длина нити': ('длины нити', ['50 см', '100 см']),
             'масса груза': ('массы груза', ['50 г', '100 г']), 'амплитуда': ('амплитуды колебаний', ['2 см', '4 см'])}),
    'spring': ('зависит ли период колебаний пружинного маятника от {x}', {'масса груза': ('массы груза', ['100 г', '200 г']),
               'жёсткость пружины': ('жёсткости пружины', ['20 Н/м', '40 Н/м']), 'амплитуда': ('амплитуды колебаний', ['1 см', '3 см'])}),
    'resist': ('зависит ли электрическое сопротивление проводника от {x}', {'длина': ('длины проводника', ['1 м', '2 м']),
               'сечение': ('площади поперечного сечения', ['0,5 мм²', '1 мм²']), 'материал': ('материала проводника', ['медь', 'никелин'])}),
    'arch': ('зависит ли выталкивающая сила от {x}', {'объём тела': ('объёма тела', ['20 см³', '40 см³']),
             'жидкость': ('плотности жидкости', ['вода', 'масло']), 'материал тела': ('материала тела', ['алюминий', 'сталь'])}),
    'fric': ('зависит ли сила трения скольжения от {x}', {'число грузов на бруске': ('силы нормального давления (веса бруска)', ['1', '2']),
             'поверхности': ('рода трущихся поверхностей', ['дерево по дереву', 'дерево по резине']),
             'грань бруска': ('площади опоры бруска', ['большая', 'малая'])}),
    'heat': ('зависит ли время нагревания воды до кипения от {x}', {'масса воды': ('массы воды', ['200 г', '400 г']),
             'мощность нагревателя': ('мощности нагревателя', ['500 Вт', '1000 Вт']), 'сосуд': ('материала сосуда', ['сталь', 'алюминий'])}),
}


def _solve_15pair(p):
    rows, tgt = p['rows'], p['target']
    keys = list(rows[0])
    good = []
    for i in range(len(rows)):
        for j in range(i + 1, len(rows)):
            diff = [k for k in keys if rows[i][k] != rows[j][k]]
            if diff == [tgt]:
                good.append(f'{LET[i]} и {LET[j]}')
    return str(p['opts'].index(good[0]) + 1)


@proto('ph-oge-15-setup-choice', 'ОГЭ', 15, 'Выбор пары установок/опытов для проверки гипотезы (метод контроля переменных)',
       invariant='из четырёх установок выбрать пару, отличающуюся только исследуемым параметром',
       varies='исследование (маятник, пружинный маятник, сопротивление, архимедова сила, трение, нагревание), '
              'исследуемый параметр, набор установок',
       answer_rule='в выбранной паре отличается только проверяемый параметр, остальные одинаковы',
       mistakes=['выбирают пару, где меняются два параметра', 'выбирают пару, где исследуемый параметр одинаков'],
       solve=_solve_15pair, kind='param', kes=['1.29', '3.28'],
       fidelity=F('одна цифра (номер верной пары из 4)', 'как в демоверсии 2027 №15: «Какую из указанных пар … можно '
                  'использовать для этой цели?» (рисунок заменён таблицей параметров)', 'Б', 2,
                  'школьные установки из банка', 'контроль переменных', '1.29, 3.28', SC1))
def g_15pair(rng):
    key = rng.choice(list(SETUP15))
    hyp, pp_ = SETUP15[key]
    params = {k: v[1] for k, v in pp_.items()}
    names = list(params)
    tgt = rng.choice(names)
    others = [n_ for n_ in names if n_ != tgt]
    for _ in range(200):
        rows = [{n_: rng.choice(params[n_]) for n_ in names} for _ in range(4)]
        good, pairs = [], []
        for i in range(4):
            for j in range(i + 1, 4):
                diff = [n_ for n_ in names if rows[i][n_] != rows[j][n_]]
                pairs.append((i, j, diff))
                if diff == [tgt]:
                    good.append((i, j))
        if len(good) == 1 and len({tuple(r.items()) for r in rows}) == 4:
            break
    else:
        raise Retry
    gi, gj = good[0]
    bad = [(i, j) for i, j, d in pairs if (i, j) != (gi, gj) and d]
    chosen = [(gi, gj)] + pick(rng, bad, 3)
    chosen = shuffled(rng, chosen)
    o = [f'{LET[i]} и {LET[j]}' for i, j in chosen]
    tab = '\n'.join(f'{LET[i]}: ' + '; '.join(f'{n_} — {rows[i][n_]}' for n_ in names) for i in range(4))
    q = (f'Ученику нужно экспериментально проверить, {hyp.format(x=pp_[tgt][0])}. В его распоряжении четыре варианта '
         f'установки (опыта) с указанными параметрами:\n{tab}\nКакую пару установок (опытов) следует использовать для этой проверки?')
    p = {'rows': rows, 'target': tgt, 'opts': o}
    e = f'Нужна пара, в которой различается только параметр «{tgt}», а остальные одинаковы: {LET[gi]} и {LET[gj]}.'
    return pcard('ph-oge-15-setup-choice', q, _solve_15pair(p), e, k='one', o=opts(o), p=p)


