def _exp_eval(rows, res, code):
    """Проверка утверждения по таблице опытов (solve): dep/indep по паре, различающейся только фактором; max."""
    keys = [k for k in rows[0]]
    k = code[0]
    if k in ('dep', 'indep'):
        f = code[1]
        found = []
        for i in range(len(rows)):
            for j in range(i + 1, len(rows)):
                diff = [x for x in keys if rows[i][x] != rows[j][x]]
                if diff == [f]:
                    found.append(Fr(res[i]) != Fr(res[j]))
        if not found:
            return False
        return any(found) if k == 'dep' else not any(found)
    if k == 'max':
        vals = [Fr(r) for r in res]
        return vals.index(max(vals)) == code[1] and vals.count(max(vals)) == 1
    if k == 'min':
        vals = [Fr(r) for r in res]
        return vals.index(min(vals)) == code[1] and vals.count(min(vals)) == 1
    return False


def _solve_16(p):
    rows = [{k: (Fr(v) if isinstance(v, str) and '/' in v else v) for k, v in r.items()} for r in p['rows']]
    return sorted(str(i + 1) for i, c in enumerate(p['st']) if _exp_eval(rows, p['res'], c))


def _exp_card(pid, key, rng):
    X = EXP16[key]
    fac = X['factors']
    names = list(fac)
    for _ in range(300):
        n = rng.choice([3, 4])
        base = {f: rng.choice(v) for f, v in fac.items()}
        rows = [dict(base)]
        varied = pick(rng, names, min(len(names), rng.choice([2, 3])))
        for f in varied:
            r = dict(rng.choice(rows))
            r[f] = rng.choice([v for v in fac[f] if v != r[f]])
            if r not in rows:
                rows.append(r)
        while len(rows) < n:
            r = {f: rng.choice(v) for f, v in fac.items()}
            if r not in rows:
                rows.append(r)
        rows = rows[:4]
        rng.shuffle(rows)
        res = [X['law'](r) for r in rows]
        # истинность «по построению»: закон (matters) + наличие пары, различающейся только фактором
        tested = set()
        for i in range(len(rows)):
            for j in range(i + 1, len(rows)):
                diff = [f for f in names if rows[i][f] != rows[j][f]]
                if len(diff) == 1:
                    tested.add(diff[0])
        if len(tested) >= 2:
            break
    else:
        raise Retry
    stm = []
    for f in names:
        dtxt = X['dep'][f]
        if f in tested:
            stm.append((f'{X["noun"].capitalize()} зависит {dtxt}.', f in X['matters'], ['dep', f]))
            stm.append((f'{X["noun"].capitalize()} не зависит {dtxt}.', f not in X['matters'], ['indep', f]))
        else:
            stm.append((f'{X["noun"].capitalize()} {"не " if rng.random() < 0.5 else ""}зависит {dtxt}.', False, ['dep' if rng.random() < 2 else 'indep', f]))
    # «нельзя проверить» — утверждения о непроверенных факторах ложны по результатам данных опытов
    vals = [Fr(r) for r in res]
    im = vals.index(max(vals))
    if vals.count(max(vals)) == 1:
        stm.append((f'Наибольшее значение величины «{X["result"].split(",")[0]}» получено в опыте {im + 1}.', True, ['max', im]))
        other = rng.choice([i for i in range(len(rows)) if i != im])
        stm.append((f'Наибольшее значение величины «{X["result"].split(",")[0]}» получено в опыте {other + 1}.', False, ['max', other]))
    # исправляем истинность для непроверенных факторов по тексту (dep/indep в зависимости от «не»)
    fixed = []
    for t, ok, c in stm:
        if c[0] in ('dep', 'indep') and c[1] not in tested:
            c = ['indep' if ' не зависит' in t else 'dep', c[1]]
            ok = False
        fixed.append((t, ok, c))
    tab_head = ' | '.join(names + [X['result']])
    tab = '\n'.join(f'{i + 1}: ' + ' | '.join(ru(r[f]) if isinstance(r[f], (int, Fr)) else str(r[f]) for f in names) + f' | {ru(v)}'
                    for i, (r, v) in enumerate(zip(rows, res)))
    q = (f'{X["intro"]}\nОпыт: {tab_head}\n{tab}\nИз предложенного перечня выберите два утверждения, соответствующих '
         'проведённым опытам. Укажите их номера.')
    p = {'rows': [{k: (str(v) if isinstance(v, Fr) else v) for k, v in r.items()} for r in rows], 'res': [str(v) for v in res]}
    e = ('Вывод о зависимости делаем только по паре опытов, в которых различается один параметр: если результат изменился — '
         'зависит, если нет — не зависит; если такой пары нет, по этим опытам вывод сделать нельзя.')
    return _many_card(pid, rng, q, fixed, p, e)


F16 = lambda kes, scale: F('две цифры (номера верных утверждений), порядок не важен', 'как в демоверсии 2027 №16: '
                           'описание опытов учителя/ученика + «Из предложенного перечня выберите два утверждения, '
                           'соответствующих проведённым опытам»', 'П', 5, scale,
                           'вывод только по паре опытов с одним изменённым параметром', kes, SC2M)

for _key, _title, _kes, _scale in [
    ('fric', 'Опыты с силой трения скольжения: вес, поверхность, площадь', ['1.12', '1.29'], 'брусок с грузами, динамометр'),
    ('spring', 'Опыты с пружинами: удлинение, масса груза, жёсткость', ['1.13', '1.29'], 'две пружины, грузы по 100 г'),
    ('arch', 'Опыты с выталкивающей силой: объём, жидкость, материал, глубина', ['1.23', '1.29'], 'цилиндры 20–40 см³, вода и масло'),
    ('pend', 'Опыты с маятником: длина нити, масса, амплитуда', ['1.24', '1.29'], 'нитяной маятник'),
    ('resist', 'Опыты с сопротивлением проволок: материал, длина, сечение', ['3.7', '3.28'], 'никелин и нихром'),
    ('cool', 'Опыты с остыванием воды: материал сосуда, масса, крышка', ['2.7', '2.17'], 'стаканы, горячая вода'),
]:
    def _mk16(key):
        def g(rng):
            return _exp_card(f'ph-oge-16-{key}', key, rng)
        g.__name__ = f'g_16_{key}'
        return g
    proto(f'ph-oge-16-{_key}', 'ОГЭ', 16, _title,
          invariant='таблица результатов 3–4 опытов; утверждения о зависимости/независимости и о максимальном результате',
          varies='набор опытов (какие параметры меняются), числа, формулировки утверждений',
          answer_rule='зависимость подтверждается парой опытов, различающихся только одним параметром; иначе вывод нельзя сделать',
          mistakes=['делают вывод по опытам, где меняются два параметра', 'утверждение о непроверенном параметре считают верным'],
          solve=_solve_16, kind='param', kes=_kes, fidelity=F16('/'.join(_kes), _scale))(_mk16(_key))


