# ЗАДАНИЕ 17. Экспериментальное задание: расчёт величины по «измеренным» данным + рецепт оформления
# =====================================================================================================================

F17 = lambda kes, scale, trap: F('в КИМ — развёрнутый ответ (рисунок/схема, формула, результаты с погрешностью, '
                                 'числовое значение или вывод); в тренажёре проверяется итоговое число', 'как в банке №17: '
                                 '«Используя …, соберите экспериментальную установку для …» + обработка результатов',
                                 'В', 30, scale, trap, kes, '3 балла по критериям (в тренажёре — только расчётная часть)')


def _solve_17rho(p):
    return exact(V(p, 'm') / (V(p, 'V2') - V(p, 'V1')) * 1000)


@proto('ph-oge-17-density', 'ОГЭ', 17, 'Лабораторная: плотность цилиндра (весы + мензурка)',
       invariant='масса — на весах, объём — по разности уровней воды в мензурке; ρ = m/(V₂ − V₁)',
       varies='цилиндр (материал из набора ФИПИ-лаборатории), масса, уровни воды',
       answer_rule='ρ = m/(V₂ − V₁), перевод г/см³ → кг/м³',
       mistakes=['делят на V₂, а не на разность', 'г/см³ ↔ кг/м³', 'мл ≠ см³'],
       solve=_solve_17rho, kes=['1.7', '1.29'],
       fidelity=F17('1.7, 1.29', 'цилиндры 20–40 см³, мензурка 100–250 мл, как в наборах ОГЭ', 'объём по разности уровней'))
def g_17rho(rng):
    mat = rng.choice(['алюминий', 'латунь', 'сталь', 'медь', 'цинк', 'олово'])
    V = rng.choice([10, 12, 15, 16, 20, 24, 25, 30, 40])
    V1 = rng.choice([40, 50, 60, 70, 80, 100])
    m = Fr(RHO[mat] * V, 1000)
    if exact(m, 1) is None:
        raise Retry
    num_ = rng.choice([1, 2, 3, 4])
    q = (f'Для определения плотности вещества цилиндра № {num_} ученик измерил его массу на электронных весах: {sx(m)} г. '
         f'Затем он налил в мензурку воду до уровня {V1} мл и полностью погрузил в неё цилиндр — уровень воды поднялся до '
         f'{V1 + V} мл. Вычислите по этим данным плотность вещества цилиндра.')
    x = Fr(RHO[mat])
    e = f'V = {V1 + V} − {V1} = {V} см³; ρ = m/V = {sx(m)}/{V} = {sx(x / 1000)} г/см³ = {RHO[mat]} кг/м³.'
    return ncard('ph-oge-17-density', q, x, 'кг/м³', e, P(m=m, V1=V1, V2=V1 + V),
                 [x / 1000, m / (V1 + V) * 1000, m / V])


def _solve_17arch(p):
    if p['find'] == 'F':
        return exact(V(p, 'P0') - V(p, 'P1'))
    return exact((V(p, 'P0') - V(p, 'P1')) / (1000 * G) * 1000000)


@proto('ph-oge-17-buoyancy', 'ОГЭ', 17, 'Лабораторная: выталкивающая сила с помощью динамометра',
       invariant='вес в воздухе P₀ и в воде P₁ (показания динамометра); Fa = P₀ − P₁; объём V = Fa/(ρв g)',
       varies='цилиндр (объём/материал), показания динамометра, что найти',
       answer_rule='Fa = P₀ − P₁; V = Fa/(ρв g)',
       mistakes=['берут показание в воде за выталкивающую силу', 'V в м³ ↔ см³'],
       solve=_solve_17arch, kes=['1.23', '1.29'],
       fidelity=F17('1.23, 1.29', 'динамометр до 5 Н, цилиндры 20–40 см³', 'разность показаний'))
def g_17arch(rng):
    mat = rng.choice(['алюминий', 'сталь', 'латунь', 'медь', 'цинк', 'олово', 'мрамор'])
    Vc = rng.choice([10, 15, 20, 25, 30, 40, 50, 60, 80])
    P0 = Fr(RHO[mat] * G * Vc, 1000000)
    Fa = Fr(1000 * G * Vc, 1000000)
    P1 = P0 - Fa
    if exact(P0, 2) is None or exact(P1, 2) is None:
        raise Retry
    find = rng.choice(['F', 'V'])
    body = rng.choice(['цилиндр № 2', 'цилиндр № 3', 'металлический брусок', 'груз из набора'])
    q = rng.choice([f'Ученик подвесил {body} к динамометру: в воздухе динамометр показал {sx(P0)} Н. После полного погружения '
                    f'тела в стакан с водой показание стало {sx(P1)} Н. ',
                    f'При выполнении лабораторной работы получены данные: вес тела ({body}) в воздухе {sx(P0)} Н, показание '
                    f'динамометра при полном погружении тела в воду {sx(P1)} Н. ',
                    f'Динамометр с подвешенным телом ({body}) показывает {sx(P0)} Н; когда тело целиком опускают в воду, '
                    f'не касаясь дна, — {sx(P1)} Н. '])
    if find == 'F':
        q += 'Определите выталкивающую силу, действующую на тело.'
        x, unit, wrong = Fa, 'Н', [P1, P0 + P1, P0]
        e = f'Fa = P₀ − P₁ = {sx(P0)} − {sx(P1)} = {exact(Fa)} Н.'
    else:
        q += 'Определите объём цилиндра. Плотность воды 1000 кг/м³.'
        x, unit, wrong = Fr(Vc), 'см³', [Fa, P1 / G * 100000, Fr(Vc, 1000000)]
        e = f'Fa = {sx(Fa)} Н; V = Fa/(ρg) = {sx(Fa)}/10000 = {sx(Fr(Vc, 1000000))} м³ = {Vc} см³.'
    return ncard('ph-oge-17-buoyancy', q, x, unit, e, P(find=find, P0=P0, P1=P1), wrong)


def _solve_17fr(p):
    return exact(V(p, 'F') / V(p, 'P'))


@proto('ph-oge-17-friction', 'ОГЭ', 17, 'Лабораторная: коэффициент трения скольжения (брусок с грузами, динамометр)',
       invariant='вес бруска с грузами P измеряют динамометром; при равномерном движении Fтр = Fтяги; μ = Fтр/P',
       varies='число грузов, поверхность (рейка), показания динамометра',
       answer_rule='μ = F/P (горизонтальная поверхность, N = P)',
       mistakes=['μ = P/F', 'берут массу вместо веса'],
       solve=_solve_17fr, kes=['1.12', '1.29'],
       fidelity=F17('1.12, 1.29', 'брусок ~1 Н, грузы по 1 Н, динамометр до 1–5 Н', 'равномерное движение'))
def g_17fr(rng):
    n = rng.choice([1, 2, 3])
    Pb = rng.choice([Fr(1, 2), Fr(3, 5), Fr(7, 10), Fr(4, 5), 1, Fr(6, 5)])
    P_ = Pb + n
    mu = rng.choice([Fr(1, 10), Fr(3, 20), Fr(1, 5), Fr(1, 4), Fr(3, 10), Fr(7, 20), Fr(2, 5), Fr(1, 2)])
    surf = rng.choice(['по горизонтальной направляющей рейке', 'по деревянной доске, лежащей на столе', 'по листу пластика на столе'])
    Fv = mu * P_
    if exact(Fv, 2) is None:
        raise Retry
    q = (f'Ученик положил на брусок {n} груз{"а" if n > 1 else ""} и измерил динамометром вес бруска с грузами: {sx(P_)} Н. '
         f'Затем он равномерно тянул брусок с грузами {surf}, и динамометр показывал '
         f'{sx(Fv)} Н. Определите коэффициент трения скольжения.')
    e = f'μ = Fтр/N = {sx(Fv)}/{sx(P_)} = {exact(mu)}.'
    return ncard('ph-oge-17-friction', q, mu, '', e, P(F=Fv, P=P_), [P_ / Fv, Fv / Pb, Fv])


def _solve_17k(p):
    return exact(V(p, 'F') / V(p, 'x') * 100)


@proto('ph-oge-17-spring', 'ОГЭ', 17, 'Лабораторная: жёсткость пружины',
       invariant='сила упругости равна весу подвешенных грузов; удлинение измеряют линейкой; k = F/x',
       varies='число грузов (по 1 Н), пружина, удлинение (см/мм)',
       answer_rule='k = F/x (x в метрах)',
       mistakes=['не переводят см в м', 'берут длину пружины вместо удлинения'],
       solve=_solve_17k, kes=['1.13', '1.29'],
       fidelity=F17('1.13, 1.29', 'грузы по 1 Н, удлинения 2–10 см', 'удлинение = разность длин'))
def g_17k(rng):
    n = rng.choice([1, 2, 3, 4])
    k = rng.choice([20, 25, 40, 50, 80, 100, 125, 200])
    x = Fr(n * 100, k)
    L0 = rng.choice([4, 5, 6, 7, 8, 10, 12])
    if exact(x, 1) is None:
        raise Retry
    q = (f'Длина нерастянутой пружины {L0} см. Когда к ней подвесили {n} груз{"а" if n > 1 else ""} массой по 100 г, длина '
         f'пружины стала {sx(L0 + x)} см. Определите жёсткость пружины.')
    e = f'F = mg = {n} Н, x = {sx(L0 + x)} − {L0} = {sx(x)} см = {sx(x / 100)} м, k = F/x = {k} Н/м.'
    return ncard('ph-oge-17-spring', q, Fr(k), 'Н/м', e, P(F=n, x=x), [Fr(n) / x, Fr(n * 100) / (L0 + x), Fr(n) / (x / 100) / 10])


def _solve_17el(p):
    f = p['find']
    if f == 'R':
        return exact(V(p, 'U') / V(p, 'I'))
    if f == 'P':
        return exact(V(p, 'U') * V(p, 'I'))
    return exact(V(p, 'U') * V(p, 'I') * V(p, 't'))


@proto('ph-oge-17-electric', 'ОГЭ', 17, 'Лабораторная: сопротивление резистора, мощность и работа тока (амперметр, вольтметр)',
       invariant='по показаниям амперметра и вольтметра: R = U/I; P = UI; A = UIt',
       varies='резистор/лампа, показания приборов, время',
       answer_rule='подстановка в формулу',
       mistakes=['R = I/U', 'время в минутах'],
       solve=_solve_17el, kes=['3.8', '3.10', '3.28'],
       fidelity=F17('3.8, 3.10, 3.28', 'источник 4,5 В, токи 0,2–0,6 А — как в демо №17', 'перевод времени'))
def g_17el(rng):
    find = rng.choice(['R', 'P', 'A'])
    el = rng.choice(['резистор R₁', 'резистор R₂', 'лампочку', 'резистор R₃'])
    I = rng.choice([Fr(1, 5), Fr(1, 4), Fr(3, 10), Fr(2, 5), Fr(1, 2), Fr(3, 5)])
    R = rng.choice([4, 5, 6, 8, 10, 12])
    U = I * R
    if exact(U, 1) is None or U > Fr(9, 2):
        raise Retry
    q = (f'Ученик собрал цепь из источника тока, ключа, реостата, амперметра и включил в неё {el}; вольтметр подключил '
         f'параллельно этому элементу. Амперметр показал {sx(I)} А, вольтметр — {sx(U)} В. ')
    if find == 'R':
        q += 'Определите сопротивление элемента.'
        x, unit, wrong = Fr(R), 'Ом', [I / U, U * I, U]
        e = f'R = U/I = {sx(U)}/{sx(I)} = {R} Ом.'
        p = P(find='R', U=U, I=I)
    elif find == 'P':
        q += 'Определите мощность электрического тока в элементе.'
        x, unit, wrong = U * I, 'Вт', [U / I, I / U, U * I * 2]
        e = f'P = UI = {sx(U)}·{sx(I)} = {exact(U * I) or ""} Вт.'
        p = P(find='P', U=U, I=I)
    else:
        t = rng.choice([60, 120, 180, 300])
        q += f'Определите работу тока в этом элементе за {t // 60} мин.'
        x, unit, wrong = U * I * t, 'Дж', [U * I * t // 60, U * I, U * I * t * 60]
        e = f'A = UIt = {sx(U)}·{sx(I)}·{t} = {exact(x) or ""} Дж.'
        p = P(find='A', U=U, I=I, t=t)
    return ncard('ph-oge-17-electric', q, x, unit, e, p, wrong)


def _solve_17lens(p):
    return exact(100 / V(p, 'F'))


@proto('ph-oge-17-lens', 'ОГЭ', 17, 'Лабораторная: оптическая сила собирающей линзы (изображение удалённого источника)',
       invariant='изображение удалённого окна/лампы на экране получается в фокальной плоскости: F = расстояние линза–экран, D = 1/F',
       varies='линза (№ 1, № 2), расстояние (см/мм)',
       answer_rule='D = 1/F, F в метрах',
       mistakes=['D = F', 'не переводят см в м'],
       solve=_solve_17lens, kes=['3.24', '3.28'],
       fidelity=F17('3.24, 3.28', 'линзы F = 5–20 см из набора', 'перевод в метры'))
def g_17lens(rng):
    F_ = rng.choice([4, 5, 8, 10, Fr(25, 2), 16, 20, 25, 40, 50, Fr(15, 2), 12])
    src = rng.choice(['удалённого окна', 'лампы, висящей в другом конце кабинета', 'дерева за окном', 'уличного фонаря',
                      'дома напротив школы'])
    lens = rng.choice(['собирающей линзы № 1', 'собирающей линзы № 2', 'лупы', 'линзы из набора по оптике'])
    dist = f'{sx(F_)} см' if rng.random() < 0.6 else f'{sx(F_ * 10)} мм'
    q = (f'Ученик получил на экране чёткое уменьшенное изображение {src}, используя {lens.replace("собирающей линзы", "собирающую линзу").replace("лупы", "лупу").replace("линзы из набора", "линзу из набора")}. Расстояние от линзы '
         f'до экрана оказалось равным {dist}. Считая источник бесконечно удалённым, определите оптическую силу линзы.')
    x = Fr(100) / F_
    e = f'F ≈ {sx(F_)} см = {sx(Fr(F_) / 100)} м; D = 1/F = {exact(x) or ""} дптр.'
    return ncard('ph-oge-17-lens', q, x, 'дптр', e, P(F=F_), [Fr(F_), Fr(1) / F_, Fr(F_) / 100])


def _solve_17lev(p):
    return exact(V(p, 'F1') * V(p, 'l1') / V(p, 'l2'))


@proto('ph-oge-17-lever', 'ОГЭ', 17, 'Лабораторная: условие равновесия рычага (моменты сил)',
       invariant='грузы по 1 Н на одном плече, динамометр — на другом; F₂ = F₁l₁/l₂; проверка равенства моментов',
       varies='число грузов, плечи (см), с какой стороны динамометр',
       answer_rule='F₂ = F₁l₁/l₂',
       mistakes=['прямая пропорция', 'плечо = расстояние между грузом и динамометром'],
       solve=_solve_17lev, kes=['1.20', '1.29'],
       fidelity=F17('1.20, 1.29', 'рычаг с делениями по 5 см, грузы по 1 Н', 'обратная пропорция'))
def g_17lev(rng):
    n = rng.choice([1, 2, 3, 4])
    l1 = rng.choice([4, 5, 6, 8, 10, 12, 15, 16, 20, 24, 25, 30])
    l2 = rng.choice([4, 5, 6, 8, 10, 12, 15, 16, 20, 24, 25, 30])
    F2 = Fr(n * l1, l2)
    if l1 == l2 or exact(F2, 2) is None or F2 > 5:
        raise Retry
    q = (f'На рычаге, уравновешенном на оси, слева на расстоянии {l1} см от оси подвесили {n} груз{"а" if n > 1 else ""} '
         f'по 1 Н. Справа на расстоянии {l2} см от оси прикрепили динамометр и потянули вертикально вниз так, что рычаг '
         'вновь уравновесился. Какое показание динамометра?')
    e = f'F₁l₁ = F₂l₂: F₂ = {n}·{l1}/{l2} = {exact(F2)} Н.'
    return ncard('ph-oge-17-lever', q, F2, 'Н', e, P(F1=n, l1=l1, l2=l2), [Fr(n * l2, l1), Fr(n), Fr(n * l1 * l2, 100)])


