# =====================================================================================================================
# ЗАДАНИЕ 18. Работа с текстом: качественный вопрос по тексту (генератор по демо-сюжету + рецепт)
# =====================================================================================================================

BOIL = {100: 100, 120: 105, 150: 111, 200: 120, 250: 127, 300: 134, 400: 144}  # кПа → °С (справочные, округлены)


def _solve_18(p):
    pr = 100 + 10 * p['h']
    tb = BOIL[pr]
    return str(p['codes'].index('yes' if p['T'] > tb else 'no') + 1)


@proto('ph-oge-18-boiling-pressure', 'ОГЭ', 18, 'Текст о кипении при разном давлении (гейзер, скороварка): закипит ли вода',
       invariant='давление на глубине p = p₀ + ρgh; температура кипения растёт с давлением (таблица); вода закипает, '
                 'если её температура выше температуры кипения при данном давлении',
       varies='сюжет (гейзер, скороварка, глубокий колодец с горячей водой), высота столба, температура воды',
       answer_rule='найти p, по таблице tкип(p), сравнить с температурой воды',
       mistakes=['не прибавляют атмосферное давление', 'считают, что вода всегда кипит при 100 °С'],
       solve=_solve_18, kind='param', kes=['2.10', '1.21'],
       fidelity=F('в КИМ — развёрнутый ответ (ответ + объяснение, 2 балла); в тренажёре — выбор ответа с верным '
                  'объяснением', 'как в демоверсии 2027 №18 (текст «Гейзеры», зависимость tкип от давления)', 'П', 15,
                  'давления 100–400 кПа, как на рисунке демоверсии', 'атмосферное давление + давление столба',
                  '2.10, 1.21', '2 балла (ответ и обоснование)'))
def g_18(rng):
    h = rng.choice([2, 5, 10, 15, 20, 30])
    pr = 100 + 10 * h
    tb = BOIL[pr]
    T = tb + rng.choice([-6, -4, -3, -2, 2, 3, 4, 6])
    ctx = rng.choice([
        'В глубокой трубке гейзера находится горячая вода. Порция пара вытолкнула часть воды, и над паром остался столб воды',
        'В вертикальной трубе геотермальной скважины находится горячая вода. Над рассматриваемым слоем находится столб воды',
        'В опыте на дне высокого вертикального сосуда нагревают воду. Над нагреваемым слоем находится столб воды'])
    tab = '; '.join(f'{p_} кПа — {t_} °С' for p_, t_ in BOIL.items())
    q = (f'Температура кипения воды зависит от внешнего давления: {tab}.\n{ctx} высотой {h} м. Температура воды в '
         f'рассматриваемом слое {T} °С. Атмосферное давление 100 кПа, плотность воды 1000 кг/м³. Закипит ли вода в этом слое?')
    items = [('yes', f'Закипит: давление в слое равно {pr} кПа, при нём вода кипит при {tb} °С, а температура воды выше.'),
             ('no', f'Не закипит: давление в слое равно {pr} кПа, при нём вода кипит при {tb} °С, а температура воды ниже.'),
             ('x100', 'Закипит: вода кипит при 100 °С, а температура воды выше 100 °С.'),
             ('xnoatm', f'Не закипит: давление столба воды {pr - 100} кПа, при нём вода кипит при температуре выше, чем температура воды.')]
    items = shuffled(rng, items)
    p = {'h': h, 'T': T, 'codes': [c for c, _ in items]}
    e = f'p = p₀ + ρgh = 100 + {10 * h} = {pr} кПа; tкип = {tb} °С; вода {"закипит" if T > tb else "не закипит"} ({T} °С).'
    return pcard('ph-oge-18-boiling-pressure', q, _solve_18(p), e, k='one', o=opts([t for _, t in items]), p=p)


