def _solve_19ep(p):
    mats = p['mats']
    if p['ask'] == 'max':
        best = max(mats, key=lambda m: RHO[m])
    else:
        best = min(mats, key=lambda m: RHO[m])
    want = {f'v:{best}', 'r:rho'}
    return sorted(str(i + 1) for i, c in enumerate(p['codes']) if c in want)


@proto('ph-oge-19-energy-density', 'ОГЭ', 19, 'Качественная: у какого из шаров одинакового размера больше (меньше) потенциальная энергия',
       invariant='шары одинакового объёма на одной высоте; Eп = mgh, m = ρV — сравнение по плотности вещества',
       varies='материалы шаров (из таблицы плотностей), наибольшая/наименьшая энергия',
       answer_rule='ответ — шар из самого плотного (наименее плотного) вещества; объяснение: при равном объёме масса '
                   'пропорциональна плотности, а Eп — массе',
       mistakes=['«у всех одинаковая — высота одна»', 'сравнивают по размеру, а не по массе'],
       solve=_solve_19ep, kind='param', kes=['1.18', '1.7'],
       fidelity=F('в КИМ — развёрнутый ответ (ответ + объяснение, 2 балла); в тренажёре — выбрать два утверждения: '
                  'верный ответ и верное объяснение', 'как в демоверсии 2027 №19 (свинцовый, медный и деревянный шары)', 'П', 12,
                  'плотности из справочных таблиц КИМ', 'равный объём ≠ равная масса', '1.18, 1.7',
                  '2 балла: верный ответ и достаточное объяснение'))
def g_19ep(rng):
    mats = pick(rng, ['свинец', 'медь', 'сталь', 'алюминий', 'древесина (дуб)', 'древесина (сосна)', 'мрамор', 'парафин', 'стекло оконное'], 3)
    if len({RHO[m] for m in mats}) < 3:
        raise Retry
    ask = rng.choice(['max', 'min'])
    adj = {'свинец': 'свинцовый', 'медь': 'медный', 'сталь': 'стальной', 'алюминий': 'алюминиевый', 'древесина (дуб)': 'дубовый',
           'древесина (сосна)': 'сосновый', 'мрамор': 'мраморный', 'парафин': 'парафиновый', 'стекло оконное': 'стеклянный'}
    q = (f'Три сплошных шара одинакового объёма — {", ".join(adj[m] for m in mats)} — лежат на полке на одной и той же '
         f'высоте над полом. Какой из шаров обладает {"наибольшей" if ask == "max" else "наименьшей"} потенциальной энергией '
         'относительно пола? Выберите два утверждения, которые вместе составляют верный ответ с обоснованием.')
    best = max(mats, key=lambda m: RHO[m]) if ask == 'max' else min(mats, key=lambda m: RHO[m])
    other = rng.choice([m for m in mats if m != best])
    items = [(f'v:{best}', f'Ответ: {adj[best]} шар.'), (f'v:{other}', f'Ответ: {adj[other]} шар.'),
             ('v:eq', 'Ответ: потенциальные энергии всех шаров одинаковы.'),
             ('r:rho', f'Объёмы шаров равны, поэтому масса больше у шара из более плотного вещества; потенциальная энергия mgh '
                       'при одинаковой высоте пропорциональна массе.'),
             ('r:h', 'Потенциальная энергия определяется только высотой тела над нулевым уровнем.'),
             ('r:size', 'Потенциальная энергия пропорциональна объёму тела, а объёмы шаров одинаковы.')]
    items = [items[0], items[3]] + pick(rng, [items[1], items[2], items[4], items[5]], 3)
    items = shuffled(rng, items)
    p = {'mats': mats, 'ask': ask, 'codes': [c for c, _ in items]}
    e = f'Eп = mgh = ρVgh; при равных V и h больше (меньше) энергия у шара с большей (меньшей) плотностью: {adj[best]}.'
    return pcard('ph-oge-19-energy-density', q, _solve_19ep(p), e, k='many', o=opts([t for _, t in items]), p=p)


