# =====================================================================================================================
# ЗАДАНИЯ 20–22. Расчётные задачи (в КИМ — полное решение; в тренажёре — итоговое число)
# =====================================================================================================================

def rnd(x, dec):
    """Ответ: точный, если конечная дробь ≤ 2 знаков, иначе округление до dec знаков (указывается в условии)."""
    a = exact(x, 2)
    return a if a is not None else fmt(Fr(x), dec)


def ncard2(pid, q, x, unit, e, p, wrong, dec=1):
    a = exact(x, 2)
    if a is None:
        q += f' Ответ округлите до {"целых" if dec == 0 else "десятых" if dec == 1 else "сотых"}.'
        a = fmt(Fr(x), dec)
    p = dict(p, dec=dec)
    q = q + (f'\nОтвет: ___ {unit}' + ('' if unit.endswith('.') else '.') if unit else '\nОтвет: ___.')
    if Fr(x) <= 0 or len(a.replace(',', '')) > 8:
        raise Retry
    ws = []
    for w in wrong:
        try:
            w = Fr(w)
        except (TypeError, ValueError, ZeroDivisionError):
            continue
        if w > 0:
            ws.append(rnd(w, dec))
    return pcard(pid, q, a, e, k='num', p=p, wrong=ws)


F20 = lambda n, kes, scale, trap: F('в КИМ — полное решение (Дано, формулы, вычисления, ответ); в тренажёре — число '
                                    '(при необходимости округление указано в условии)', 'как в банке и демоверсии 2027 '
                                    f'№{n}: развёрнутая расчётная задача', 'П' if n == 20 else 'В', 15 if n == 20 else 20,
                                    scale, trap, kes, SC3)


# ---------------------------------------------------------------- 20

def _solve_20c(p):
    R1, R2, R3, I = V(p, 'R1'), V(p, 'R2'), V(p, 'R3'), V(p, 'I')
    R23 = R2 * R3 / (R2 + R3)
    f = p['find']
    if f == 'U1':
        v = I * R1
    elif f == 'U':
        v = I * (R1 + R23)
    elif f == 'I2':
        v = I * R23 / R2
    else:
        v = I * I * (R1 + R23)
    return rnd(v, p['dec'])


@proto('ph-oge-20-circuit-mixed', 'ОГЭ', 20, 'Смешанное соединение резисторов: напряжения, токи, мощность',
       invariant='R₁ последовательно с параллельными R₂ и R₃; амперметр в неразветвлённой части',
       varies='сопротивления, показание амперметра, что найти (U₁, U общ, I₂, мощность)',
       answer_rule='R₂₃ = R₂R₃/(R₂+R₃); U₁ = IR₁; U = I(R₁+R₂₃); I₂ = IR₂₃/R₂; P = I²R',
       mistakes=['складывают все сопротивления', 'ток ветви = общему току'],
       solve=_solve_20c, kes=['3.8', '3.9', '3.10'],
       fidelity=F20(20, '3.8–3.10', 'как в демоверсии 2027 №20 (R₁ = 10 Ом, R₂ = R₃ = 5 Ом, 2 А)', 'эквивалентное '
                    'сопротивление параллельного участка'))
def g_20c(rng):
    R1 = rng.choice([2, 4, 5, 6, 8, 10, 12, 15, 20])
    R2, R3 = rng.choice([(5, 5), (10, 10), (6, 3), (12, 6), (20, 5), (4, 12), (30, 15), (8, 8), (6, 6)])
    I = rng.choice([Fr(1, 2), 1, Fr(3, 2), 2, 3, 4])
    find = rng.choice(['U1', 'U', 'I2', 'P'])
    R23 = Fr(R2 * R3, R2 + R3)
    desc = (f'Резистор R₁ = {R1} Ом включён последовательно с участком из двух параллельно соединённых резисторов '
            f'R₂ = {R2} Ом и R₃ = {R3} Ом. Амперметр, включённый в неразветвлённую часть цепи, показывает {sx(I)} А.')
    ask = {'U1': ('Каково напряжение на резисторе R₁?', 'В', I * R1),
           'U': ('Каково напряжение на всём участке цепи?', 'В', I * (R1 + R23)),
           'I2': ('Какова сила тока через резистор R₂?', 'А', I * R23 / R2),
           'P': ('Какая мощность выделяется на всём участке цепи?', 'Вт', I * I * (R1 + R23))}[find]
    q = f'{desc} {ask[0]}'
    x = ask[2]
    e = f'R₂₃ = {R2}·{R3}/({R2}+{R3}) = {sx(R23)} Ом; ответ: {rnd(x, 1)} {ask[1]}.'
    wrong = [I * (R1 + R2 + R3), I * R2, I * R1 * 2, x * 2]
    return ncard2('ph-oge-20-circuit-mixed', q, x, ask[1], e, P(find=find, R1=R1, R2=R2, R3=R3, I=I), wrong)


def _solve_20wire(p):
    R = RHO_EL[p['mat']] * V(p, 'l') / V(p, 'S')
    U = V(p, 'U')
    v = U * U / R if p['find'] == 'P' else U / R
    return rnd(v, p['dec'])


@proto('ph-oge-20-wire-heater', 'ОГЭ', 20, 'Нагреватель из проволоки: сопротивление по ρl/S, ток и мощность',
       invariant='R = ρl/S (ρ — таблица КИМ, Ом·мм²/м), затем I = U/R или P = U²/R',
       varies='материал (нихром, никелин, константан, фехраль → нихром), длина, сечение, напряжение, что найти',
       answer_rule='R = ρl/S; I = U/R; P = U²/R',
       mistakes=['R = ρS/l', 'P = U/R'],
       solve=_solve_20wire, kes=['3.7', '3.8', '3.10'],
       fidelity=F20(20, '3.7–3.10', 'проволока 1–20 м, 0,1–1 мм², 12–220 В, как в банке', 'два шага: R, затем I или P'))
def g_20wire(rng):
    mat = rng.choice(['нихром', 'никелин', 'константан'])
    l = rng.choice([2, 4, 5, 8, 10, 11, 20])
    S = rng.choice([Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1])
    U = rng.choice([12, 24, 36, 110, 127, 220])
    R = RHO_EL[mat] * l / S
    find = rng.choice(['I', 'P'])
    x = U / R if find == 'I' else U * U / R
    if x > 5000 or x < Fr(1, 10):
        raise Retry
    mg = {'нихром': 'нихромовой', 'никелин': 'никелиновой', 'константан': 'константановой'}[mat]
    dev = rng.choice(['самодельного паяльника', 'электроплитки для турпохода', 'сушилки для обуви', 'инкубатора', 'подогревателя аквариума'])
    q = (f'Для {dev} намотали спираль: {l} м {mg} проволоки сечением {sx(S)} мм². Прибор рассчитан на подключение к '
         f'источнику {U} В. Определите {"силу тока в спирали" if find == "I" else "мощность, выделяемую в спирали"}.')
    e = f'R = ρl/S = {sx(RHO_EL[mat])}·{l}/{sx(S)} = {sx(R)} Ом; {"I = U/R" if find == "I" else "P = U²/R"} = {rnd(x, 1)}.'
    wrong = [U * R if find == 'I' else U / R, x * 2, x / 2]
    return ncard2('ph-oge-20-wire-heater', q, x, 'А' if find == 'I' else 'Вт', e, P(find=find, mat=mat, l=l, S=S, U=U), wrong)


def _solve_20mix(p):
    m1, t1, m2, t2, k = V(p, 'm1'), V(p, 't1'), V(p, 'm2'), V(p, 't2'), V(p, 'k')
    if p['find'] == 'T':
        v = (k * m1 * t1 + m2 * t2) / (k * m1 + m2)
    else:  # масса холодной воды при известной конечной температуре T
        T = V(p, 'T')
        v = k * m1 * (t1 - T) / (T - t2)
    return rnd(v, p['dec'])


@proto('ph-oge-20-heat-mixing', 'ОГЭ', 20, 'Смешивание горячей и холодной воды (уравнение теплового баланса, возможны потери)',
       invariant='cm₁(t₁ − θ)·k = cm₂(θ − t₂), k — доля теплоты горячей воды, пошедшая на нагрев холодной',
       varies='массы, температуры, потери (0 или 10–20 %), что найти (θ или масса)',
       answer_rule='из уравнения теплового баланса',
       mistakes=['среднее арифметическое температур', 'потери вычитают не из той части'],
       solve=_solve_20mix, kes=['2.8', '2.9'],
       fidelity=F20(20, '2.8–2.9', 'как в банке: «Смешали 3 кг воды при 80 °С и 1,6 кг воды при 10 °С… 20 % тепла…»',
                    'учёт потерь'))
def g_20mix(rng):
    m1 = rng.choice([Fr(1, 5), Fr(2, 5), Fr(1, 2), 1, 2, 3, 4])
    m2 = rng.choice([Fr(1, 5), Fr(3, 10), Fr(1, 2), 1, Fr(8, 5), 2])
    t1 = rng.choice([60, 70, 80, 90, 100])
    t2 = rng.choice([10, 15, 20, 25])
    loss = rng.choice([0, 0, 10, 20, 25])
    k = Fr(100 - loss, 100)
    find = rng.choice(['T', 'T', 'm'])
    ms = lambda m: f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    ltxt = f' Потери теплоты составили {loss} % от количества теплоты, отданного горячей водой.' if loss else ' Потерями теплоты пренебречь.'
    if find == 'T':
        x = (k * m1 * t1 + m2 * t2) / (k * m1 + m2)
        q = f'В сосуд налили {ms(m1)} воды при температуре {t1} °С и {ms(m2)} воды при температуре {t2} °С.{ltxt} Какой станет температура смеси?'
        unit = '°С'
        wrong = [Fr(t1 + t2, 2), (m1 * t1 + m2 * t2) / (m1 + m2), x + 5]
        e = f'k·cm₁(t₁ − θ) = cm₂(θ − t₂) ⇒ θ = {rnd(x, 1)} °С.'
        p = P(find='T', m1=m1, t1=t1, m2=m2, t2=t2, k=k)
    else:
        T = rng.choice([30, 35, 40, 45, 50])
        if not t2 < T < t1:
            raise Retry
        x = k * m1 * (t1 - T) / (T - t2)
        q = (f'В ванну налили {ms(m1)} горячей воды при {t1} °С. Сколько холодной воды при {t2} °С нужно добавить, чтобы '
             f'температура стала {T} °С?{ltxt}')
        unit = 'кг'
        wrong = [m1 * (T - t2) / (t1 - T), m1, x * 2]
        e = f'm₂ = k·m₁(t₁ − θ)/(θ − t₂) = {rnd(x, 1)} кг.'
        p = P(find='m', m1=m1, t1=t1, m2=0, t2=t2, k=k, T=T)
    return ncard2('ph-oge-20-heat-mixing', q, x, unit, e, p, wrong)


def _solve_20ice(p):
    m, t0 = V(p, 'm'), V(p, 't0')
    f = p['case']
    if f == 'ice':
        Q = 2100 * m * (0 - t0) + 330000 * m + (4200 * m * V(p, 't2') if p.get('t2') else 0)
    else:  # пар 100 °С → вода t2
        Q = 2300000 * m + 4200 * m * (100 - V(p, 't2'))
    return rnd(Q / 1000, p['dec'])


@proto('ph-oge-20-phase-chain', 'ОГЭ', 20, 'Цепочка тепловых процессов: лёд → вода, пар → вода (сумма теплот)',
       invariant='Q = Q₁ + Q₂ (+ Q₃): нагрев льда до 0 °С, плавление, нагрев воды; или конденсация пара и остывание воды',
       varies='масса, начальная и конечная температура, направление процесса',
       answer_rule='сумма cmΔt и λm (или Lm) по участкам, константы — из таблиц КИМ',
       mistakes=['пропускают один из этапов', 'берут c воды для льда'],
       solve=_solve_20ice, kes=['2.8', '2.10', '2.12'],
       fidelity=F20(20, '2.8–2.12', 'как в банке: «лёд при −20 °С внесли…», «конденсация 2 кг пара и остывание»',
                    'все этапы процесса'))
def g_20ice(rng):
    case = rng.choice(['ice', 'ice', 'steam'])
    m = rng.choice([Fr(1, 10), Fr(1, 5), Fr(1, 4), Fr(1, 2), 1, Fr(3, 2), 2, 3])
    ms = f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    if case == 'ice':
        t0 = rng.choice([-40, -30, -25, -20, -15, -10, -5])
        t2 = rng.choice([0, 0, 10, 15, 20, 25])
        q = (f'Кусок льда массой {ms} при температуре {ru(t0)} °С внесли в тёплое помещение. Какое количество теплоты получил '
             f'лёд к моменту, когда он полностью растаял{"" if t2 == 0 else f" и образовавшаяся вода нагрелась до {t2} °С"}?')
        Q = 2100 * m * (-t0) + 330000 * m + 4200 * m * t2
        p = P(case='ice', m=m, t0=t0, t2=t2)
        wrong = [330000 * m / 1000, (2100 * m * (-t0) + 4200 * m * t2) / 1000, (4200 * m * (-t0) + 330000 * m) / 1000]
        e = f'Q = cл·m·{-t0} + λm + cв·m·{t2} = {rnd(Q / 1000, 1)} кДж.'
    else:
        t2 = rng.choice([20, 30, 40, 50, 60, 70, 80])
        q = (f'Водяной пар массой {ms} при температуре 100 °С впустили в холодную ванну; пар сконденсировался, и образовавшаяся '
             f'вода остыла до {t2} °С. Какое количество теплоты выделилось?')
        Q = 2300000 * m + 4200 * m * (100 - t2)
        p = P(case='steam', m=m, t0=0, t2=t2)
        wrong = [2300000 * m / 1000, 4200 * m * (100 - t2) / 1000, (2300000 * m - 4200 * m * (100 - t2)) / 1000]
        e = f'Q = Lm + cm(100 − {t2}) = {rnd(Q / 1000, 1)} кДж.'
    return ncard2('ph-oge-20-phase-chain', q, Q / 1000, 'кДж', e, p, wrong)


def _solve_20v(p):
    v1, v2 = V(p, 'v1'), V(p, 'v2')
    v = (v1 + v2) / 2 if p['mode'] == 'time' else 2 * v1 * v2 / (v1 + v2)
    return rnd(v, p['dec'])


@proto('ph-oge-20-avg-speed-halves', 'ОГЭ', 20, 'Средняя скорость на двух половинах пути или времени',
       invariant='υср = s/t; половины времени → (υ₁ + υ₂)/2; половины пути → 2υ₁υ₂/(υ₁ + υ₂)',
       varies='кто движется, скорости, «половина пути» или «половина времени», подъём/спуск',
       answer_rule='по определению средней скорости',
       mistakes=['для половин пути берут среднее арифметическое'],
       solve=_solve_20v, kes=['1.1', '1.2'],
       fidelity=F20(20, '1.1–1.2', 'как в банке: «первую половину времени 100 км/ч, вторую 60 км/ч», «туристы 2 и 6 км/ч»',
                    'половина пути ≠ половина времени'))
def g_20v(rng):
    mode = rng.choice(['time', 'path'])
    v1, v2 = rng.choice([(100, 60), (60, 40), (90, 60), (2, 6), (4, 6), (12, 18), (30, 60), (10, 15), (20, 30), (80, 120)])
    if rng.random() < 0.5:
        v1, v2 = v2, v1
    who = rng.choice(['Автомобиль', 'Велосипедист', 'Туристическая группа', 'Поезд', 'Катер'])
    unit = 'км/ч'
    if mode == 'time':
        q = f'{who} первую половину всего времени движения двигался со скоростью {v1} км/ч, а вторую половину — со скоростью {v2} км/ч. Определите среднюю скорость на всём пути.'
        x = Fr(v1 + v2, 2)
    else:
        q = f'{who} первую половину пути прошёл со скоростью {v1} км/ч, а вторую половину — со скоростью {v2} км/ч. Определите среднюю скорость на всём пути.'
        x = Fr(2 * v1 * v2, v1 + v2)
    if who == 'Туристическая группа':
        q = q.replace('двигался', 'двигалась').replace('прошёл', 'прошла')
    if who == 'Катер':
        q = q.replace('прошёл', 'прошёл')
    e = f'υср = s/t ⇒ {"(υ₁ + υ₂)/2" if mode == "time" else "2υ₁υ₂/(υ₁ + υ₂)"} = {rnd(x, 1)} км/ч.'
    wrong = [Fr(v1 + v2, 2) if mode == 'path' else Fr(2 * v1 * v2, v1 + v2), Fr(abs(v1 - v2)), Fr(v1 + v2)]
    return ncard2('ph-oge-20-avg-speed-halves', q, x, unit, e, P(mode=mode, v1=v1, v2=v2), wrong)


# ---------------------------------------------------------------- 21

def _solve_21col(p):
    m1, m2, v1, v2 = V(p, 'm1'), V(p, 'm2'), V(p, 'v1'), V(p, 'v2')
    u = (m1 * v1 - m2 * v2) / (m1 + m2)
    if p['find'] == 'Ek2':
        v = m2 * u * u / 2
    elif p['find'] == 'Q':
        v = m1 * v1 * v1 / 2 + m2 * v2 * v2 / 2 - (m1 + m2) * u * u / 2
    else:
        v = abs(u)
    return rnd(v, p['dec'])


@proto('ph-oge-21-collision-energy', 'ОГЭ', 21, 'Неупругое столкновение: скорость после удара, кинетическая энергия, выделившаяся теплота',
       invariant='закон сохранения импульса (с учётом направлений) + энергия: Q = Eк до − Eк после',
       varies='массы (г, кг), скорости, встречное или попутное движение, что найти',
       answer_rule='u = (m₁υ₁ ∓ m₂υ₂)/(m₁ + m₂); Eк₂ = m₂u²/2; Q = ΣEк до − (m₁+m₂)u²/2',
       mistakes=['не учитывают встречное направление', 'Q = сумма энергий до удара', 'не переводят граммы'],
       solve=_solve_21col, kes=['1.16', '1.18', '1.19'],
       fidelity=F20(21, '1.16–1.19', 'как в демоверсии 2027 №21 (100 г и 200 г, 4 и 5 м/с навстречу)', 'знак проекции'))
def g_21col(rng):
    m1 = rng.choice([Fr(1, 10), Fr(1, 5), Fr(3, 10), Fr(1, 2), 1, 2, 3])
    m2 = rng.choice([Fr(1, 10), Fr(1, 5), Fr(2, 5), Fr(1, 2), 1, 2, 4])
    v1 = rng.choice([2, 3, 4, 5, 6, 8])
    v2 = rng.choice([1, 2, 3, 4, 5])
    head = rng.random() < 0.7
    sv2 = v2 if head else -v2
    u = (m1 * v1 - m2 * sv2) / (m1 + m2)
    if u == 0:
        raise Retry
    find = rng.choice(['Ek2', 'Q', 'u'])
    who = rng.choice([('свинцовых шарика', 'шарики'), ('пластилиновых шарика', 'шарики'), ('тележки с липучками', 'тележки')])
    ms = lambda m: f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    q = (f'Два {who[0]} массами m₁ = {ms(m1)} и m₂ = {ms(m2)} движутся {"навстречу друг другу" if head else "в одном направлении"} '
         f'со скоростями υ₁ = {v1} м/с и υ₂ = {v2} м/с{"" if head else " (первый догоняет второй)"}. После удара {who[1]} движутся как одно целое. ')
    if 'тележки' in who[0]:
        q = q.replace('Два тележки', 'Две тележки').replace('первый догоняет второй', 'первая догоняет вторую')
    if find == 'Ek2':
        q += 'Какую кинетическую энергию будет иметь второе тело после удара?'
        x, unit = m2 * u * u / 2, 'Дж'
        wrong = [m2 * v2 * v2 / 2, (m1 + m2) * u * u / 2, m2 * ((m1 * v1 + m2 * sv2) / (m1 + m2)) ** 2 / 2]
    elif find == 'Q':
        q += 'Какое количество теплоты выделилось при ударе?'
        x, unit = m1 * v1 * v1 / 2 + m2 * v2 * v2 / 2 - (m1 + m2) * u * u / 2, 'Дж'
        wrong = [m1 * v1 * v1 / 2 + m2 * v2 * v2 / 2, (m1 + m2) * u * u / 2, x * 2]
    else:
        q += 'Определите модуль скорости тел после удара.'
        x, unit = abs(u), 'м/с'
        wrong = [abs((m1 * v1 + m2 * sv2) / (m1 + m2)), Fr(v1 + v2, 2), Fr(v1)]
    e = f'Проекция общей скорости u = (m₁υ₁ {"−" if head else "+"} m₂υ₂)/(m₁ + m₂) = {ru(Fr(rnd(u, 2).replace(",", ".")))} м/с; ответ: {rnd(x, 2)} {unit}.'
    return ncard2('ph-oge-21-collision-energy', q, x, unit, e, P(find=find, m1=m1, m2=m2, v1=v1, v2=sv2), wrong, dec=2)


def _solve_21bul(p):
    v1, v2, k, c = V(p, 'v1'), V(p, 'v2'), V(p, 'k'), V(p, 'c')
    return rnd(k * (v1 * v1 - v2 * v2) / (2 * c), p['dec'])


@proto('ph-oge-21-bullet-heat', 'ОГЭ', 21, 'Пуля пробивает преграду: изменение кинетической энергии → нагревание',
       invariant='часть убыли кинетической энергии идёт на нагревание пули: k·m(υ₁² − υ₂²)/2 = cmΔt (масса сокращается)',
       varies='материал пули (свинец, сталь — c из таблицы), скорости, доля энергии',
       answer_rule='Δt = k(υ₁² − υ₂²)/(2c)',
       mistakes=['берут υ₁ − υ₂ вместо разности квадратов', 'забывают долю k'],
       solve=_solve_21bul, kes=['1.19', '2.8'],
       fidelity=F20(21, '1.19, 2.8', 'как в банке: «свинцовая пуля 200 → 100 м/с…», «стальная пуля 400 м/с»',
                    'разность квадратов скоростей'))
def g_21bul(rng):
    mat, c = rng.choice([('свинцовая', 130), ('стальная', 500), ('медная', 400)])
    v1 = rng.choice([200, 300, 400, 500, 600])
    v2 = rng.choice([100, 150, 200, 250, 300])
    if v2 >= v1:
        raise Retry
    kp = rng.choice([20, 25, 40, 50, 60, 80])
    k = Fr(kp, 100)
    x = k * (v1 * v1 - v2 * v2) / (2 * c)
    obst = rng.choice(['деревянную доску', 'стенку из фанеры', 'мешок с песком'])
    q = (f'В тире {mat} пуля, имевшая скорость {v1} м/с, прошла сквозь {obst}; после этого её скорость стала {v2} м/с. '
         f'Считая, что {kp} % убыли кинетической энергии пули пошло на её нагревание, определите, на сколько градусов '
         'повысилась температура пули.')
    e = f'k·(υ₁² − υ₂²)/2 = cΔt ⇒ Δt = {sx(k)}·({v1}² − {v2}²)/(2·{c}) = {rnd(x, 1)} °С.'
    wrong = [(v1 * v1 - v2 * v2) / Fr(2 * c), k * (v1 - v2) ** 2 / (2 * c), k * (v1 * v1 - v2 * v2) / c]
    return ncard2('ph-oge-21-bullet-heat', q, x, '°С', e, P(v1=v1, v2=v2, k=k, c=c), wrong)


def _solve_21fall(p):
    h, k, c = V(p, 'h'), V(p, 'k'), V(p, 'c')
    return rnd(k * G * h / c, p['dec'])


@proto('ph-oge-21-fall-heat', 'ОГЭ', 21, 'Падение тела (молот, водопад, гиря) → нагревание',
       invariant='k·mgh = cmΔt ⇒ Δt = kgh/c (масса сокращается)',
       varies='тело (стальной молот, свинцовый шар, вода водопада), высота, доля энергии',
       answer_rule='Δt = kgh/c',
       mistakes=['забывают долю k', 'подставляют c другого вещества'],
       solve=_solve_21fall, kes=['1.19', '2.8'],
       fidelity=F20(21, '1.19, 2.8', 'как в банке: «стальной молот падает с высоты 10 м… 50 % энергии…», водопады',
                    'сокращение массы'))
def g_21fall(rng):
    what, c, gnd = rng.choice([('Стальной молот копра', 500, 'm'), ('Свинцовый шар', 130, 'm'), ('Вода водопада', 4200, 'f'),
                               ('Медная гиря', 400, 'f'), ('Чугунная баба копра', 540, 'f'), ('Латунный груз', 380, 'm')])
    h = rng.choice([5, 8, 10, 12, 15, 20, 26, 30, 40, 50, 60, 84, 100, 120])
    kp = rng.choice([20, 25, 30, 40, 50, 60, 75, 80, 100]) if 'Вода' not in what else 100
    k = Fr(kp, 100)
    x = k * G * h / c
    if 'Вода' in what:
        q = (f'Высота водопада {h} м. На сколько градусов температура воды у его основания выше, чем у вершины, если вся '
             'механическая энергия падающей воды идёт на её нагревание?')
    else:
        q = (f'{what} падает с высоты {h} м на массивную плиту и останавливается. На сколько градусов {"она" if gnd == "f" else "он"} нагреется, если на '
             f'{"её" if gnd == "f" else "его"} нагревание идёт {kp} % механической энергии?')
    e = f'k·mgh = cmΔt ⇒ Δt = {sx(k)}·10·{h}/{c} = {rnd(x, 2)} °С.'
    wrong = [G * h / Fr(c), k * h / c, k * G * h / c * 2]
    return ncard2('ph-oge-21-fall-heat', q, x, '°С', e, P(h=h, k=k, c=c), wrong, dec=2)


def _solve_21lift(p):
    m, h, U, I, eta = V(p, 'm'), V(p, 'h'), V(p, 'U'), V(p, 'I'), V(p, 'eta')
    if p['find'] == 't':
        v = m * G * h / (eta * U * I)
    elif p['find'] == 'I':
        v = m * G * h / (eta * U * V(p, 't'))
    else:
        v = m * G * h / (U * I * V(p, 't')) * 100
    return rnd(v, p['dec'])


@proto('ph-oge-21-motor-lift', 'ОГЭ', 21, 'Электродвигатель поднимает груз: КПД, время, сила тока',
       invariant='η = mgh/(UIt); подъём равномерный',
       varies='устройство (кран, транспортёр, лифт, лебёдка), масса, высота, U, I, t, η; что найти',
       answer_rule='t = mgh/(ηUI); I = mgh/(ηUt); η = mgh/(UIt)',
       mistakes=['η = UIt/(mgh)', 'не переводят проценты', 'забывают g'],
       solve=_solve_21lift, kes=['1.17', '3.10'],
       fidelity=F20(21, '1.17, 3.10', 'как в банке: «транспортёр поднимает 190 кг на 9 м за 50 с…, КПД 60 %»',
                    'полезная и затраченная работа'))
def g_21lift(rng):
    who = rng.choice(['Подъёмный кран', 'Транспортёр', 'Строительная лебёдка', 'Грузовой лифт'])
    m = rng.choice([100, 150, 190, 200, 300, 400, 500, 1000])
    h = rng.choice([5, 6, 9, 10, 12, 15, 20])
    U = rng.choice([220, 380])
    I = rng.choice([2, 4, 5, 8, 10, 12, 20])
    etap = rng.choice([50, 60, 70, 75, 80, 90])
    eta = Fr(etap, 100)
    find = rng.choice(['t', 'I', 'eta'])
    t = m * G * h / (eta * U * I)
    if find == 't':
        q = (f'{who} с электродвигателем, работающим при напряжении {U} В и силе тока {I} А, равномерно поднимает груз массой '
             f'{m} кг на высоту {h} м. КПД установки {etap} %. Сколько времени длится подъём?')
        x, unit = t, 'с'
        wrong = [m * G * h / Fr(U * I), eta * U * I / (m * G * h), t * eta * eta]
        p = P(find='t', m=m, h=h, U=U, I=I, eta=eta)
    elif find == 'I':
        tt = rng.choice([10, 20, 25, 30, 40, 50, 60])
        x = m * G * h / (eta * U * tt)
        q = (f'За {tt} с {who.lower()} поднимает с постоянной скоростью {rng.choice(["поддон с плиткой", "контейнер", "бадью с бетоном"])} массой {m} кг на {h} м. '
             f'Электродвигатель питается от сети {U} В, его КПД {etap} %. Какой ток потребляет двигатель?')
        unit = 'А'
        wrong = [m * G * h / Fr(U * tt), x * eta * eta, m * h / (eta * U * tt)]
        p = P(find='I', m=m, h=h, U=U, I=0, eta=eta, t=tt)
    else:
        tt = rng.choice([10, 20, 30, 40, 50, 60])
        x = Fr(m * G * h * 100, U * I * tt)
        if x >= 100 or x < 20:
            raise Retry
        q = (f'За {tt} с {who.lower()} поднял{"а" if who in ("Строительная лебёдка",) else ""} с постоянной скоростью {rng.choice(["поддон с плиткой", "контейнер", "бадью с бетоном", "рулоны утеплителя"])} массой {m} кг на {h} м. '
             f'Электродвигатель при этом потреблял ток {I} А при напряжении {U} В. Каков КПД установки?')
        unit = '%'
        wrong = [Fr(U * I * tt * 100, m * G * h), x / 100, Fr(m * h * 100, U * I * tt)]
        p = P(find='eta', m=m, h=h, U=U, I=I, eta=1, t=tt)
    q = q.replace('Строительная лебёдка с электродвигателем, работающим', 'Строительная лебёдка с электродвигателем, работающим')
    e = f'η = mgh/(UIt) ⇒ ответ {rnd(x, 1)} {unit}.'
    return ncard2('ph-oge-21-motor-lift', q, x, unit, e, p, wrong)


def _solve_21fuel(p):
    N, v, eta, q_, s = V(p, 'N'), V(p, 'v'), V(p, 'eta'), V(p, 'q'), V(p, 's')
    if p['find'] == 'm':
        val = N * (s / v) / (eta * q_)
    else:
        val = eta * q_ * V(p, 'm') * v / N / 1000
    return rnd(val, p['dec'])


@proto('ph-oge-21-vehicle-fuel', 'ОГЭ', 21, 'Двигатель транспорта: мощность, скорость, КПД и расход топлива',
       invariant='Aп = Nt = N·s/υ; Q = qm; η = Aп/Q',
       varies='транспорт (автомобиль, самолёт, катер, трактор), топливо (q из таблицы), N, υ, путь или масса топлива',
       answer_rule='m = N·s/(υηq); s = ηqmυ/N',
       mistakes=['забывают перевести км/ч в м/с', 'путают полезную и затраченную энергию'],
       solve=_solve_21fuel, kes=['1.17', '2.13'],
       fidelity=F20(21, '1.17, 2.13', 'как в банке: «самолёт … 250 км/ч … керосин», «автомобиль 100 км/ч … бензин»',
                    'перевод единиц скорости и мощности'))
def g_21fuel(rng):
    veh, fuel, fg = rng.choice([('Автомобиль', 'бензин', 'бензина'), ('Катер', 'бензин', 'бензина'),
                                ('Самолёт', 'керосин', 'керосина'), ('Трактор', 'дизельное топливо', 'дизельного топлива')])
    q_ = Q_FUEL[fuel]
    vk = rng.choice([36, 54, 72, 90, 108]) if veh != 'Самолёт' else rng.choice([180, 216, 252, 360])
    v = Fr(vk * 1000, 3600)
    Nk = rng.choice([20, 23, 40, 46, 60, 92]) if veh != 'Самолёт' else rng.choice([500, 1000, 2000])
    N = Nk * 1000
    etap = rng.choice([20, 25, 30, 40])
    eta = Fr(etap, 100)
    find = rng.choice(['m', 's'])
    if find == 'm':
        sk = rng.choice([10, 20, 50, 100, 200, 500])
        s = sk * 1000
        x = N * (s / v) / (eta * q_)
        q = (f'{veh} движется со средней скоростью {vk} км/ч; двигатель развивает полезную мощность {Nk} кВт при КПД {etap} %. '
             f'Какую массу {fg} израсходует двигатель на пути {sk} км?')
        unit = 'кг'
        wrong = [N * (s / v) / q_, N * s / (eta * q_), x * eta]
        p = P(find='m', N=N, v=v, eta=eta, q=q_, s=s, m=0)
    else:
        mf = rng.choice([5, 10, 20, 30, 50, 100])
        x = eta * q_ * mf * v / N / 1000
        q = (f'{veh} движется со средней скоростью {vk} км/ч; двигатель развивает полезную мощность {Nk} кВт при КПД {etap} %. '
             f'Какой путь пройдёт {veh.lower()}, израсходовав {mf} кг {fg}? Ответ дайте в километрах.')
        unit = 'км'
        wrong = [q_ * mf * v / N / 1000, eta * q_ * mf / N / 1000, x * 3600 / 1000]
        p = P(find='s', N=N, v=v, eta=eta, q=q_, s=0, m=mf)
    e = f'υ = {sx(v)} м/с; ηqm = N·s/υ ⇒ ответ {rnd(x, 1)} {unit}.'
    return ncard2('ph-oge-21-vehicle-fuel', q, x, unit, e, p, wrong)


# ---------------------------------------------------------------- 22

def _solve_22k(p):
    m, dt, eta, P_ = V(p, 'm'), V(p, 'dt'), V(p, 'eta'), V(p, 'P')
    if p['find'] == 't':
        v = 4200 * m * dt / (eta * P_) / 60
    else:
        v = eta * P_ * V(p, 't') / (4200 * m)
    return rnd(v, p['dec'])


@proto('ph-oge-22-kettle', 'ОГЭ', 22, 'Электрочайник/кипятильник: время нагревания или изменение температуры с учётом КПД',
       invariant='ηPt = cmΔt; P = UI или U²/R',
       varies='прибор, мощность (или U и R), КПД, масса воды, начальная температура, что найти',
       answer_rule='t = cmΔt/(ηP); Δt = ηPt/(cm)',
       mistakes=['не учитывают КПД', 'Δt считают до 100 от 0', 'минуты ↔ секунды'],
       solve=_solve_22k, kes=['2.8', '3.10'],
       fidelity=F20(22, '2.8, 3.10', 'как в банке: «электрочайник с КПД 60 %, 0,6 кг воды при 20 °С, 220 В…»',
                    'КПД и перевод времени'))
def g_22k(rng):
    dev = rng.choice(['Электрочайник', 'Кипятильник', 'Электроплитка с кастрюлей', 'Водонагреватель'])
    by = rng.choice(['P', 'UR'])
    if by == 'P':
        P_ = rng.choice([500, 600, 800, 1000, 1200, 1500, 2000, 2400])
        ptxt = f'мощностью {P_} Вт'
    else:
        U, R = rng.choice([(220, 22), (220, 44), (220, 55), (220, Fr(121, 10)), (120, 12), (220, 40)])
        P_ = Fr(U * U) / R
        ptxt = f'с нагревательным элементом сопротивлением {sx(R)} Ом, включённый в сеть напряжением {U} В'
    m = rng.choice([Fr(1, 2), Fr(3, 5), Fr(3, 4), 1, Fr(3, 2), 2])
    t1 = rng.choice([10, 15, 20, 25])
    etap = rng.choice([60, 70, 75, 80, 84, 90, 100])
    eta = Fr(etap, 100)
    find = rng.choice(['t', 'dt'])
    ms = f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    etxt = f' КПД прибора {etap} %.' if etap < 100 else ' Потерями энергии пренебречь.'
    if find == 't':
        dt = 100 - t1
        x = 4200 * m * dt / (eta * P_) / 60
        q = f'{dev} {ptxt} нагревает {ms} воды от {t1} °С до кипения.{etxt} Сколько времени займёт нагревание? Ответ дайте в минутах.'
        unit = 'мин.'
        wrong = [4200 * m * dt / P_ / 60, 4200 * m * dt / (eta * P_), 4200 * m * 100 / (eta * P_) / 60]
        p = P(find='t', m=m, dt=dt, eta=eta, P=P_)
    else:
        tt = rng.choice([60, 120, 180, 240, 300])
        x = eta * P_ * tt / (4200 * m)
        if t1 + x >= 100:
            raise Retry
        q = f'{dev} {ptxt} работал {tt // 60} мин., нагревая {ms} воды.{etxt} На сколько градусов нагрелась вода?'
        unit = '°С'
        wrong = [P_ * tt / (4200 * m), eta * P_ * tt / 60 / (4200 * m), x + t1]
        p = P(find='dt', m=m, dt=0, eta=eta, P=P_, t=tt)
    q = q.replace('Электроплитка с кастрюлей мощностью', 'Электроплитка мощностью').replace('Электроплитка с кастрюлей с', 'Электроплитка с')
    q = q.replace('Электроплитка мощностью', 'Электроплитка мощностью')
    if dev.startswith('Электроплитка'):
        q = q.replace('работал', 'работала').replace('включённый', 'включённая')
    e = f'ηPt = cmΔt, P = {sx(P_)} Вт ⇒ ответ {rnd(x, 1)} {unit}.'
    return ncard2('ph-oge-22-kettle', q, x, unit, e, p, wrong)


def _solve_22cal(p):
    U, R, t, loss = V(p, 'U'), V(p, 'R'), V(p, 't'), V(p, 'loss')
    mc, mw = V(p, 'mc'), V(p, 'mw')
    Q = U * U / R * t * (1 - loss)
    return rnd(Q / (920 * mc + 4200 * mw), p['dec'])


@proto('ph-oge-22-calorimeter', 'ОГЭ', 22, 'Спираль в калориметре с водой: нагрев калориметра и воды с учётом потерь',
       invariant='(1 − k)·U²t/R = (cк mк + cв mв)Δt; калориметр алюминиевый (c = 920)',
       varies='массы калориметра и воды, R, U, время, потери',
       answer_rule='Δt = (1 − k)U²t/(R(cк mк + cв mв))',
       mistakes=['не учитывают нагрев калориметра', 'потери не вычитают', 'минуты ↔ секунды'],
       solve=_solve_22cal, kes=['2.8', '2.9', '3.10'],
       fidelity=F20(22, '2.8–3.10', 'как в демоверсии 2027 №22 (100 г Al, 200 г воды, 2 Ом, 12 В, 5 мин, 25 %)',
                    'теплоёмкость калориметра + потери'))
def g_22cal(rng):
    mc = rng.choice([Fr(1, 20), Fr(1, 10), Fr(3, 20), Fr(1, 5)])
    mw = rng.choice([Fr(1, 10), Fr(3, 25), Fr(1, 5), Fr(1, 4), Fr(3, 10)])
    R = rng.choice([1, 2, 3, 4, 5])
    U = rng.choice([6, 9, 10, 12])
    mins = rng.choice([2, 3, 4, 5, 10])
    lossp = rng.choice([0, 10, 20, 25, 30])
    loss = Fr(lossp, 100)
    x = Fr(U * U, R) * mins * 60 * (1 - loss) / (920 * mc + 4200 * mw)
    if x > 60:
        raise Retry
    q = (f'Ученица собрала установку: алюминиевый стакан-калориметр ({sx(mc * 1000)} г), в нём {sx(mw * 1000)} г воды и '
         f'проволочный нагреватель сопротивлением {R} Ом, питаемый от источника {U} В. Нагреватель работал {mins} мин. '
         f'{"В окружающую среду рассеялось " + str(lossp) + " % выделившейся энергии." if lossp else "Рассеянием энергии в окружающую среду пренебречь."} '
         'Найдите, на сколько градусов повысилась температура стакана с водой.')
    e = f'(1 − k)U²t/R = (920·mк + 4200·mв)Δt ⇒ Δt = {rnd(x, 1)} °С.'
    wrong = [Fr(U * U, R) * mins * 60 * (1 - loss) / (4200 * mw), Fr(U * U, R) * mins * 60 / (920 * mc + 4200 * mw), x * 2]
    return ncard2('ph-oge-22-calorimeter', q, x, '°С', e, P(U=U, R=R, t=mins * 60, loss=loss, mc=mc, mw=mw), wrong)


def _solve_22two(p):
    P1 = V(p, 'P1')
    Pt = 2 * P1 if p['conn'] == 'par' else P1 / 2
    v = 4200 * V(p, 'm') * V(p, 'dt') / (V(p, 'eta') * Pt) / 60
    return rnd(v, p['dec'])


@proto('ph-oge-22-two-heaters', 'ОГЭ', 22, 'Два одинаковых нагревателя: последовательное и параллельное включение',
       invariant='каждый нагреватель рассчитан на напряжение сети (мощность P₁); последовательно — P₁/2, параллельно — 2P₁',
       varies='мощность нагревателя, масса воды, Δt, КПД, способ соединения',
       answer_rule='t = cmΔt/(ηPобщ)',
       mistakes=['при последовательном соединении складывают мощности', 'не учитывают КПД'],
       solve=_solve_22two, kes=['2.8', '3.9', '3.10'],
       fidelity=F20(22, '2.8, 3.9, 3.10', 'как в банке: «два одинаковых нагревателя по 600 Вт…»', 'мощность при '
                    'последовательном соединении'))
def g_22two(rng):
    P1 = rng.choice([400, 500, 600, 800, 1000])
    m = rng.choice([Fr(1, 2), 1, Fr(3, 2), 2, 3])
    dt = rng.choice([20, 30, 40, 50, 60, 80])
    etap = rng.choice([70, 80, 90, 100])
    eta = Fr(etap, 100)
    conn = rng.choice(['ser', 'par'])
    x = 4200 * m * dt / (eta * (2 * P1 if conn == 'par' else Fr(P1, 2))) / 60
    q = (f'Имеются два одинаковых электрических нагревателя мощностью {P1} Вт каждый (при включении в сеть по отдельности). '
         f'Их соединили {"параллельно" if conn == "par" else "последовательно"} и включили в ту же сеть. Сколько минут '
         f'потребуется, чтобы нагреть {sx(m)} кг воды на {dt} °С?{" КПД нагревателей " + str(etap) + " %." if etap < 100 else " Потерями энергии пренебречь."}')
    e = f'Pобщ = {"2P₁" if conn == "par" else "P₁/2"}; t = cmΔt/(ηPобщ) = {rnd(x, 1)} мин.'
    wrong = [4200 * m * dt / (eta * 2 * P1) / 60 if conn == 'ser' else 4200 * m * dt / (eta * Fr(P1, 2)) / 60,
             4200 * m * dt / (eta * P1) / 60, x * 60]
    return ncard2('ph-oge-22-two-heaters', q, x, 'мин.', e, P(P1=P1, m=m, dt=dt, eta=eta, conn=conn), wrong)


def _solve_22fur(p):
    m, t0, eta, P_ = V(p, 'm'), V(p, 't0'), V(p, 'eta'), V(p, 'P')
    Q = V(p, 'c') * m * (V(p, 'tm') - t0) + V(p, 'lam') * m
    return rnd(Q / (eta * P_) / 60, p['dec'])


@proto('ph-oge-22-furnace', 'ОГЭ', 22, 'Электропечь нагревает и плавит металл: время с учётом КПД',
       invariant='ηPt = cm(tпл − t₀) + λm; константы — справочные данные КИМ',
       varies='металл (сталь, алюминий, медь, олово, свинец), масса, начальная температура, мощность, КПД',
       answer_rule='t = (cmΔt + λm)/(ηP)',
       mistakes=['забывают плавление', 'не учитывают КПД'],
       solve=_solve_22fur, kes=['2.8', '2.12', '3.10'],
       fidelity=F20(22, '2.8, 2.12, 3.10', 'как в банке: «в электропечи мощностью 100 кВт расплавили слиток стали…»',
                    'два этапа: нагрев и плавление'))
def g_22fur(rng):
    met = rng.choice(['сталь', 'алюминий', 'медь', 'олово', 'свинец'])
    c, lam, tm = C_HEAT[met], LAMBDA[met], T_MELT[met]
    m = rng.choice([1, 2, 5, 10, 50, 100, 200, 500])
    t0 = rng.choice([20, 25, 30])
    Pk = rng.choice([5, 10, 20, 50, 100])
    etap = rng.choice([50, 60, 70, 75, 80, 90])
    eta = Fr(etap, 100)
    Q = c * m * (tm - t0) + lam * m
    x = Q / (eta * Pk * 1000) / 60
    if x < 1 or x > 600:
        raise Retry
    q = (f'В электропечи мощностью {Pk} кВт нагрели от {t0} °С до температуры плавления и полностью расплавили слиток: '
         f'{met}, масса {m} кг. КПД печи {etap} %. Сколько минут длился процесс?')
    e = f'Q = cmΔt + λm = {sx(Q)} Дж; t = Q/(ηP) = {rnd(x, 1)} мин.'
    wrong = [Q / (Pk * 1000) / 60, (c * m * (tm - t0)) / (eta * Pk * 1000) / 60, Q / (eta * Pk * 1000)]
    return ncard2('ph-oge-22-furnace', q, x, 'мин.', e, P(m=m, t0=t0, eta=eta, P=Pk * 1000, c=c, lam=lam, tm=tm), wrong)


def _solve_22fb(p):
    mf, q_, eta, mw, t1 = V(p, 'mf'), V(p, 'q'), V(p, 'eta'), V(p, 'mw'), V(p, 't1')
    rest = eta * q_ * mf - 4200 * mw * (100 - t1)
    return rnd(rest / 2300000 * 1000, p['dec'])


@proto('ph-oge-22-fuel-boil', 'ОГЭ', 22, 'Сжигание топлива: нагрев воды до кипения и частичное испарение',
       invariant='ηqmт = cmв(100 − t₁) + Lmп; найти массу образовавшегося пара',
       varies='топливо (q из таблицы КИМ), масса топлива, масса воды, начальная температура, КПД',
       answer_rule='mп = (ηqmт − cmв(100 − t₁))/L',
       mistakes=['забывают нагрев до кипения', 'КПД не учитывают'],
       solve=_solve_22fb, kes=['2.8', '2.10', '2.13'],
       fidelity=F20(22, '2.8, 2.10, 2.13', 'как в банке: «сжигая 40 г керосина, воду массой 2,5 кг нагревают от 20 °С до 100 °С '
                    'и частично переводят в пар»', 'два этапа + КПД'))
def g_22fb(rng):
    fuel, fg = rng.choice([('керосин', 'керосина'), ('бензин', 'бензина'), ('спирт', 'спирта'), ('природный газ', 'природного газа')])
    q_ = Q_FUEL[fuel]
    mf = Fr(rng.choice([20, 30, 40, 50, 60, 80, 100]), 1000)
    mw = rng.choice([Fr(1, 2), 1, Fr(3, 2), 2, Fr(5, 2)])
    t1 = rng.choice([10, 15, 20, 25])
    etap = rng.choice([40, 50, 60, 70, 100])
    eta = Fr(etap, 100)
    rest = eta * q_ * mf - 4200 * mw * (100 - t1)
    if rest <= 0:
        raise Retry
    x = rest / 2300000 * 1000
    if x > mw * 1000:
        raise Retry
    q = (f'При сжигании {sx(mf * 1000)} г {fg} воду массой {sx(mw)} кг нагрели от {t1} °С до кипения и часть её перевели в пар. '
         f'{"КПД нагревателя " + str(etap) + " %." if etap < 100 else "Потерями теплоты пренебречь."} Сколько граммов воды превратилось в пар?')
    e = f'ηqmт = cmв(100 − t₁) + Lmп ⇒ mп = {rnd(x, 1)} г.'
    wrong = [eta * q_ * mf / 2300000 * 1000, (q_ * mf - 4200 * mw * (100 - t1)) / 2300000 * 1000, x / 1000]
    return ncard2('ph-oge-22-fuel-boil', q, x, 'г', e, P(mf=mf, q=q_, eta=eta, mw=mw, t1=t1), wrong)


def _solve_21air(p):
    m, h, v = V(p, 'm'), V(p, 'h'), V(p, 'v')
    if p['mode'] == 'fall':
        val = m * G * h - m * v * v / 2
    else:
        val = m * v * v / 2 - m * G * h
    return rnd(val, p['dec'])


@proto('ph-oge-21-air-resistance', 'ОГЭ', 21, 'Работа силы сопротивления воздуха (закон изменения механической энергии)',
       invariant='|Aсопр| = убыль механической энергии: mgh − mυ²/2 (падение) или mυ₀²/2 − mgh (бросок вверх)',
       varies='тело (мяч, камень, сосулька, ядро), масса (г/кг), высота, скорость, падение/бросок вверх',
       answer_rule='A = Eмех1 − Eмех2',
       mistakes=['считают A = mgh', 'не переводят граммы'],
       solve=_solve_21air, kes=['1.17', '1.19'],
       fidelity=F20(21, '1.17, 1.19', 'как в банке: «с высоты 100 м мяч массой 2 кг падает…», «тело 2 кг с 20 м, скорость 14 м/с»',
                    'механическая энергия не сохраняется'))
def g_21air(rng):
    mode = rng.choice(['fall', 'up'])
    who, ms_ = rng.choice([('Мяч', [Fr(2, 5), Fr(1, 2)]), ('Камень', [1, 2, 3]), ('Снежок', [Fr(1, 5)]),
                           ('Резиновый мяч', [Fr(1, 4), Fr(1, 2)]), ('Ядро', [4, 5])])
    m = rng.choice(ms_)
    ms = f'{sx(m * 1000)} г' if m < 1 else f'{sx(m)} кг'
    if mode == 'fall':
        h = rng.choice([10, 15, 20, 25, 30, 40, 50, 100])
        v = rng.choice([8, 10, 12, 14, 15, 16, 18, 20, 25, 30])
        if v * v >= 20 * h:
            raise Retry
        x = m * G * h - m * v * v / 2
        place = rng.choice(['с крыши многоэтажного дома', 'с вершины скалы', 'с воздушного шара, зависшего над полем', 'с моста'])
        q = (f'{who} массой {ms} выпустили из рук {place} на высоте {h} м над землёй. Перед ударом о землю скорость тела '
             f'составила {v} м/с. Какую по модулю работу совершила за время полёта сила сопротивления воздуха?')
    else:
        v = rng.choice([10, 12, 15, 20, 25])
        h = rng.choice([3, 4, 5, 6, 8, 10, 12, 15, 20, 25])
        if 20 * h >= v * v:
            raise Retry
        x = m * v * v / 2 - m * G * h
        q = (f'{who} массой {ms} подбросили вертикально вверх, сообщив скорость {v} м/с; наивысшая точка подъёма оказалась '
             f'на высоте {h} м над точкой броска. Какую по модулю работу совершила при подъёме сила сопротивления воздуха?')
    e = f'|A| = изменение механической энергии = {rnd(x, 1)} Дж.'
    wrong = [m * G * h, m * v * v / 2, x * 2]
    return ncard2('ph-oge-21-air-resistance', q, x, 'Дж', e, P(mode=mode, m=m, h=h, v=v), wrong)


def _solve_21aw(p):
    rho, Vb, h, rl = V(p, 'rho'), V(p, 'V'), V(p, 'h'), V(p, 'rl')
    F_ = (rho - rl) * G * Vb
    return rnd(F_ * h if p['find'] == 'A' else F_, p['dec'])


@proto('ph-oge-21-underwater-lift', 'ОГЭ', 21, 'Подъём тела в воде: сила и работа с учётом выталкивающей силы',
       invariant='F = mg − Fa = (ρт − ρж)gV; A = Fh при равномерном подъёме под водой',
       varies='тело (камень, якорь, чугунная деталь, бетонный блок), объём, глубина, жидкость, что найти',
       answer_rule='F = (ρт − ρж)gV; A = (ρт − ρж)gVh',
       mistakes=['забывают выталкивающую силу', 'берут плотность тела вместо жидкости в Fa'],
       solve=_solve_21aw, kes=['1.17', '1.23'],
       fidelity=F20(21, '1.17, 1.23', 'как в банке: «какую минимальную работу необходимо совершить для равномерного '
                    'вертикального перемещения под водой…»', 'учёт выталкивающей силы'))
def g_21aw(rng):
    body, mat = rng.choice([('гранитную плиту', 'гранит'), ('чугунный якорь', 'чугун'), ('бетонный блок', 'бетон'),
                            ('стальную болванку', 'сталь'), ('мраморную колонну', 'мрамор')])
    rho = {'гранит': 2600, 'чугун': 7000, 'бетон': 2300, 'сталь': 7800, 'мрамор': 2700}[mat]
    Vb = rng.choice([Fr(1, 100), Fr(2, 100), Fr(5, 100), Fr(1, 10), Fr(1, 5), Fr(1, 2)])
    liq = rng.choice([('воды', 1000), ('морской воды', 1030)])
    h = rng.choice([2, 3, 5, 8, 10, 12])
    find = rng.choice(['F', 'A'])
    Fv = (rho - liq[1]) * G * Vb
    if find == 'F':
        q = (f'Какую силу нужно приложить, чтобы удерживать под водой ({liq[0]}) {body} объёмом {sx(Vb)} м³? Плотность '
             f'материала {rho} кг/м³.')
        x, unit = Fv, 'Н'
    else:
        q = (f'Какую минимальную работу нужно совершить, чтобы равномерно поднять {body} объёмом {sx(Vb)} м³ в толще '
             f'{liq[0]} на {h} м (не вынимая из воды)? Плотность материала {rho} кг/м³.')
        x, unit = Fv * h, 'Дж'
    e = f'F = (ρт − ρж)gV = {sx(Fv)} Н' + (f'; A = Fh = {rnd(x, 1)} Дж.' if find == 'A' else '.')
    wrong = [rho * G * Vb * (h if find == 'A' else 1), liq[1] * G * Vb * (h if find == 'A' else 1), x * 2]
    return ncard2('ph-oge-21-underwater-lift', q, x, unit, e, P(find=find, rho=rho, V=Vb, h=h, rl=liq[1]), wrong)
